import React, { useState, useEffect } from 'react';
import { db } from './services/database';
import { Sidebar } from './components/Sidebar';
import { DashboardPage } from './pages/DashboardPage';
import { ProjectsPage } from './pages/ProjectsPage';
import { StudentsPage } from './pages/StudentsPage';
import { TeachersPage } from './pages/TeachersPage';
import { SettingsPage } from './pages/SettingsPage';
import { ReportsPage } from './pages/ReportsPage';
import { UsersPage } from './pages/UsersPage';
import { MenuIcon, XIcon } from './components/Icons';
import { useAuth } from './contexts/AuthContext';
import { LoginPage } from './pages/LoginPage';
import { StudentProjectViewPage } from './pages/StudentProjectViewPage';

type Page = 'dashboard' | 'projects' | 'students' | 'teachers' | 'settings' | 'reports' | 'users';

const pageLabels: Record<Page, string> = {
    dashboard: 'Panel Principal',
    projects: 'Proyectos',
    students: 'Estudiantes',
    teachers: 'Docentes',
    settings: 'Configuración',
    reports: 'Reportes',
    users: 'Usuarios',
};

const App: React.FC = () => {
  const { isAuthenticated, logout, isStudent } = useAuth();
  const [currentPage, setCurrentPage] = useState<Page>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isPublicReportsView, setIsPublicReportsView] = useState(false);

  useEffect(() => {
    db.initializeDB();
  }, []);

  // Si el usuario elige ver reportes de forma pública
  if (isPublicReportsView && !isAuthenticated) {
      return (
          <div className="min-h-screen bg-gray-100 p-4 md:p-8">
              <div className="max-w-7xl mx-auto">
                <header className="mb-6 flex justify-between items-center bg-white p-4 rounded-lg shadow-sm">
                    <img src="https://axis.uninunez.edu.co/images/uninunez/vm/logoqteal.svg" alt="Logo Uninúñez" className="h-12 object-contain"/>
                    <button 
                        onClick={() => setIsPublicReportsView(false)}
                        className="text-uninunez-teal font-bold hover:underline"
                    >
                        &larr; Volver al Inicio de Sesión
                    </button>
                </header>
                <ReportsPage isPublicView={true} />
              </div>
          </div>
      );
  }

  if (!isAuthenticated) {
    return <LoginPage onOpenPublicReports={() => setIsPublicReportsView(true)} />;
  }

  if (isStudent) {
    return <StudentProjectViewPage />;
  }

  const renderPage = () => {
    switch (currentPage) {
      case 'dashboard':
        return <DashboardPage />;
      case 'projects':
        return <ProjectsPage />;
      case 'students':
        return <StudentsPage />;
      case 'teachers':
        return <TeachersPage />;
      case 'settings':
        return <SettingsPage />;
      case 'reports':
        return <ReportsPage isPublicView={false} />;
      case 'users':
        return <UsersPage />;
      default:
        return <DashboardPage />;
    }
  };

  const handlePageChange = (page: Page) => {
    setCurrentPage(page);
    if (window.innerWidth < 768) {
      setIsSidebarOpen(false);
    }
  }

  return (
    <div className="flex h-screen bg-gray-100 font-sans">
      <Sidebar 
        currentPage={currentPage} 
        onNavigate={handlePageChange}
        isOpen={isSidebarOpen}
        setIsOpen={setIsSidebarOpen}
      />
      <div className="flex-1 flex flex-col overflow-hidden">
        <header className="flex justify-between items-center p-4 bg-white border-b">
           <div className="flex items-center">
             <button 
                className="md:hidden mr-4 text-gray-500 hover:text-gray-600 focus:outline-none focus:ring-2 focus:ring-primary-500"
                onClick={() => setIsSidebarOpen(!isSidebarOpen)}
              >
                {isSidebarOpen ? <XIcon className="h-6 w-6" /> : <MenuIcon className="h-6 w-6" />}
              </button>
              <div className="text-xl font-semibold text-gray-700">
                {pageLabels[currentPage]}
              </div>
          </div>
          <button
            onClick={logout}
            className="px-4 py-2 text-sm bg-gray-200 text-gray-800 rounded-md hover:bg-gray-300 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-400"
          >
            Cerrar Sesión
          </button>
        </header>
        <main className="flex-1 overflow-x-hidden overflow-y-auto bg-gray-100 p-4 md:p-6">
          {renderPage()}
        </main>
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { HomeIcon, ProjectIcon, StudentIcon, TeacherIcon, SettingsIcon, ReportIcon, UserAdminIcon } from './Icons';
import { useAuth } from '../contexts/AuthContext';

type Page = 'dashboard' | 'projects' | 'students' | 'teachers' | 'settings' | 'reports' | 'users';

interface SidebarProps {
  currentPage: Page;
  onNavigate: (page: Page) => void;
  isOpen: boolean;
  setIsOpen: (isOpen: boolean) => void;
}

const NavItem: React.FC<{
  icon: React.ReactNode;
  label: string;
  isActive: boolean;
  onClick: () => void;
}> = ({ icon, label, isActive, onClick }) => {
  return (
    <a
      href="#"
      onClick={(e) => {
        e.preventDefault();
        onClick();
      }}
      className={`flex items-center px-4 py-3 text-sm font-semibold transition-all duration-200 ease-in-out border-l-4 ${
        isActive
          ? 'bg-uninunez-orange text-white border-white'
          : 'text-gray-300 border-transparent hover:bg-uninunez-ash hover:text-white'
      }`}
    >
      <div className={`${isActive ? 'text-white' : 'text-uninunez-orangeLight'}`}>
        {icon}
      </div>
      <span className="ml-4 font-display uppercase tracking-wider text-[11px]">{label}</span>
    </a>
  );
};

export const Sidebar: React.FC<SidebarProps> = ({ currentPage, onNavigate, isOpen, setIsOpen }) => {
    const { user } = useAuth();
    const navItems: { page: Page; label: string; icon: React.ReactNode; adminOnly?: boolean }[] = [
        { page: 'dashboard', label: 'Inicio', icon: <HomeIcon className="h-5 w-5" /> },
        { page: 'projects', label: 'Proyectos', icon: <ProjectIcon className="h-5 w-5" /> },
        { page: 'students', label: 'Estudiantes', icon: <StudentIcon className="h-5 w-5" /> },
        { page: 'teachers', label: 'Docentes', icon: <TeacherIcon className="h-5 w-5" /> },
        { page: 'reports', label: 'Informes', icon: <ReportIcon className="h-5 w-5" /> },
        { page: 'users', label: 'Seguridad', icon: <UserAdminIcon className="h-5 w-5" />, adminOnly: true },
        { page: 'settings', label: 'Maestros', icon: <SettingsIcon className="h-5 w-5" /> },
    ];

  return (
    <>
      <div className={`fixed inset-0 z-20 bg-black bg-opacity-60 transition-opacity md:hidden ${isOpen ? 'block' : 'hidden'}`} onClick={() => setIsOpen(false)}></div>
      <div className={`fixed inset-y-0 left-0 z-30 w-64 bg-uninunez-onix shadow-2xl transform ${isOpen ? 'translate-x-0' : '-translate-x-full'} transition-transform duration-300 ease-in-out md:relative md:translate-x-0 md:flex md:flex-shrink-0`}>
        <div className="flex flex-col h-full w-full">
           <div className="flex flex-col items-center justify-center p-6 bg-white border-b-4 border-uninunez-orange">
            <img 
              src="https://axis.uninunez.edu.co/images/uninunez/vm/logoqteal.svg" 
              alt="Logo Uninúñez" 
              className="h-20 object-contain"
            />
          </div>
          <nav className="flex-1 mt-4 space-y-1">
            {navItems.map(item => (
                (!item.adminOnly || user?.username === 'admin') && (
                    <NavItem 
                        key={item.page}
                        icon={item.icon}
                        label={item.label}
                        isActive={currentPage === item.page}
                        onClick={() => onNavigate(item.page)}
                    />
                )
            ))}
          </nav>
          <div className="p-4 bg-uninunez-ash bg-opacity-20 border-t border-uninunez-ash">
             <div className="text-[10px] text-gray-400 font-bold uppercase tracking-widest text-center">
                UNINÚÑEZ v2.0
             </div>
          </div>
        </div>
      </div>
    </>
  );
};

import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { db, isSupabaseConfigured } from '../services/database';
import { Teacher } from '../types';

interface LoginPageProps {
    onOpenPublicReports: () => void;
}

export const LoginPage: React.FC<LoginPageProps> = ({ onOpenPublicReports }) => {
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [selectedUsername, setSelectedUsername] = useState('');
    const [password, setPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isFetching, setIsFetching] = useState(true);
    const [error, setError] = useState('');
    const [dbConnected, setDbConnected] = useState<boolean | null>(null);
    const { login } = useAuth();

    const checkConnection = async () => {
        setIsFetching(true);
        setError('');

        // Verificamos conexión (Supabase o LocalStorage)
        try {
            const connected = await db.checkConnection();
            setDbConnected(connected);
            const data = await db.getTeachers();
            setTeachers(data);
        } catch (err) {
            setError('Error al conectar con la base de datos institucional.');
            setDbConnected(false);
        } finally {
            setIsFetching(false);
        }
    };

    useEffect(() => {
        checkConnection();
    }, []);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedUsername) {
            setError('Por favor, selecciona tu nombre de la lista oficial.');
            return;
        }
        setError('');
        setIsLoading(true);
        try {
            const success = await login(selectedUsername, password);
            if (!success) {
                if (selectedUsername === 'admin') {
                    setError('Clave de administrador incorrecta. Intenta con las credenciales de sistemas.');
                } else {
                    setError('Credenciales incorrectas. La contraseña es su número de documento.');
                }
            }
        } catch (err) {
            setError('Ocurrió un error en el protocolo de autenticación.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="flex items-center justify-center min-h-screen bg-gray-50 p-4 font-sans relative overflow-hidden">
            {/* Elementos decorativos de marca */}
            <div className="absolute top-0 left-0 w-full h-2 bg-uninunez-orange"></div>
            <div className="absolute -bottom-24 -right-24 w-64 h-64 bg-uninunez-teal rounded-full opacity-10"></div>
            <div className="absolute -top-24 -left-24 w-64 h-64 bg-uninunez-orange rounded-full opacity-10"></div>

            <div className="w-full max-w-md space-y-6 bg-white p-10 rounded-2xl shadow-2xl relative z-10 border border-gray-100">
                <div className="absolute top-4 right-6">
                    <span className={`inline-flex items-center px-2 py-1 rounded text-[9px] font-bold uppercase tracking-wider ${dbConnected ? 'bg-uninunez-teal text-white' : 'bg-red-500 text-white'}`}>
                        {dbConnected === null ? 'Verificando...' : dbConnected ? (isSupabaseConfigured ? 'CLOUD SYNC' : 'LOCAL DB') : 'OFFLINE'}
                    </span>
                </div>

                <div className="text-center">
                    <img 
                        src="https://axis.uninunez.edu.co/images/uninunez/vm/logoqteal.svg" 
                        alt="Logo Uninúñez" 
                        className="h-24 mx-auto mb-6 object-contain"
                    />
                    <h1 className="text-2xl font-extrabold text-uninunez-onix font-display uppercase tracking-tight">Gestor de Proyectos</h1>
                    <div className="w-12 h-1 bg-uninunez-orange mx-auto mt-2"></div>
                </div>

                <form className="mt-8 space-y-5" onSubmit={handleSubmit}>
                    <div className="space-y-4">
                        <div>
                            <label className="block text-[10px] font-bold text-uninunez-ash uppercase tracking-widest mb-1.5 ml-1">Identificación de Usuario</label>
                            <select
                                required
                                value={selectedUsername}
                                onChange={(e) => setSelectedUsername(e.target.value)}
                                disabled={isFetching}
                                className="block w-full px-4 py-3 border border-gray-200 rounded-xl shadow-sm focus:ring-2 focus:ring-uninunez-orange focus:border-uninunez-orange sm:text-sm bg-gray-50 transition-all font-medium"
                            >
                                <option value="">-- Seleccione su nombre --</option>
                                <option value="admin">ADMINISTRADOR DEL SISTEMA</option>
                                {teachers.map(t => (
                                    <option key={t.id} value={t.name}>{t.name}</option>
                                ))}
                            </select>
                        </div>
                        <div>
                            <label className="block text-[10px] font-bold text-uninunez-ash uppercase tracking-widest mb-1.5 ml-1">Contraseña Institucional</label>
                            <input
                                type="password"
                                required
                                value={password}
                                onChange={(e) => setPassword(e.target.value)}
                                className="block w-full px-4 py-3 border border-gray-200 rounded-xl shadow-sm focus:ring-2 focus:ring-uninunez-orange focus:border-uninunez-orange sm:text-sm bg-gray-50 transition-all font-medium"
                                placeholder="Cédula"
                            />
                        </div>
                    </div>

                    {error && (
                        <div className="bg-red-50 p-4 rounded-xl border border-red-100 animate-pulse">
                            <p className="text-xs text-red-600 font-bold leading-tight">{error}</p>
                        </div>
                    )}

                    <div className="space-y-4 pt-4">
                        <button
                            type="submit"
                            disabled={isLoading || isFetching}
                            className={`w-full flex justify-center py-4 px-4 border border-transparent text-xs font-extrabold rounded-xl text-white shadow-xl transition-all transform hover:-translate-y-1 active:scale-95 ${isLoading ? 'bg-gray-400' : 'bg-uninunez-orange hover:bg-uninunez-orangeLight'} uppercase tracking-widest font-display`}
                        >
                            {isLoading ? 'AUTENTICANDO...' : 'INGRESAR AL SISTEMA'}
                        </button>

                        <button
                            type="button"
                            onClick={onOpenPublicReports}
                            className="w-full flex justify-center py-3 px-4 border-2 border-uninunez-teal text-xs font-bold rounded-xl text-uninunez-teal bg-transparent hover:bg-uninunez-teal hover:text-white transition-all uppercase tracking-widest font-display"
                        >
                            Consultar Reportes Públicos
                        </button>
                    </div>
                </form>

                <div className="mt-8 text-center">
                    <p className="text-[10px] text-uninunez-ash font-bold uppercase tracking-widest leading-relaxed">
                        Corporación Universitaria Rafael Núñez<br/>
                        <span className="text-gray-400 font-medium normal-case">Vigilada Mineducación</span>
                    </p>
                </div>
            </div>
        </div>
    );
};

// @ts-ignore - Importación directa desde CDN
import { createClient } from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';
import { Project, Student, Teacher, ProjectTeacher, Format, TeacherRole, Status, Program, User } from '../types';

const supabaseUrl = (import.meta as any).env?.VITE_SUPABASE_URL || '';
const supabaseAnonKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || '';

export const isSupabaseConfigured = !!(supabaseUrl && supabaseAnonKey && supabaseUrl.startsWith('http'));

// @ts-ignore
export const supabase = isSupabaseConfigured 
    ? createClient(supabaseUrl, supabaseAnonKey) 
    : null;

const generateId = (): string => Date.now().toString(36) + Math.random().toString(36).substring(2);

// --- Local Storage Implementation ---
const LOCAL_STORAGE_KEY = 'uninunez_db';

const getLocalDB = () => {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (!data) return null;
    try {
        return JSON.parse(data);
    } catch {
        return null;
    }
};

const setLocalDB = (db: any) => {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(db));
};

const initialDB = {
    users: [{ id: 'admin-id', username: 'admin', password: 'admin123', role: 'admin', teacherId: null, studentId: null }],
    projects: [],
    programs: [{ id: '1', name: 'Ingeniería de Sistemas' }, { id: '2', name: 'Derecho' }, { id: '3', name: 'Medicina' }],
    students: [],
    teachers: [],
    projectTeachers: [],
    formats: [{ id: '1', name: 'Anteproyecto' }, { id: '2', name: 'Proyecto Final' }],
    teacherRoles: [{ id: '1', name: 'Director' }, { id: '2', name: 'Co-Director' }, { id: '3', name: 'Evaluador 1' }, { id: '4', name: 'Evaluador 2' }],
    statuses: [{ id: '1', name: 'En Proceso' }, { id: '2', name: 'Aprobado' }, { id: '3', name: 'Sustentado' }, { id: '4', name: 'Rechazado' }]
};

export const initializeDB = () => {
    if (!isSupabaseConfigured && !localStorage.getItem(LOCAL_STORAGE_KEY)) {
        setLocalDB(initialDB);
    }
};

const safeQuery = async (queryPromise: Promise<any>, tableName: string) => {
    if (supabase) {
        try {
            const result = await queryPromise;
            if (result.error) throw result.error;
            return result;
        } catch (error) {
            console.error(`Error en Supabase (${tableName}):`, error);
        }
    }

    // Fallback a Local Storage
    const db = getLocalDB() || initialDB;
    return { data: db[tableName] || [], error: null };
};

const mapProjectToDB = (p: Partial<Project>) => ({
    id: p.id,
    title: p.title,
    presentation_date: p.presentationDate,
    files_url: p.filesUrl,
    status_id: p.statusId,
    format_id: p.formatId,
    is_approved_by_director: p.isApprovedByDirector,
    written_grade_reviewer1: p.writtenGradeReviewer1,
    presentation_grade_reviewer1: p.presentationGradeReviewer1,
    written_grade_reviewer2: p.writtenGradeReviewer2,
    presentation_grade_reviewer2: p.presentationGradeReviewer2
});

const mapProjectFromDB = (p: any): Project => ({
    id: p.id,
    title: p.title,
    presentationDate: p.presentation_date || p.presentationDate,
    filesUrl: p.files_url || p.filesUrl,
    statusId: p.status_id || p.statusId,
    formatId: p.format_id || p.formatId,
    isApprovedByDirector: p.is_approved_by_director !== undefined ? p.is_approved_by_director : p.isApprovedByDirector,
    writtenGradeReviewer1: p.written_grade_reviewer1 !== undefined ? p.written_grade_reviewer1 : p.writtenGradeReviewer1,
    presentationGradeReviewer1: p.presentation_grade_reviewer1 !== undefined ? p.presentation_grade_reviewer1 : p.presentationGradeReviewer1,
    writtenGradeReviewer2: p.written_grade_reviewer2 !== undefined ? p.written_grade_reviewer2 : p.writtenGradeReviewer2,
    presentationGradeReviewer2: p.presentation_grade_reviewer2 !== undefined ? p.presentation_grade_reviewer2 : p.presentationGradeReviewer2
});

export const db = {
    checkConnection: async () => {
        if (!supabase) return true; // Si no hay Supabase, la conexión local siempre es válida
        try {
            const { error } = await supabase.from('users').select('id').limit(1);
            return !error;
        } catch {
            return false;
        }
    },

    getUsers: async () => {
        const { data } = await safeQuery(supabase?.from('users').select('*') || Promise.resolve({}), 'users');
        return (data || []).map((u: any) => ({
            ...u,
            teacherId: u.teacher_id || u.teacherId,
            studentId: u.student_id || u.studentId
        }));
    },
    getUserByUsername: async (username: string) => {
        const users = await db.getUsers();
        return users.find((u: User) => u.username.toLowerCase() === username.toLowerCase().trim()) || null;
    },
    deleteUser: async (id: string) => {
        if (supabase) await supabase.from('users').delete().eq('id', id);
        const db_local = getLocalDB();
        if (db_local) {
            db_local.users = db_local.users.filter((u: any) => u.id !== id);
            setLocalDB(db_local);
        }
    },
    getProjects: async () => {
        const { data } = await safeQuery(supabase?.from('projects').select('*') || Promise.resolve({}), 'projects');
        return (data || []).map(mapProjectFromDB);
    },
    getProjectById: async (id: string) => {
        const projects = await db.getProjects();
        return projects.find(p => p.id === id) || null;
    },
    addProject: async (project: Omit<Project, 'id'>) => {
        const id = generateId();
        const newProject = { ...project, id };
        if (supabase) await supabase.from('projects').insert([mapProjectToDB(newProject)]);
        const db_local = getLocalDB();
        if (db_local) {
            db_local.projects.push(newProject);
            setLocalDB(db_local);
        }
        return newProject as Project;
    },
    updateProject: async (project: Project) => {
        if (supabase) await supabase.from('projects').update(mapProjectToDB(project)).eq('id', project.id);
        const db_local = getLocalDB();
        if (db_local) {
            const idx = db_local.projects.findIndex((p: any) => p.id === project.id);
            if (idx !== -1) db_local.projects[idx] = project;
            setLocalDB(db_local);
        }
        return project;
    },
    deleteProject: async (id: string) => {
        if (supabase) await supabase.from('projects').delete().eq('id', id);
        const db_local = getLocalDB();
        if (db_local) {
            db_local.projects = db_local.projects.filter((p: any) => p.id !== id);
            setLocalDB(db_local);
        }
    },
    getStudents: async () => {
        const { data } = await safeQuery(supabase?.from('students').select('*') || Promise.resolve({}), 'students');
        return (data || []).map((s: any) => ({ ...s, projectId: s.project_id || s.projectId, programId: s.program_id || s.programId }));
    },
    getStudentById: async (id: string) => {
        const students = await db.getStudents();
        return students.find(s => s.id === id) || null;
    },
    addStudent: async (student: Omit<Student, 'id'>) => {
        const id = generateId();
        const newStudent = { ...student, id };
        if (supabase) {
            await supabase.from('students').insert([{ id, name: student.name, email: student.email, cedula: student.cedula, project_id: student.projectId, program_id: student.programId }]);
            await supabase.from('users').insert([{ id: generateId(), username: student.name, password: student.cedula, role: 'student', student_id: id }]);
        }
        const db_local = getLocalDB();
        if (db_local) {
            db_local.students.push(newStudent);
            db_local.users.push({ id: generateId(), username: student.name, password: student.cedula, role: 'student', studentId: id, teacherId: null });
            setLocalDB(db_local);
        }
        return newStudent as Student;
    },
    updateStudent: async (student: Student) => {
        if (supabase) {
            await supabase.from('students').update({ name: student.name, email: student.email, cedula: student.cedula, project_id: student.projectId, program_id: student.programId }).eq('id', student.id);
            await supabase.from('users').update({ username: student.name, password: student.cedula }).eq('student_id', student.id);
        }
        const db_local = getLocalDB();
        if (db_local) {
            const idx = db_local.students.findIndex((s: any) => s.id === student.id);
            if (idx !== -1) db_local.students[idx] = student;
            const uIdx = db_local.users.findIndex((u: any) => u.studentId === student.id);
            if (uIdx !== -1) {
                db_local.users[uIdx].username = student.name;
                db_local.users[uIdx].password = student.cedula;
            }
            setLocalDB(db_local);
        }
        return student;
    },
    deleteStudent: async (id: string) => {
        if (supabase) {
            await supabase.from('users').delete().eq('student_id', id);
            await supabase.from('students').delete().eq('id', id);
        }
        const db_local = getLocalDB();
        if (db_local) {
            db_local.users = db_local.users.filter((u: any) => u.studentId !== id);
            db_local.students = db_local.students.filter((s: any) => s.id !== id);
            setLocalDB(db_local);
        }
    },
    getTeachers: async () => {
        const { data } = await safeQuery(supabase?.from('teachers').select('*') || Promise.resolve({}), 'teachers');
        return data || [];
    },
    getTeacherById: async (id: string) => {
        const teachers = await db.getTeachers();
        return teachers.find(t => t.id === id) || null;
    },
    addTeacher: async (teacher: Omit<Teacher, 'id'>) => {
        const id = generateId();
        const newTeacher = { ...teacher, id };
        if (supabase) {
            await supabase.from('teachers').insert([{ ...teacher, id }]);
            await supabase.from('users').insert([{ id: generateId(), username: teacher.name, password: teacher.cedula, role: 'teacher', teacher_id: id }]);
        }
        const db_local = getLocalDB();
        if (db_local) {
            db_local.teachers.push(newTeacher);
            db_local.users.push({ id: generateId(), username: teacher.name, password: teacher.cedula, role: 'teacher', teacherId: id, studentId: null });
            setLocalDB(db_local);
        }
        return newTeacher as Teacher;
    },
    updateTeacher: async (teacher: Teacher) => {
        if (supabase) {
            await supabase.from('teachers').update(teacher).eq('id', teacher.id);
            await supabase.from('users').update({ username: teacher.name, password: teacher.cedula }).eq('teacher_id', teacher.id);
        }
        const db_local = getLocalDB();
        if (db_local) {
            const idx = db_local.teachers.findIndex((t: any) => t.id === teacher.id);
            if (idx !== -1) db_local.teachers[idx] = teacher;
            const uIdx = db_local.users.findIndex((u: any) => u.teacherId === teacher.id);
            if (uIdx !== -1) {
                db_local.users[uIdx].username = teacher.name;
                db_local.users[uIdx].password = teacher.cedula;
            }
            setLocalDB(db_local);
        }
        return teacher;
    },
    deleteTeacher: async (id: string) => {
        if (supabase) {
            await supabase.from('users').delete().eq('teacher_id', id);
            await supabase.from('teachers').delete().eq('id', id);
        }
        const db_local = getLocalDB();
        if (db_local) {
            db_local.users = db_local.users.filter((u: any) => u.teacherId !== id);
            db_local.teachers = db_local.teachers.filter((t: any) => t.id !== id);
            setLocalDB(db_local);
        }
    },
    getProjectTeachers: async () => {
        const { data } = await safeQuery(supabase?.from('project_teachers').select('*') || Promise.resolve({}), 'projectTeachers');
        return (data || []).map((pt: any) => ({ 
            id: pt.id, 
            projectId: pt.project_id || pt.projectId, 
            teacherId: pt.teacher_id || pt.teacherId, 
            roleId: pt.role_id || pt.roleId 
        }));
    },
    addProjectTeacher: async (pt: Omit<ProjectTeacher, 'id'>) => {
        const id = generateId();
        const newPT = { ...pt, id };
        if (supabase) await supabase.from('project_teachers').insert([{ id, project_id: pt.projectId, teacher_id: pt.teacherId, role_id: pt.roleId }]);
        const db_local = getLocalDB();
        if (db_local) {
            db_local.projectTeachers.push(newPT);
            setLocalDB(db_local);
        }
        return newPT;
    },
    deleteProjectTeacher: async (id: string) => {
        if (supabase) await supabase.from('project_teachers').delete().eq('id', id);
        const db_local = getLocalDB();
        if (db_local) {
            db_local.projectTeachers = db_local.projectTeachers.filter((pt: any) => pt.id !== id);
            setLocalDB(db_local);
        }
    },
    deleteProjectTeachersByProject: async (projectId: string) => {
        if (supabase) await supabase.from('project_teachers').delete().eq('project_id', projectId);
        const db_local = getLocalDB();
        if (db_local) {
            db_local.projectTeachers = db_local.projectTeachers.filter((pt: any) => pt.projectId !== projectId);
            setLocalDB(db_local);
        }
    },
    getPrograms: async () => (await safeQuery(supabase?.from('programs').select('*') || Promise.resolve({}), 'programs')).data || [],
    getStatuses: async () => (await safeQuery(supabase?.from('statuses').select('*') || Promise.resolve({}), 'statuses')).data || [],
    getFormats: async () => (await safeQuery(supabase?.from('formats').select('*') || Promise.resolve({}), 'formats')).data || [],
    getTeacherRoles: async () => (await safeQuery(supabase?.from('teacher_roles').select('*') || Promise.resolve({}), 'teacherRoles')).data || [],

    // Simplificación de agregación local para settings
    addProgram: async (p: Omit<Program, 'id'>) => {
        const id = generateId();
        if (supabase) await supabase.from('programs').insert([{...p, id}]);
        const db_local = getLocalDB(); if (db_local) { db_local.programs.push({...p, id}); setLocalDB(db_local); }
        return {...p, id};
    },
    updateProgram: async (p: Program) => {
        if (supabase) await supabase.from('programs').update(p).eq('id', p.id);
        const db_local = getLocalDB(); if (db_local) { const idx = db_local.programs.findIndex((i:any)=>i.id===p.id); if(idx!==-1) db_local.programs[idx]=p; setLocalDB(db_local); }
        return p;
    },
    deleteProgram: async (id: string) => {
        if (supabase) await supabase.from('programs').delete().eq('id', id);
        const db_local = getLocalDB(); if (db_local) { db_local.programs = db_local.programs.filter((i:any)=>i.id!==id); setLocalDB(db_local); }
    },
    // Métodos similares para status, format, role... (omitidos por brevedad o mapeados genéricamente)
    addStatus: async (p: Omit<Status, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('statuses').insert([{...p, id}]); const db_l=getLocalDB(); if(db_l){db_l.statuses.push({...p, id}); setLocalDB(db_l);} return {...p, id}; },
    updateStatus: async (p: Status) => { if(supabase) await supabase.from('statuses').update(p).eq('id', p.id); const db_l=getLocalDB(); if(db_l){const idx=db_l.statuses.findIndex((i:any)=>i.id===p.id); if(idx!==-1) db_l.statuses[idx]=p; setLocalDB(db_l);} return p; },
    deleteStatus: async (id: string) => { if(supabase) await supabase.from('statuses').delete().eq('id', id); const db_l=getLocalDB(); if(db_l){db_l.statuses=db_l.statuses.filter((i:any)=>i.id!==id); setLocalDB(db_l);} },

    addFormat: async (p: Omit<Format, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('formats').insert([{...p, id}]); const db_l=getLocalDB(); if(db_l){db_l.formats.push({...p, id}); setLocalDB(db_l);} return {...p, id}; },
    updateFormat: async (p: Format) => { if(supabase) await supabase.from('formats').update(p).eq('id', p.id); const db_l=getLocalDB(); if(db_l){const idx=db_l.formats.findIndex((i:any)=>i.id===p.id); if(idx!==-1) db_l.formats[idx]=p; setLocalDB(db_l);} return p; },
    deleteFormat: async (id: string) => { if(supabase) await supabase.from('formats').delete().eq('id', id); const db_l=getLocalDB(); if(db_l){db_l.formats=db_l.formats.filter((i:any)=>i.id!==id); setLocalDB(db_l);} },

    addTeacherRole: async (p: Omit<TeacherRole, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('teacher_roles').insert([{...p, id}]); const db_l=getLocalDB(); if(db_l){db_l.teacherRoles.push({...p, id}); setLocalDB(db_l);} return {...p, id}; },
    updateTeacherRole: async (p: TeacherRole) => { if(supabase) await supabase.from('teacher_roles').update(p).eq('id', p.id); const db_l=getLocalDB(); if(db_l){const idx=db_l.teacherRoles.findIndex((i:any)=>i.id===p.id); if(idx!==-1) db_l.teacherRoles[idx]=p; setLocalDB(db_l);} return p; },
    deleteTeacherRole: async (id: string) => { if(supabase) await supabase.from('teacher_roles').delete().eq('id', id); const db_l=getLocalDB(); if(db_l){db_l.teacherRoles=db_l.teacherRoles.filter((i:any)=>i.id!==id); setLocalDB(db_l);} },

    getCurrentDB: async () => {
        const [users, projects, programs, students, teachers, projectTeachers, formats, teacherRoles, statuses] = await Promise.all([
            db.getUsers(), db.getProjects(), db.getPrograms(), db.getStudents(), db.getTeachers(),
            db.getProjectTeachers(), db.getFormats(), db.getTeacherRoles(), db.getStatuses()
        ]);
        return { users, projects, programs, students, teachers, projectTeachers, formats, teacherRoles, statuses };
    },
    initializeDB
};

import React, { useState, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { Project, Student, Teacher, TeacherRole, Status, Format, ProjectTeacher } from '../types';
import { Modal } from '../components/Modal';
import { ConfirmationDialog } from '../components/ConfirmationDialog';
import { PlusIcon, EditIcon, TrashIcon } from '../components/Icons';
import { useAuth } from '../contexts/AuthContext';

const ProjectForm: React.FC<{
    project: Partial<Project> | null;
    onSave: (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => void;
    onClose: () => void;
    statuses: Status[];
    formats: Format[];
    teachers: Teacher[];
    allStudents: Student[];
    roles: TeacherRole[];
    initialAssignments: ProjectTeacher[];
    initialStudentIds: string[];
    canEditDetails: boolean;
    gradeInfo: { canGrade: boolean, reviewerRole: string | null };
}> = ({ project, onSave, onClose, statuses, formats, teachers, allStudents, roles, initialAssignments, initialStudentIds, canEditDetails, gradeInfo }) => {
    const { isAdmin } = useAuth();
    const [formData, setFormData] = useState<Partial<Project>>({});
    const [assignments, setAssignments] = useState<Array<{teacherId: string, roleId: string, tempId: number}>>([]);
    const [assignedStudentIds, setAssignedStudentIds] = useState<string[]>([]);
    const [newAssignment, setNewAssignment] = useState({ teacherId: '', roleId: '' });
    const [selectedStudentId, setSelectedStudentId] = useState('');

    useEffect(() => {
        const initialData: Partial<Project> = {
            title: '', presentationDate: '', filesUrl: '',
            statusId: statuses[0]?.id || '', formatId: formats[0]?.id || '',
            isApprovedByDirector: false, writtenGradeReviewer1: null,
            presentationGradeReviewer1: null, writtenGradeReviewer2: null,
            presentationGradeReviewer2: null, ...project
        };
        setFormData(initialData);
        setAssignments(initialAssignments.map(a => ({ teacherId: a.teacherId, roleId: a.roleId, tempId: Math.random() })));
        setAssignedStudentIds(initialStudentIds);
        setNewAssignment({ teacherId: '', roleId: '' });
        setSelectedStudentId('');
    }, [project, initialAssignments, initialStudentIds, statuses]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
    };

    const handleAddAssignment = () => {
        if (newAssignment.teacherId && newAssignment.roleId) {
            if (assignments.some(a => a.teacherId === newAssignment.teacherId)) {
                alert('Este docente ya ha sido asignado.'); return;
            }
            setAssignments(prev => [...prev, {...newAssignment, tempId: Math.random()}]);
            setNewAssignment({ teacherId: '', roleId: '' });
        }
    };

    const handleAddStudent = () => {
        if (selectedStudentId && !assignedStudentIds.includes(selectedStudentId)) {
            setAssignedStudentIds(prev => [...prev, selectedStudentId]);
            setSelectedStudentId('');
        }
    };

    const removeStudent = (id: string) => {
        setAssignedStudentIds(prev => prev.filter(sid => sid !== id));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave(formData, assignments, assignedStudentIds);
    };

    const getTeacherName = (id: string) => teachers.find(t => t.id === id)?.name || 'Desconocido';
    const getRoleName = (id: string) => roles.find(r => r.id === id)?.name || 'Desconocido';
    const getStudentName = (id: string) => allStudents.find(s => s.id === id)?.name || 'Estudiante';

    // Estudiantes que no tienen proyecto o que ya están en este proyecto
    const availableStudents = allStudents.filter(s => !s.projectId || assignedStudentIds.includes(s.id));

    return (
        <form onSubmit={handleSubmit} className="space-y-5">
            <div className="space-y-4">
                <div>
                    <label className="block text-xs font-bold text-uninunez-ash uppercase tracking-widest mb-1.5">Título del Proyecto</label>
                    <input type="text" name="title" value={formData.title || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-lg shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs font-bold text-uninunez-ash uppercase tracking-widest mb-1.5">Fecha de Radicación</label>
                        <input type="date" name="presentationDate" value={formData.presentationDate || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-lg shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails}/>
                    </div>
                    <div>
                        <label className="block text-xs font-bold text-uninunez-ash uppercase tracking-widest mb-1.5">Estado del Proceso</label>
                        <select name="statusId" value={formData.statusId || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-lg shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails && !gradeInfo.canGrade}>
                            {statuses.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-sm font-black text-uninunez-onix uppercase tracking-widest mb-4">Integrantes (Estudiantes)</h4>
                <div className="space-y-2 mb-3">
                    {assignedStudentIds.map(sid => (
                        <div key={sid} className="flex justify-between items-center bg-gray-50 px-3 py-2 rounded-lg border border-gray-100">
                            <span className="text-sm font-medium text-gray-700">{getStudentName(sid)}</span>
                            {canEditDetails && (
                                <button type="button" onClick={() => removeStudent(sid)} className="text-red-500 hover:text-red-700 p-1">
                                    <TrashIcon className="h-4 w-4"/>
                                </button>
                            )}
                        </div>
                    ))}
                    {assignedStudentIds.length === 0 && <p className="text-xs text-gray-400 italic">No hay estudiantes vinculados.</p>}
                </div>
                {canEditDetails && (
                    <div className="flex gap-2">
                        <select 
                            value={selectedStudentId} 
                            onChange={(e) => setSelectedStudentId(e.target.value)}
                            className="flex-grow border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-orange"
                        >
                            <option value="">Seleccionar Estudiante...</option>
                            {availableStudents.filter(s => !assignedStudentIds.includes(s.id)).map(s => (
                                <option key={s.id} value={s.id}>{s.name}</option>
                            ))}
                        </select>
                        <button type="button" onClick={handleAddStudent} className="bg-uninunez-orange text-white px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-uninunez-orangeLight shadow-md">
                            Añadir
                        </button>
                    </div>
                )}
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-sm font-black text-uninunez-onix uppercase tracking-widest mb-4">Asignaciones (Docentes)</h4>
                <div className="space-y-2 mb-3">
                    {assignments.map(a => (
                        <div key={a.tempId} className="flex justify-between items-center bg-gray-50 px-3 py-2 rounded-lg border border-gray-100">
                            <span className="text-sm font-medium text-gray-700">{getTeacherName(a.teacherId)} — <span className="text-uninunez-teal font-bold text-xs uppercase">{getRoleName(a.roleId)}</span></span>
                            {canEditDetails && (
                                <button type="button" onClick={() => setAssignments(prev => prev.filter(x => x.tempId !== a.tempId))} className="text-red-500 hover:text-red-700 p-1">
                                    <TrashIcon className="h-4 w-4"/>
                                </button>
                            )}
                        </div>
                    ))}
                </div>
                {canEditDetails && (
                    <div className="grid grid-cols-1 sm:grid-cols-7 gap-2">
                        <select name="teacherId" value={newAssignment.teacherId} onChange={(e) => setNewAssignment(p => ({...p, teacherId: e.target.value}))} className="sm:col-span-3 border border-gray-300 rounded-lg px-3 py-2 text-sm">
                            <option value="">Docente...</option>
                            {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                        </select>
                        <select name="roleId" value={newAssignment.roleId} onChange={(e) => setNewAssignment(p => ({...p, roleId: e.target.value}))} className="sm:col-span-3 border border-gray-300 rounded-lg px-3 py-2 text-sm">
                            <option value="">Rol...</option>
                            {roles.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                        </select>
                        <button type="button" onClick={handleAddAssignment} className="sm:col-span-1 bg-uninunez-orange text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-uninunez-orangeLight shadow-md">
                            Añadir
                        </button>
                    </div>
                )}
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t">
                <button type="button" onClick={onClose} className="px-6 py-2.5 border-2 border-gray-200 rounded-xl text-xs font-bold uppercase tracking-widest text-gray-500 hover:bg-gray-50">Cancelar</button>
                <button type="submit" className="px-8 py-2.5 bg-uninunez-orange text-white rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-uninunez-orangeLight shadow-lg transform transition active:scale-95">Guardar Proyecto</button>
            </div>
        </form>
    );
};

export const ProjectsPage: React.FC = () => {
    const { isAdmin, canEditProject, canGradeProject } = useAuth();
    const [projects, setProjects] = useState<Project[]>([]);
    const [students, setStudents] = useState<Student[]>([]);
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [roles, setRoles] = useState<TeacherRole[]>([]);
    const [statuses, setStatuses] = useState<Status[]>([]);
    const [formats, setFormats] = useState<Format[]>([]);
    const [projectTeachers, setProjectTeachers] = useState<ProjectTeacher[]>([]);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);

    const [userPerms, setUserPerms] = useState<Record<string, {canEdit: boolean, grade: {canGrade: boolean, reviewerRole: string | null}}>>({});

    const loadData = useCallback(async () => {
        const [p, s, t, r, st, f, pt] = await Promise.all([
            db.getProjects(), db.getStudents(), db.getTeachers(),
            db.getTeacherRoles(), db.getStatuses(), db.getFormats(),
            db.getProjectTeachers()
        ]);
        setProjects(p);
        setStudents(s);
        setTeachers(t);
        setRoles(r);
        setStatuses(st);
        setFormats(f);
        setProjectTeachers(pt);

        const perms: any = {};
        for(const project of p) {
            perms[project.id] = {
                canEdit: await canEditProject(project.id),
                grade: await canGradeProject(project.id)
            };
        }
        setUserPerms(perms);
    }, [canEditProject, canGradeProject]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => {
        let savedProject: Project;
        if (editingProject) {
            savedProject = await db.updateProject({ ...editingProject, ...projectData } as Project);
        } else {
            savedProject = await db.addProject(projectData as Omit<Project, 'id'>);
        }

        // 1. Sincronizar Docentes
        if (userPerms[savedProject.id]?.canEdit || isAdmin || !editingProject) {
            await db.deleteProjectTeachersByProject(savedProject.id);
            for (const a of assignments) {
                await db.addProjectTeacher({ projectId: savedProject.id, teacherId: a.teacherId, roleId: a.roleId });
            }

            // 2. Sincronizar Estudiantes
            // Liberar estudiantes que antes estaban en este proyecto pero ya no
            const prevProjectStudents = students.filter(s => s.projectId === savedProject.id);
            for (const s of prevProjectStudents) {
                if (!studentIds.includes(s.id)) {
                    await db.updateStudent({ ...s, projectId: null });
                }
            }
            // Asignar nuevos estudiantes
            for (const sid of studentIds) {
                const s = students.find(x => x.id === sid);
                if (s && s.projectId !== savedProject.id) {
                    await db.updateStudent({ ...s, projectId: savedProject.id });
                }
            }
        }

        loadData();
        setIsModalOpen(false);
    };

    const handleDelete = async () => {
        if (deletingProject) {
            await db.deleteProject(deletingProject.id);
            loadData();
            setDeletingProject(null);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-black text-uninunez-onix font-display uppercase tracking-tight">Banco de Proyectos</h1>
                    <p className="text-uninunez-ash text-sm font-medium">Gestión integral de trabajos de grado y asignaciones.</p>
                </div>
                {isAdmin && (
                    <button 
                        onClick={() => { setEditingProject(null); setIsModalOpen(true); }} 
                        className="bg-uninunez-orange text-white px-6 py-2.5 rounded-xl flex items-center text-xs font-bold uppercase tracking-widest shadow-lg hover:bg-uninunez-orangeLight transition-transform active:scale-95"
                    >
                        <PlusIcon className="h-5 w-5 mr-2"/> Nuevo Proyecto
                    </button>
                )}
            </div>
            <div className="bg-white shadow-sm border border-gray-100 rounded-2xl overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50/50 border-b border-gray-100">
                            <tr>
                                <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Título del Proyecto</th>
                                <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Estado Actual</th>
                                <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest">Acciones</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-50">
                            {projects.map(p => (
                                <tr key={p.id} className="hover:bg-gray-50/50 transition-colors">
                                    <td className="px-6 py-4 text-sm font-bold text-uninunez-onix">{p.title}</td>
                                    <td className="px-6 py-4">
                                        <span className="px-3 py-1 text-[10px] font-black uppercase tracking-wider rounded-lg bg-uninunez-teal/10 text-uninunez-teal">
                                            {statuses.find(s => s.id === p.statusId)?.name || 'N/A'}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 flex gap-3">
                                        {(userPerms[p.id]?.canEdit || userPerms[p.id]?.grade.canGrade) && (
                                            <button onClick={() => { setEditingProject(p); setIsModalOpen(true); }} className="text-uninunez-teal hover:text-uninunez-tealLight p-1.5 hover:bg-uninunez-teal/5 rounded-lg transition-colors">
                                                <EditIcon className="h-5 w-5"/>
                                            </button>
                                        )}
                                        {userPerms[p.id]?.canEdit && (
                                            <button onClick={() => setDeletingProject(p)} className="text-red-500 hover:text-red-600 p-1.5 hover:bg-red-50 rounded-lg transition-colors">
                                                <TrashIcon className="h-5 w-5"/>
                                            </button>
                                        )}
                                    </td>
                                </tr>
                            ))}
                            {projects.length === 0 && (
                                <tr>
                                    <td colSpan={3} className="text-center py-20 text-gray-400 italic text-sm">No se han registrado proyectos en la plataforma.</td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingProject ? 'Actualizar Información de Proyecto' : 'Registro de Nuevo Proyecto'}>
                {isModalOpen && (
                    <ProjectForm 
                        project={editingProject} 
                        onSave={handleSave} 
                        onClose={() => setIsModalOpen(false)} 
                        statuses={statuses} 
                        formats={formats} 
                        teachers={teachers} 
                        allStudents={students}
                        roles={roles} 
                        initialAssignments={editingProject ? projectTeachers.filter(pt => pt.projectId === editingProject.id) : []} 
                        initialStudentIds={editingProject ? students.filter(s => s.projectId === editingProject.id).map(s => s.id) : []}
                        canEditDetails={editingProject ? userPerms[editingProject.id]?.canEdit : isAdmin} 
                        gradeInfo={editingProject ? userPerms[editingProject.id]?.grade : {canGrade: false, reviewerRole: null}} 
                    />
                )}
            </Modal>
            <ConfirmationDialog isOpen={!!deletingProject} onClose={() => setDeletingProject(null)} onConfirm={handleDelete} title="Confirmar Eliminación" message="¿Estás seguro de que deseas eliminar este proyecto del banco institucional? Esta acción es irreversible." />
        </div>
    );
};

import React, { createContext, useState, useContext, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { User } from '../types';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isAdmin: boolean;
  isTeacher: boolean;
  isStudent: boolean;
  canEditProject: (projectId: string) => Promise<boolean>;
  canGradeProject: (projectId: string) => Promise<{ canGrade: boolean, reviewerRole: string | null, reviewerSlot: 1 | 2 | 'admin' | null }>;
  login: (username: string, password: string) => Promise<boolean>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    const storedUser = localStorage.getItem('degreeProjectManagerUser');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  const login = async (username: string, password: string): Promise<boolean> => {
    try {
        const foundUser = await db.getUserByUsername(username.trim());
        if (foundUser && String(foundUser.password).trim() === String(password).trim()) {
          setUser(foundUser);
          localStorage.setItem('degreeProjectManagerUser', JSON.stringify(foundUser));
          return true;
        }
    } catch (e) {
        console.error("Error en proceso de login:", e);
    }
    return false;
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('degreeProjectManagerUser');
  };

  const getProjectAssignmentsForCurrentUser = async (projectId: string) => {
    if (!user || !user.teacherId) return [];
    const projectTeachers = await db.getProjectTeachers();
    const roles = await db.getTeacherRoles();
    return projectTeachers
      .filter(pt => pt.projectId === projectId && pt.teacherId === user.teacherId)
      .map(pt => ({
        roleName: roles.find(r => r.id === pt.roleId)?.name || '',
        roleId: pt.roleId
      }));
  };

  const canEditProject = async (projectId: string): Promise<boolean> => {
    if (!user) return false;
    if (user.role === 'admin') return true;
    if (user.role !== 'teacher') return false;
    const assignments = await getProjectAssignmentsForCurrentUser(projectId);
    return assignments.some(a => a.roleName.toLowerCase().includes('director'));
  };

  const canGradeProject = async (projectId: string): Promise<{ canGrade: boolean, reviewerRole: string | null, reviewerSlot: 1 | 2 | 'admin' | null }> => {
      if (!user) return { canGrade: false, reviewerRole: null, reviewerSlot: null };
      if (user.role === 'admin') return { canGrade: true, reviewerRole: 'admin', reviewerSlot: 'admin' };
      if (user.role !== 'teacher') return { canGrade: false, reviewerRole: null, reviewerSlot: null };

      const assignments = await getProjectAssignmentsForCurrentUser(projectId);
      const eval1 = assignments.find(a => a.roleName.toLowerCase().includes('evaluador 1'));
      if (eval1) return { canGrade: true, reviewerRole: eval1.roleName, reviewerSlot: 1 };

      const eval2 = assignments.find(a => a.roleName.toLowerCase().includes('evaluador 2'));
      if (eval2) return { canGrade: true, reviewerRole: eval2.roleName, reviewerSlot: 2 };

      return { canGrade: false, reviewerRole: null, reviewerSlot: null };
  };

  const isAuthenticated = !!user;
  const isAdmin = user?.role === 'admin';
  const isTeacher = user?.role === 'teacher';
  const isStudent = user?.role === 'student';

  return (
    <AuthContext.Provider value={{ user, isAuthenticated, isAdmin, isTeacher, isStudent, login, logout, canEditProject, canGradeProject }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { useState, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { Project, Student, Teacher, TeacherRole, Status, Format, ProjectTeacher } from '../types';
import { Modal } from '../components/Modal';
import { ConfirmationDialog } from '../components/ConfirmationDialog';
import { PlusIcon, EditIcon, TrashIcon } from '../components/Icons';
import { useAuth } from '../contexts/AuthContext';

const ProjectForm: React.FC<{
    project: Partial<Project> | null;
    onSave: (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => void;
    onClose: () => void;
    statuses: Status[];
    formats: Format[];
    teachers: Teacher[];
    allStudents: Student[];
    roles: TeacherRole[];
    initialAssignments: ProjectTeacher[];
    initialStudentIds: string[];
    canEditDetails: boolean;
    gradeInfo: { canGrade: boolean, reviewerRole: string | null, reviewerSlot: 1 | 2 | 'admin' | null };
}> = ({ project, onSave, onClose, statuses, formats, teachers, allStudents, roles, initialAssignments, initialStudentIds, canEditDetails, gradeInfo }) => {
    const { isAdmin } = useAuth();
    const [formData, setFormData] = useState<Partial<Project>>({});
    const [assignments, setAssignments] = useState<Array<{teacherId: string, roleId: string, tempId: number}>>([]);
    const [assignedStudentIds, setAssignedStudentIds] = useState<string[]>([]);
    const [newAssignment, setNewAssignment] = useState({ teacherId: '', roleId: '' });
    const [selectedStudentId, setSelectedStudentId] = useState('');

    useEffect(() => {
        const initialData: Partial<Project> = {
            title: '', presentationDate: '', filesUrl: '',
            statusId: statuses[0]?.id || '', formatId: formats[0]?.id || '',
            isApprovedByDirector: false, writtenGradeReviewer1: null,
            presentationGradeReviewer1: null, writtenGradeReviewer2: null,
            presentationGradeReviewer2: null, ...project
        };
        setFormData(initialData);
        setAssignments(initialAssignments.map(a => ({ teacherId: a.teacherId, roleId: a.roleId, tempId: Math.random() })));
        setAssignedStudentIds(initialStudentIds);
        setNewAssignment({ teacherId: '', roleId: '' });
        setSelectedStudentId('');
    }, [project, initialAssignments, initialStudentIds, statuses]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        let val: any = value;
        if (type === 'number') {
            val = value === '' ? null : parseFloat(value);
            if (val !== null && (val < 1 || val > 5)) return; // Validación de rango 1-5
        }
        setFormData(prev => ({ ...prev, [name]: val }));
    };

    const handleAddAssignment = () => {
        if (newAssignment.teacherId && newAssignment.roleId) {
            if (assignments.some(a => a.teacherId === newAssignment.teacherId)) {
                alert('Este docente ya ha sido asignado.'); return;
            }
            setAssignments(prev => [...prev, {...newAssignment, tempId: Math.random()}]);
            setNewAssignment({ teacherId: '', roleId: '' });
        }
    };

    const handleAddStudent = () => {
        if (selectedStudentId && !assignedStudentIds.includes(selectedStudentId)) {
            setAssignedStudentIds(prev => [...prev, selectedStudentId]);
            setSelectedStudentId('');
        }
    };

    const removeStudent = (id: string) => {
        setAssignedStudentIds(prev => prev.filter(sid => sid !== id));
    };

    const calculateFinalGrade = () => {
        const g1w = formData.writtenGradeReviewer1 || 0;
        const g1p = formData.presentationGradeReviewer1 || 0;
        const g2w = formData.writtenGradeReviewer2 || 0;
        const g2p = formData.presentationGradeReviewer2 || 0;

        let total = 0;
        let count = 0;

        if (g1w > 0 || g1p > 0) {
            total += (g1w + g1p) / (g1w > 0 && g1p > 0 ? 2 : 1);
            count++;
        }
        if (g2w > 0 || g2p > 0) {
            total += (g2w + g2p) / (g2w > 0 && g2p > 0 ? 2 : 1);
            count++;
        }

        return count > 0 ? (total / count).toFixed(2) : '0.00';
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave(formData, assignments, assignedStudentIds);
    };

    const getTeacherName = (id: string) => teachers.find(t => t.id === id)?.name || 'Desconocido';
    const getRoleName = (id: string) => roles.find(r => r.id === id)?.name || 'Desconocido';
    const getStudentName = (id: string) => allStudents.find(s => s.id === id)?.name || 'Estudiante';

    const canGrade1 = isAdmin || gradeInfo.reviewerSlot === 1;
    const canGrade2 = isAdmin || gradeInfo.reviewerSlot === 2;

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-4">
                <div>
                    <label className="block text-[10px] font-bold text-uninunez-ash uppercase tracking-widest mb-1.5 ml-1">Título del Proyecto</label>
                    <input type="text" name="title" value={formData.title || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-[10px] font-bold text-uninunez-ash uppercase tracking-widest mb-1.5 ml-1">Fecha de Radicación</label>
                        <input type="date" name="presentationDate" value={formData.presentationDate || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails}/>
                    </div>
                    <div>
                        <label className="block text-[10px] font-bold text-uninunez-ash uppercase tracking-widest mb-1.5 ml-1">Estado del Proceso</label>
                        <select name="statusId" value={formData.statusId || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails && !gradeInfo.canGrade}>
                            {statuses.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            {/* SECCIÓN DE CALIFICACIONES */}
            <div className="bg-gray-50 p-6 rounded-2xl border border-gray-100 space-y-4">
                <div className="flex justify-between items-center mb-2">
                    <h4 className="text-xs font-black text-uninunez-onix uppercase tracking-widest">Calificaciones Académicas (1.0 - 5.0)</h4>
                    <div className="bg-uninunez-orange text-white px-3 py-1 rounded-lg text-sm font-black">
                        NOTA FINAL: {calculateFinalGrade()}
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Evaluador 1 */}
                    <div className={`p-4 rounded-xl border-2 ${canGrade1 ? 'bg-white border-uninunez-teal/20' : 'bg-gray-100 border-transparent opacity-60'}`}>
                        <p className="text-[10px] font-black text-uninunez-teal uppercase tracking-widest mb-3">Evaluador 1</p>
                        <div className="space-y-3">
                            <div>
                                <label className="block text-[9px] font-bold text-gray-500 uppercase mb-1">Trabajo Escrito</label>
                                <input type="number" step="0.1" min="1" max="5" name="writtenGradeReviewer1" value={formData.writtenGradeReviewer1 ?? ''} onChange={handleChange} disabled={!canGrade1} className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-teal" placeholder="0.0" />
                            </div>
                            <div>
                                <label className="block text-[9px] font-bold text-gray-500 uppercase mb-1">Sustentación</label>
                                <input type="number" step="0.1" min="1" max="5" name="presentationGradeReviewer1" value={formData.presentationGradeReviewer1 ?? ''} onChange={handleChange} disabled={!canGrade1} className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-teal" placeholder="0.0" />
                            </div>
                        </div>
                    </div>

                    {/* Evaluador 2 */}
                    <div className={`p-4 rounded-xl border-2 ${canGrade2 ? 'bg-white border-uninunez-teal/20' : 'bg-gray-100 border-transparent opacity-60'}`}>
                        <p className="text-[10px] font-black text-uninunez-teal uppercase tracking-widest mb-3">Evaluador 2</p>
                        <div className="space-y-3">
                            <div>
                                <label className="block text-[9px] font-bold text-gray-500 uppercase mb-1">Trabajo Escrito</label>
                                <input type="number" step="0.1" min="1" max="5" name="writtenGradeReviewer2" value={formData.writtenGradeReviewer2 ?? ''} onChange={handleChange} disabled={!canGrade2} className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-teal" placeholder="0.0" />
                            </div>
                            <div>
                                <label className="block text-[9px] font-bold text-gray-500 uppercase mb-1">Sustentación</label>
                                <input type="number" step="0.1" min="1" max="5" name="presentationGradeReviewer2" value={formData.presentationGradeReviewer2 ?? ''} onChange={handleChange} disabled={!canGrade2} className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-teal" placeholder="0.0" />
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-4 ml-1">Integrantes Estudiantiles</h4>
                <div className="flex flex-wrap gap-2 mb-3">
                    {assignedStudentIds.map(sid => (
                        <div key={sid} className="flex items-center bg-white px-3 py-1.5 rounded-full border border-gray-200 shadow-sm">
                            <span className="text-xs font-bold text-gray-600 mr-2">{getStudentName(sid)}</span>
                            {canEditDetails && (
                                <button type="button" onClick={() => removeStudent(sid)} className="text-red-400 hover:text-red-600 transition-colors">
                                    <TrashIcon className="h-3.5 w-3.5"/>
                                </button>
                            )}
                        </div>
                    ))}
                </div>
                {canEditDetails && (
                    <div className="flex gap-2">
                        <select value={selectedStudentId} onChange={(e) => setSelectedStudentId(e.target.value)} className="flex-grow border border-gray-200 rounded-xl px-4 py-2.5 text-sm">
                            <option value="">Seleccionar Estudiante...</option>
                            {allStudents.filter(s => (!s.projectId || assignedStudentIds.includes(s.id)) && !assignedStudentIds.includes(s.id)).map(s => (
                                <option key={s.id} value={s.id}>{s.name}</option>
                            ))}
                        </select>
                        <button type="button" onClick={handleAddStudent} className="bg-uninunez-orange text-white px-5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-uninunez-orangeLight shadow-md">Añadir</button>
                    </div>
                )}
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-4 ml-1">Docentes Asignados</h4>
                <div className="space-y-2 mb-4">
                    {assignments.map(a => (
                        <div key={a.tempId} className="flex justify-between items-center bg-white px-4 py-2.5 rounded-xl border border-gray-100 shadow-sm">
                            <span className="text-sm font-bold text-gray-700">{getTeacherName(a.teacherId)} — <span className="text-uninunez-orange text-[10px] uppercase">{getRoleName(a.roleId)}</span></span>
                            {canEditDetails && (
                                <button type="button" onClick={() => setAssignments(prev => prev.filter(x => x.tempId !== a.tempId))} className="text-red-400 hover:text-red-600 p-1">
                                    <TrashIcon className="h-4 w-4"/>
                                </button>
                            )}
                        </div>
                    ))}
                </div>
                {canEditDetails && (
                    <div className="grid grid-cols-1 sm:grid-cols-7 gap-2">
                        <select value={newAssignment.teacherId} onChange={(e) => setNewAssignment(p => ({...p, teacherId: e.target.value}))} className="sm:col-span-3 border border-gray-200 rounded-xl px-4 py-2.5 text-sm">
                            <option value="">Docente...</option>
                            {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                        </select>
                        <select value={newAssignment.roleId} onChange={(e) => setNewAssignment(p => ({...p, roleId: e.target.value}))} className="sm:col-span-3 border border-gray-200 rounded-xl px-4 py-2.5 text-sm">
                            <option value="">Rol...</option>
                            {roles.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                        </select>
                        <button type="button" onClick={handleAddAssignment} className="sm:col-span-1 bg-uninunez-orange text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-uninunez-orangeLight shadow-md">OK</button>
                    </div>
                )}
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t">
                <button type="button" onClick={onClose} className="px-6 py-3 border-2 border-gray-100 rounded-xl text-[10px] font-black uppercase tracking-widest text-gray-400 hover:bg-gray-50 transition-all">Cerrar</button>
                <button type="submit" className="px-10 py-3 bg-uninunez-orange text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-uninunez-orangeLight shadow-xl transform transition active:scale-95">Guardar Cambios</button>
            </div>
        </form>
    );
};

export const ProjectsPage: React.FC = () => {
    const { isAdmin, canEditProject, canGradeProject } = useAuth();
    const [projects, setProjects] = useState<Project[]>([]);
    const [students, setStudents] = useState<Student[]>([]);
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [roles, setRoles] = useState<TeacherRole[]>([]);
    const [statuses, setStatuses] = useState<Status[]>([]);
    const [formats, setFormats] = useState<Format[]>([]);
    const [projectTeachers, setProjectTeachers] = useState<ProjectTeacher[]>([]);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);

    const [userPerms, setUserPerms] = useState<Record<string, {canEdit: boolean, grade: {canGrade: boolean, reviewerRole: string | null, reviewerSlot: 1 | 2 | 'admin' | null}}>>({});

    const loadData = useCallback(async () => {
        const [p, s, t, r, st, f, pt] = await Promise.all([
            db.getProjects(), db.getStudents(), db.getTeachers(),
            db.getTeacherRoles(), db.getStatuses(), db.getFormats(),
            db.getProjectTeachers()
        ]);
        setProjects(p);
        setStudents(s);
        setTeachers(t);
        setRoles(r);
        setStatuses(st);
        setFormats(f);
        setProjectTeachers(pt);

        const perms: any = {};
        for(const project of p) {
            perms[project.id] = {
                canEdit: await canEditProject(project.id),
                grade: await canGradeProject(project.id)
            };
        }
        setUserPerms(perms);
    }, [canEditProject, canGradeProject]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => {
        let savedProject: Project;
        if (editingProject) {
            savedProject = await db.updateProject({ ...editingProject, ...projectData } as Project);
        } else {
            savedProject = await db.addProject(projectData as Omit<Project, 'id'>);
        }

        // Sincronizar Docentes (solo si es admin o director)
        if (userPerms[savedProject.id]?.canEdit || isAdmin || !editingProject) {
            await db.deleteProjectTeachersByProject(savedProject.id);
            for (const a of assignments) {
                await db.addProjectTeacher({ projectId: savedProject.id, teacherId: a.teacherId, roleId: a.roleId });
            }

            // Sincronizar Estudiantes
            const prevProjectStudents = students.filter(s => s.projectId === savedProject.id);
            for (const s of prevProjectStudents) {
                if (!studentIds.includes(s.id)) {
                    await db.updateStudent({ ...s, projectId: null });
                }
            }
            for (const sid of studentIds) {
                const s = students.find(x => x.id === sid);
                if (s && s.projectId !== savedProject.id) {
                    await db.updateStudent({ ...s, projectId: savedProject.id });
                }
            }
        }

        loadData();
        setIsModalOpen(false);
    };

    const handleDelete = async () => {
        if (deletingProject) {
            await db.deleteProject(deletingProject.id);
            loadData();
            setDeletingProject(null);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-black text-uninunez-onix font-display uppercase tracking-tight">Proyectos Académicos</h1>
                    <p className="text-uninunez-ash text-sm font-medium">Control de trabajos de grado, evaluaciones y seguimiento.</p>
                </div>
                {isAdmin && (
                    <button 
                        onClick={() => { setEditingProject(null); setIsModalOpen(true); }} 
                        className="bg-uninunez-orange text-white px-6 py-3 rounded-xl flex items-center text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-uninunez-orangeLight transition-all active:scale-95"
                    >
                        <PlusIcon className="h-5 w-5 mr-2"/> Registrar Proyecto
                    </button>
                )}
            </div>

            <div className="bg-white shadow-sm border border-gray-100 rounded-3xl overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50/50 border-b border-gray-100">
                            <tr>
                                <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Proyecto</th>
                                <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Etapa Actual</th>
                                <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-right">Gestión</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-50">
                            {projects.map(p => (
                                <tr key={p.id} className="hover:bg-gray-50/50 transition-colors group">
                                    <td className="px-8 py-6">
                                        <div className="text-sm font-bold text-uninunez-onix group-hover:text-uninunez-orange transition-colors">{p.title}</div>
                                        <div className="text-[10px] text-gray-400 mt-1 uppercase font-medium">Radicado: {p.presentationDate}</div>
                                    </td>
                                    <td className="px-8 py-6">
                                        <span className="px-3 py-1.5 text-[10px] font-black uppercase tracking-wider rounded-lg bg-uninunez-teal/10 text-uninunez-teal">
                                            {statuses.find(s => s.id === p.statusId)?.name || 'POR ASIGNAR'}
                                        </span>
                                    </td>
                                    <td className="px-8 py-6 text-right">
                                        <div className="flex justify-end gap-2">
                                            {(userPerms[p.id]?.canEdit || userPerms[p.id]?.grade.canGrade) && (
                                                <button onClick={() => { setEditingProject(p); setIsModalOpen(true); }} className="p-2.5 bg-uninunez-teal/5 text-uninunez-teal hover:bg-uninunez-teal hover:text-white rounded-xl transition-all">
                                                    <EditIcon className="h-5 w-5"/>
                                                </button>
                                            )}
                                            {userPerms[p.id]?.canEdit && (
                                                <button onClick={() => setDeletingProject(p)} className="p-2.5 bg-red-50 text-red-500 hover:bg-red-500 hover:text-white rounded-xl transition-all">
                                                    <TrashIcon className="h-5 w-5"/>
                                                </button>
                                            )}
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingProject ? 'Expediente de Proyecto' : 'Registro de Nuevo Proyecto'}>
                {isModalOpen && (
                    <ProjectForm 
                        project={editingProject} 
                        onSave={handleSave} 
                        onClose={() => setIsModalOpen(false)} 
                        statuses={statuses} 
                        formats={formats} 
                        teachers={teachers} 
                        allStudents={students}
                        roles={roles} 
                        initialAssignments={editingProject ? projectTeachers.filter(pt => pt.projectId === editingProject.id) : []} 
                        initialStudentIds={editingProject ? students.filter(s => s.projectId === editingProject.id).map(s => s.id) : []}
                        canEditDetails={editingProject ? userPerms[editingProject.id]?.canEdit : isAdmin} 
                        gradeInfo={editingProject ? userPerms[editingProject.id]?.grade : {canGrade: false, reviewerRole: null, reviewerSlot: null}} 
                    />
                )}
            </Modal>
            <ConfirmationDialog isOpen={!!deletingProject} onClose={() => setDeletingProject(null)} onConfirm={handleDelete} title="Confirmar Eliminación" message="¿Estás seguro de que deseas eliminar este proyecto del banco institucional? Esta acción eliminará también las asignaciones y calificaciones registradas." />
        </div>
    );
};

import React, { createContext, useState, useContext, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { User } from '../types';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isAdmin: boolean;
  isTeacher: boolean;
  isStudent: boolean;
  canEditProject: (projectId: string) => Promise<boolean>;
  canGradeProject: (projectId: string) => Promise<{ canGrade: boolean, reviewerRole: string | null, reviewerSlot: 1 | 2 | 'admin' | null }>;
  login: (username: string, password: string) => Promise<boolean>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    const storedUser = localStorage.getItem('degreeProjectManagerUser');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  const login = async (username: string, password: string): Promise<boolean> => {
    try {
        const foundUser = await db.getUserByUsername(username.trim());
        if (foundUser && String(foundUser.password).trim() === String(password).trim()) {
          setUser(foundUser);
          localStorage.setItem('degreeProjectManagerUser', JSON.stringify(foundUser));
          return true;
        }
    } catch (e) {
        console.error("Error en proceso de login:", e);
    }
    return false;
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('degreeProjectManagerUser');
  };

  const getProjectAssignmentsForCurrentUser = async (projectId: string) => {
    if (!user || !user.teacherId) return [];
    const projectTeachers = await db.getProjectTeachers();
    const roles = await db.getTeacherRoles();
    return projectTeachers
      .filter(pt => pt.projectId === projectId && pt.teacherId === user.teacherId)
      .map(pt => ({
        roleName: roles.find(r => r.id === pt.roleId)?.name || '',
        roleId: pt.roleId
      }));
  };

  const canEditProject = async (projectId: string): Promise<boolean> => {
    if (!user) return false;
    if (user.role === 'admin') return true;
    if (user.role !== 'teacher') return false;
    const assignments = await getProjectAssignmentsForCurrentUser(projectId);
    // Un docente solo edita detalles si es director
    return assignments.some(a => a.roleName.toLowerCase().includes('director'));
  };

  const canGradeProject = async (projectId: string): Promise<{ canGrade: boolean, reviewerRole: string | null, reviewerSlot: 1 | 2 | 'admin' | null }> => {
      if (!user) return { canGrade: false, reviewerRole: null, reviewerSlot: null };
      if (user.role === 'admin') return { canGrade: true, reviewerRole: 'admin', reviewerSlot: 'admin' };
      if (user.role !== 'teacher') return { canGrade: false, reviewerRole: null, reviewerSlot: null };

      const assignments = await getProjectAssignmentsForCurrentUser(projectId);

      // Verificamos si es Evaluador 1
      const isEval1 = assignments.some(a => a.roleName.toLowerCase().includes('evaluador 1'));
      if (isEval1) return { canGrade: true, reviewerRole: 'Evaluador 1', reviewerSlot: 1 };

      // Verificamos si es Evaluador 2
      const isEval2 = assignments.some(a => a.roleName.toLowerCase().includes('evaluador 2'));
      if (isEval2) return { canGrade: true, reviewerRole: 'Evaluador 2', reviewerSlot: 2 };

      return { canGrade: false, reviewerRole: null, reviewerSlot: null };
  };

  const isAuthenticated = !!user;
  const isAdmin = user?.role === 'admin';
  const isTeacher = user?.role === 'teacher';
  const isStudent = user?.role === 'student';

  return (
    <AuthContext.Provider value={{ user, isAuthenticated, isAdmin, isTeacher, isStudent, login, logout, canEditProject, canGradeProject }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { useState, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { Project, Student, Teacher, TeacherRole, Status, Format, ProjectTeacher } from '../types';
import { Modal } from '../components/Modal';
import { ConfirmationDialog } from '../components/ConfirmationDialog';
import { PlusIcon, EditIcon, TrashIcon } from '../components/Icons';
import { useAuth } from '../contexts/AuthContext';

const ProjectForm: React.FC<{
    project: Partial<Project> | null;
    onSave: (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => void;
    onClose: () => void;
    statuses: Status[];
    formats: Format[];
    teachers: Teacher[];
    allStudents: Student[];
    roles: TeacherRole[];
    initialAssignments: ProjectTeacher[];
    initialStudentIds: string[];
    canEditDetails: boolean;
    gradeInfo: { canGrade: boolean, reviewerRole: string | null, reviewerSlot: 1 | 2 | 'admin' | null };
}> = ({ project, onSave, onClose, statuses, formats, teachers, allStudents, roles, initialAssignments, initialStudentIds, canEditDetails, gradeInfo }) => {
    const { isAdmin } = useAuth();
    const [formData, setFormData] = useState<Partial<Project>>({});
    const [assignments, setAssignments] = useState<Array<{teacherId: string, roleId: string, tempId: number}>>([]);
    const [assignedStudentIds, setAssignedStudentIds] = useState<string[]>([]);
    const [newAssignment, setNewAssignment] = useState({ teacherId: '', roleId: '' });
    const [selectedStudentId, setSelectedStudentId] = useState('');

    useEffect(() => {
        const initialData: Partial<Project> = {
            title: '', presentationDate: '', filesUrl: '',
            statusId: statuses[0]?.id || '', formatId: formats[0]?.id || '',
            isApprovedByDirector: false, writtenGradeReviewer1: null,
            presentationGradeReviewer1: null, writtenGradeReviewer2: null,
            presentationGradeReviewer2: null, ...project
        };
        setFormData(initialData);
        setAssignments(initialAssignments.map(a => ({ teacherId: a.teacherId, roleId: a.roleId, tempId: Math.random() })));
        setAssignedStudentIds(initialStudentIds);
        setNewAssignment({ teacherId: '', roleId: '' });
        setSelectedStudentId('');
    }, [project, initialAssignments, initialStudentIds, statuses]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        let val: any = value;

        if (type === 'number') {
            if (value === '') {
                val = null;
            } else {
                const num = parseFloat(value);
                // Validar rango 1.0 a 5.0
                if (num < 1.0 || num > 5.0) return;
                val = num;
            }
        }
        setFormData(prev => ({ ...prev, [name]: val }));
    };

    const handleAddAssignment = () => {
        if (newAssignment.teacherId && newAssignment.roleId) {
            if (assignments.some(a => a.teacherId === newAssignment.teacherId)) {
                alert('Este docente ya ha sido asignado.'); return;
            }
            setAssignments(prev => [...prev, {...newAssignment, tempId: Math.random()}]);
            setNewAssignment({ teacherId: '', roleId: '' });
        }
    };

    const handleAddStudent = () => {
        if (selectedStudentId && !assignedStudentIds.includes(selectedStudentId)) {
            setAssignedStudentIds(prev => [...prev, selectedStudentId]);
            setSelectedStudentId('');
        }
    };

    const removeStudent = (id: string) => {
        setAssignedStudentIds(prev => prev.filter(sid => sid !== id));
    };

    const calculateFinalGrade = () => {
        const g1w = formData.writtenGradeReviewer1 ?? 0;
        const g1p = formData.presentationGradeReviewer1 ?? 0;
        const g2w = formData.writtenGradeReviewer2 ?? 0;
        const g2p = formData.presentationGradeReviewer2 ?? 0;

        let ev1Avg = 0;
        let ev2Avg = 0;
        let activeEvaluators = 0;

        if (g1w > 0 || g1p > 0) {
            ev1Avg = (g1w + g1p) / ((g1w > 0 ? 1 : 0) + (g1p > 0 ? 1 : 0));
            activeEvaluators++;
        }
        if (g2w > 0 || g2p > 0) {
            ev2Avg = (g2w + g2p) / ((g2w > 0 ? 1 : 0) + (g2p > 0 ? 1 : 0));
            activeEvaluators++;
        }

        if (activeEvaluators === 0) return "0.00";
        return ((ev1Avg + ev2Avg) / activeEvaluators).toFixed(2);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave(formData, assignments, assignedStudentIds);
    };

    const getTeacherName = (id: string) => teachers.find(t => t.id === id)?.name || 'Desconocido';
    const getRoleName = (id: string) => roles.find(r => r.id === id)?.name || 'Desconocido';
    const getStudentName = (id: string) => allStudents.find(s => s.id === id)?.name || 'Estudiante';

    // Lógica de deshabilitación de campos de notas
    const isGradingDisabled1 = !(isAdmin || gradeInfo.reviewerSlot === 1);
    const isGradingDisabled2 = !(isAdmin || gradeInfo.reviewerSlot === 2);

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-[0.1em] mb-1.5 ml-1">Título del Proyecto</label>
                    <input type="text" name="title" value={formData.title || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-[0.1em] mb-1.5 ml-1">Fecha de Radicación</label>
                        <input type="date" name="presentationDate" value={formData.presentationDate || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails}/>
                    </div>
                    <div>
                        <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-[0.1em] mb-1.5 ml-1">Estado Institucional</label>
                        <select name="statusId" value={formData.statusId || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails && !gradeInfo.canGrade}>
                            {statuses.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            {/* SECCIÓN DE CALIFICACIONES - CONSTRUIDA CON LOS COLORES DE LA MARCA */}
            <div className="bg-uninunez-onix/5 p-6 rounded-2xl border border-uninunez-onix/10 space-y-4">
                <div className="flex justify-between items-center border-b border-uninunez-onix/10 pb-4">
                    <h4 className="text-[11px] font-black text-uninunez-onix uppercase tracking-[0.2em]">Registro de Evaluación Académica</h4>
                    <div className="flex items-center gap-3">
                        <span className="text-[10px] font-bold text-uninunez-ash uppercase">Promedio Total:</span>
                        <div className="bg-uninunez-orange text-white px-4 py-1.5 rounded-lg text-sm font-black shadow-md">
                            {calculateFinalGrade()}
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Panel Evaluador 1 */}
                    <div className={`p-4 rounded-xl border-2 transition-all ${!isGradingDisabled1 ? 'bg-white border-uninunez-teal shadow-md' : 'bg-gray-50 border-transparent opacity-60'}`}>
                        <div className="flex items-center justify-between mb-4">
                            <p className="text-[10px] font-black text-uninunez-teal uppercase tracking-widest">Evaluador Principal 1</p>
                            {!isGradingDisabled1 && <span className="bg-uninunez-teal text-white text-[8px] px-2 py-0.5 rounded uppercase font-bold">Habilitado</span>}
                        </div>
                        <div className="space-y-3">
                            <div>
                                <label className="block text-[9px] font-bold text-gray-500 uppercase mb-1">Nota Trabajo Escrito</label>
                                <input type="number" step="0.1" min="1" max="5" name="writtenGradeReviewer1" value={formData.writtenGradeReviewer1 ?? ''} onChange={handleChange} disabled={isGradingDisabled1} className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-teal font-bold text-uninunez-onix" placeholder="1.0 - 5.0" />
                            </div>
                            <div>
                                <label className="block text-[9px] font-bold text-gray-500 uppercase mb-1">Nota Sustentación</label>
                                <input type="number" step="0.1" min="1" max="5" name="presentationGradeReviewer1" value={formData.presentationGradeReviewer1 ?? ''} onChange={handleChange} disabled={isGradingDisabled1} className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-teal font-bold text-uninunez-onix" placeholder="1.0 - 5.0" />
                            </div>
                        </div>
                    </div>

                    {/* Panel Evaluador 2 */}
                    <div className={`p-4 rounded-xl border-2 transition-all ${!isGradingDisabled2 ? 'bg-white border-uninunez-teal shadow-md' : 'bg-gray-50 border-transparent opacity-60'}`}>
                        <div className="flex items-center justify-between mb-4">
                            <p className="text-[10px] font-black text-uninunez-teal uppercase tracking-widest">Evaluador Principal 2</p>
                            {!isGradingDisabled2 && <span className="bg-uninunez-teal text-white text-[8px] px-2 py-0.5 rounded uppercase font-bold">Habilitado</span>}
                        </div>
                        <div className="space-y-3">
                            <div>
                                <label className="block text-[9px] font-bold text-gray-500 uppercase mb-1">Nota Trabajo Escrito</label>
                                <input type="number" step="0.1" min="1" max="5" name="writtenGradeReviewer2" value={formData.writtenGradeReviewer2 ?? ''} onChange={handleChange} disabled={isGradingDisabled2} className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-teal font-bold text-uninunez-onix" placeholder="1.0 - 5.0" />
                            </div>
                            <div>
                                <label className="block text-[9px] font-bold text-gray-500 uppercase mb-1">Nota Sustentación</label>
                                <input type="number" step="0.1" min="1" max="5" name="presentationGradeReviewer2" value={formData.presentationGradeReviewer2 ?? ''} onChange={handleChange} disabled={isGradingDisabled2} className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-teal font-bold text-uninunez-onix" placeholder="1.0 - 5.0" />
                            </div>
                        </div>
                    </div>
                </div>

                {gradeInfo.canGrade && !isAdmin && (
                    <div className="mt-2 text-[9px] font-bold text-uninunez-teal italic bg-uninunez-teal/5 p-2 rounded-lg border border-uninunez-teal/20 text-center">
                        Usted ha sido identificado como {gradeInfo.reviewerRole}. Solo puede editar las notas de su slot asignado.
                    </div>
                )}
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-4 ml-1">Integrantes Estudiantiles</h4>
                <div className="flex flex-wrap gap-2 mb-3">
                    {assignedStudentIds.map(sid => (
                        <div key={sid} className="flex items-center bg-white px-3 py-1.5 rounded-full border border-gray-200 shadow-sm">
                            <span className="text-xs font-bold text-gray-600 mr-2">{getStudentName(sid)}</span>
                            {canEditDetails && (
                                <button type="button" onClick={() => removeStudent(sid)} className="text-red-400 hover:text-red-600 transition-colors">
                                    <TrashIcon className="h-3.5 w-3.5"/>
                                </button>
                            )}
                        </div>
                    ))}
                </div>
                {canEditDetails && (
                    <div className="flex gap-2">
                        <select value={selectedStudentId} onChange={(e) => setSelectedStudentId(e.target.value)} className="flex-grow border border-gray-200 rounded-xl px-4 py-2.5 text-sm">
                            <option value="">Vincular Estudiante...</option>
                            {allStudents.filter(s => (!s.projectId || assignedStudentIds.includes(s.id)) && !assignedStudentIds.includes(s.id)).map(s => (
                                <option key={s.id} value={s.id}>{s.name}</option>
                            ))}
                        </select>
                        <button type="button" onClick={handleAddStudent} className="bg-uninunez-orange text-white px-5 rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-uninunez-orangeLight shadow-md">Añadir</button>
                    </div>
                )}
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-4 ml-1">Docentes Asignados</h4>
                <div className="space-y-2 mb-4">
                    {assignments.map(a => (
                        <div key={a.tempId} className="flex justify-between items-center bg-white px-4 py-2.5 rounded-xl border border-gray-100 shadow-sm">
                            <span className="text-sm font-bold text-gray-700">{getTeacherName(a.teacherId)} — <span className="text-uninunez-orange text-[10px] uppercase font-black">{getRoleName(a.roleId)}</span></span>
                            {canEditDetails && (
                                <button type="button" onClick={() => setAssignments(prev => prev.filter(x => x.tempId !== a.tempId))} className="text-red-400 hover:text-red-600 p-1">
                                    <TrashIcon className="h-4 w-4"/>
                                </button>
                            )}
                        </div>
                    ))}
                </div>
                {canEditDetails && (
                    <div className="grid grid-cols-1 sm:grid-cols-7 gap-2">
                        <select value={newAssignment.teacherId} onChange={(e) => setNewAssignment(p => ({...p, teacherId: e.target.value}))} className="sm:col-span-3 border border-gray-200 rounded-xl px-4 py-2.5 text-sm">
                            <option value="">Docente...</option>
                            {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                        </select>
                        <select value={newAssignment.roleId} onChange={(e) => setNewAssignment(p => ({...p, roleId: e.target.value}))} className="sm:col-span-3 border border-gray-200 rounded-xl px-4 py-2.5 text-sm">
                            <option value="">Rol...</option>
                            {roles.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                        </select>
                        <button type="button" onClick={handleAddAssignment} className="sm:col-span-1 bg-uninunez-orange text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-uninunez-orangeLight shadow-md">OK</button>
                    </div>
                )}
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t">
                <button type="button" onClick={onClose} className="px-6 py-3 border-2 border-gray-100 rounded-xl text-[10px] font-black uppercase tracking-widest text-gray-400 hover:bg-gray-50 transition-all">Cancelar</button>
                <button type="submit" className="px-10 py-3 bg-uninunez-orange text-white rounded-xl text-[10px] font-black uppercase tracking-widest hover:bg-uninunez-orangeLight shadow-xl transform transition active:scale-95">Guardar Cambios</button>
            </div>
        </form>
    );
};

export const ProjectsPage: React.FC = () => {
    const { isAdmin, canEditProject, canGradeProject } = useAuth();
    const [projects, setProjects] = useState<Project[]>([]);
    const [students, setStudents] = useState<Student[]>([]);
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [roles, setRoles] = useState<TeacherRole[]>([]);
    const [statuses, setStatuses] = useState<Status[]>([]);
    const [formats, setFormats] = useState<Format[]>([]);
    const [projectTeachers, setProjectTeachers] = useState<ProjectTeacher[]>([]);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);

    const [userPerms, setUserPerms] = useState<Record<string, {canEdit: boolean, grade: {canGrade: boolean, reviewerRole: string | null, reviewerSlot: 1 | 2 | 'admin' | null}}>>({});

    const loadData = useCallback(async () => {
        const [p, s, t, r, st, f, pt] = await Promise.all([
            db.getProjects(), db.getStudents(), db.getTeachers(),
            db.getTeacherRoles(), db.getStatuses(), db.getFormats(),
            db.getProjectTeachers()
        ]);
        setProjects(p);
        setStudents(s);
        setTeachers(t);
        setRoles(r);
        setStatuses(st);
        setFormats(f);
        setProjectTeachers(pt);

        const perms: any = {};
        for(const project of p) {
            perms[project.id] = {
                canEdit: await canEditProject(project.id),
                grade: await canGradeProject(project.id)
            };
        }
        setUserPerms(perms);
    }, [canEditProject, canGradeProject]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => {
        let savedProject: Project;
        if (editingProject) {
            savedProject = await db.updateProject({ ...editingProject, ...projectData } as Project);
        } else {
            savedProject = await db.addProject(projectData as Omit<Project, 'id'>);
        }

        // Sincronizar Docentes (solo si es admin o director)
        if (userPerms[savedProject.id]?.canEdit || isAdmin || !editingProject) {
            await db.deleteProjectTeachersByProject(savedProject.id);
            for (const a of assignments) {
                await db.addProjectTeacher({ projectId: savedProject.id, teacherId: a.teacherId, roleId: a.roleId });
            }

            // Sincronizar Estudiantes
            const prevProjectStudents = students.filter(s => s.projectId === savedProject.id);
            for (const s of prevProjectStudents) {
                if (!studentIds.includes(s.id)) {
                    await db.updateStudent({ ...s, projectId: null });
                }
            }
            for (const sid of studentIds) {
                const s = students.find(x => x.id === sid);
                if (s && s.projectId !== savedProject.id) {
                    await db.updateStudent({ ...s, projectId: savedProject.id });
                }
            }
        }

        loadData();
        setIsModalOpen(false);
    };

    const handleDelete = async () => {
        if (deletingProject) {
            await db.deleteProject(deletingProject.id);
            loadData();
            setDeletingProject(null);
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-black text-uninunez-onix font-display uppercase tracking-tight">Gestión Académica</h1>
                    <p className="text-uninunez-ash text-sm font-medium">Control de trabajos de grado, evaluaciones y seguimiento.</p>
                </div>
                {isAdmin && (
                    <button 
                        onClick={() => { setEditingProject(null); setIsModalOpen(true); }} 
                        className="bg-uninunez-orange text-white px-6 py-3 rounded-xl flex items-center text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-uninunez-orangeLight transition-all active:scale-95"
                    >
                        <PlusIcon className="h-5 w-5 mr-2"/> Registrar Proyecto
                    </button>
                )}
            </div>

            <div className="bg-white shadow-sm border border-gray-100 rounded-3xl overflow-hidden">
                <div className="overflow-x-auto">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50/50 border-b border-gray-100">
                            <tr>
                                <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Proyecto</th>
                                <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Estado de Trámite</th>
                                <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-right">Acciones</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-50">
                            {projects.map(p => (
                                <tr key={p.id} className="hover:bg-gray-50/50 transition-colors group">
                                    <td className="px-8 py-6">
                                        <div className="text-sm font-bold text-uninunez-onix group-hover:text-uninunez-orange transition-colors">{p.title}</div>
                                        <div className="text-[10px] text-gray-400 mt-1 uppercase font-bold tracking-tight">Radicado: {p.presentationDate}</div>
                                    </td>
                                    <td className="px-8 py-6">
                                        <span className="px-3 py-1.5 text-[10px] font-black uppercase tracking-wider rounded-lg bg-uninunez-teal/10 text-uninunez-teal">
                                            {statuses.find(s => s.id === p.statusId)?.name || 'POR DEFINIR'}
                                        </span>
                                    </td>
                                    <td className="px-8 py-6 text-right">
                                        <div className="flex justify-end gap-2">
                                            {(userPerms[p.id]?.canEdit || userPerms[p.id]?.grade.canGrade) && (
                                                <button onClick={() => { setEditingProject(p); setIsModalOpen(true); }} className="p-2.5 bg-uninunez-teal/5 text-uninunez-teal hover:bg-uninunez-teal hover:text-white rounded-xl transition-all">
                                                    <EditIcon className="h-5 w-5"/>
                                                </button>
                                            )}
                                            {userPerms[p.id]?.canEdit && (
                                                <button onClick={() => setDeletingProject(p)} className="p-2.5 bg-red-50 text-red-500 hover:bg-red-500 hover:text-white rounded-xl transition-all">
                                                    <TrashIcon className="h-5 w-5"/>
                                                </button>
                                            )}
                                        </div>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingProject ? 'Ficha Técnica de Proyecto' : 'Registro de Nuevo Proyecto'}>
                {isModalOpen && (
                    <ProjectForm 
                        project={editingProject} 
                        onSave={handleSave} 
                        onClose={() => setIsModalOpen(false)} 
                        statuses={statuses} 
                        formats={formats} 
                        teachers={teachers} 
                        allStudents={students}
                        roles={roles} 
                        initialAssignments={editingProject ? projectTeachers.filter(pt => pt.projectId === editingProject.id) : []} 
                        initialStudentIds={editingProject ? students.filter(s => s.projectId === editingProject.id).map(s => s.id) : []}
                        canEditDetails={editingProject ? userPerms[editingProject.id]?.canEdit : isAdmin} 
                        gradeInfo={editingProject ? userPerms[editingProject.id]?.grade : {canGrade: false, reviewerRole: null, reviewerSlot: null}} 
                    />
                )}
            </Modal>
            <ConfirmationDialog isOpen={!!deletingProject} onClose={() => setDeletingProject(null)} onConfirm={handleDelete} title="Confirmar Eliminación" message="¿Estás seguro de que deseas eliminar este proyecto del banco institucional? Esta acción eliminará también las asignaciones y calificaciones registradas." />
        </div>
    );
};

import React, { createContext, useState, useContext, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { User } from '../types';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isAdmin: boolean;
  isTeacher: boolean;
  isStudent: boolean;
  canEditProject: (projectId: string) => Promise<boolean>;
  canGradeProject: (projectId: string) => Promise<{ canGrade: boolean, reviewerRole: string | null, reviewerSlot: 1 | 2 | 'admin' | null }>;
  login: (username: string, password: string) => Promise<boolean>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    const storedUser = localStorage.getItem('degreeProjectManagerUser');
    if (storedUser) {
      setUser(JSON.parse(storedUser));
    }
  }, []);

  const login = async (username: string, password: string): Promise<boolean> => {
    try {
        const foundUser = await db.getUserByUsername(username.trim());
        if (foundUser && String(foundUser.password).trim() === String(password).trim()) {
          setUser(foundUser);
          localStorage.setItem('degreeProjectManagerUser', JSON.stringify(foundUser));
          return true;
        }
    } catch (e) {
        console.error("Error en proceso de login:", e);
    }
    return false;
  };

  const logout = () => {
    setUser(null);
    localStorage.removeItem('degreeProjectManagerUser');
  };

  const getProjectAssignmentsForCurrentUser = async (projectId: string) => {
    if (!user || !user.teacherId) return [];
    const projectTeachers = await db.getProjectTeachers();
    const roles = await db.getTeacherRoles();
    return projectTeachers
      .filter(pt => pt.projectId === projectId && pt.teacherId === user.teacherId)
      .map(pt => ({
        roleName: roles.find(r => r.id === pt.roleId)?.name || '',
        roleId: pt.roleId
      }));
  };

  const canEditProject = async (projectId: string): Promise<boolean> => {
    if (!user) return false;
    if (user.role === 'admin') return true;
    if (user.role !== 'teacher') return false;
    const assignments = await getProjectAssignmentsForCurrentUser(projectId);
    // Un docente solo edita detalles si es director o co-director
    return assignments.some(a => 
        a.roleName.toLowerCase().includes('director') || 
        a.roleName.toLowerCase().includes('co-director')
    );
  };

  const canGradeProject = async (projectId: string): Promise<{ canGrade: boolean, reviewerRole: string | null, reviewerSlot: 1 | 2 | 'admin' | null }> => {
      if (!user) return { canGrade: false, reviewerRole: null, reviewerSlot: null };
      if (user.role === 'admin') return { canGrade: true, reviewerRole: 'admin', reviewerSlot: 'admin' };
      if (user.role !== 'teacher') return { canGrade: false, reviewerRole: null, reviewerSlot: null };

      const assignments = await getProjectAssignmentsForCurrentUser(projectId);

      // El Director califica en el Slot 1
      const isDirector = assignments.some(a => a.roleName.toLowerCase() === 'director');
      if (isDirector) return { canGrade: true, reviewerRole: 'Director', reviewerSlot: 1 };

      // El Co-Director califica en el Slot 2
      const isCoDirector = assignments.some(a => a.roleName.toLowerCase() === 'co-director');
      if (isCoDirector) return { canGrade: true, reviewerRole: 'Co-Director', reviewerSlot: 2 };

      return { canGrade: false, reviewerRole: null, reviewerSlot: null };
  };

  const isAuthenticated = !!user;
  const isAdmin = user?.role === 'admin';
  const isTeacher = user?.role === 'teacher';
  const isStudent = user?.role === 'student';

  return (
    <AuthContext.Provider value={{ user, isAuthenticated, isAdmin, isTeacher, isStudent, login, logout, canEditProject, canGradeProject }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { useState, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { Project, Student, Teacher, TeacherRole, Status, Format, ProjectTeacher } from '../types';
import { Modal } from '../components/Modal';
import { ConfirmationDialog } from '../components/ConfirmationDialog';
import { PlusIcon, EditIcon, TrashIcon } from '../components/Icons';
import { useAuth } from '../contexts/AuthContext';

const ProjectForm: React.FC<{
    project: Partial<Project> | null;
    onSave: (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => void;
    onClose: () => void;
    statuses: Status[];
    formats: Format[];
    teachers: Teacher[];
    allStudents: Student[];
    roles: TeacherRole[];
    initialAssignments: ProjectTeacher[];
    initialStudentIds: string[];
    canEditDetails: boolean;
    gradeInfo: { canGrade: boolean, reviewerRole: string | null, reviewerSlot: 1 | 2 | 'admin' | null };
}> = ({ project, onSave, onClose, statuses, formats, teachers, allStudents, roles, initialAssignments, initialStudentIds, canEditDetails, gradeInfo }) => {
    const { isAdmin } = useAuth();
    const [formData, setFormData] = useState<Partial<Project>>({});
    const [assignments, setAssignments] = useState<Array<{teacherId: string, roleId: string, tempId: number}>>([]);
    const [assignedStudentIds, setAssignedStudentIds] = useState<string[]>([]);
    const [newAssignment, setNewAssignment] = useState({ teacherId: '', roleId: '' });
    const [selectedStudentId, setSelectedStudentId] = useState('');

    useEffect(() => {
        const initialData: Partial<Project> = {
            title: '', presentationDate: '', filesUrl: '',
            statusId: statuses[0]?.id || '', formatId: formats[0]?.id || '',
            isApprovedByDirector: false, writtenGradeReviewer1: null,
            presentationGradeReviewer1: null, writtenGradeReviewer2: null,
            presentationGradeReviewer2: null, ...project
        };
        setFormData(initialData);
        setAssignments(initialAssignments.map(a => ({ teacherId: a.teacherId, roleId: a.roleId, tempId: Math.random() })));
        setAssignedStudentIds(initialStudentIds);
        setNewAssignment({ teacherId: '', roleId: '' });
        setSelectedStudentId('');
    }, [project, initialAssignments, initialStudentIds, statuses]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        let val: any = value;

        if (type === 'number') {
            if (value === '') {
                val = null;
            } else {
                const num = parseFloat(value);
                if (num < 1.0 || num > 5.0) return;
                val = num;
            }
        }
        setFormData(prev => ({ ...prev, [name]: val }));
    };

    const handleAddAssignment = () => {
        if (newAssignment.teacherId && newAssignment.roleId) {
            if (assignments.some(a => a.teacherId === newAssignment.teacherId)) {
                alert('Este docente ya ha sido asignado.'); return;
            }
            setAssignments(prev => [...prev, {...newAssignment, tempId: Math.random()}]);
            setNewAssignment({ teacherId: '', roleId: '' });
        }
    };

    const handleAddStudent = () => {
        if (selectedStudentId && !assignedStudentIds.includes(selectedStudentId)) {
            setAssignedStudentIds(prev => [...prev, selectedStudentId]);
            setSelectedStudentId('');
        }
    };

    const removeStudent = (id: string) => {
        setAssignedStudentIds(prev => prev.filter(sid => sid !== id));
    };

    const calculateFinalGrade = () => {
        const g1w = formData.writtenGradeReviewer1 ?? 0;
        const g1p = formData.presentationGradeReviewer1 ?? 0;
        const g2w = formData.writtenGradeReviewer2 ?? 0;
        const g2p = formData.presentationGradeReviewer2 ?? 0;

        let ev1Avg = 0;
        let ev2Avg = 0;
        let activeEvaluators = 0;

        if (g1w > 0 || g1p > 0) {
            ev1Avg = (g1w + g1p) / ((g1w > 0 ? 1 : 0) + (g1p > 0 ? 1 : 0));
            activeEvaluators++;
        }
        if (g2w > 0 || g2p > 0) {
            ev2Avg = (g2w + g2p) / ((g2w > 0 ? 1 : 0) + (g2p > 0 ? 1 : 0));
            activeEvaluators++;
        }

        if (activeEvaluators === 0) return "0.00";
        return ((ev1Avg + ev2Avg) / activeEvaluators).toFixed(2);
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        onSave(formData, assignments, assignedStudentIds);
    };

    const getTeacherName = (id: string) => teachers.find(t => t.id === id)?.name || 'Desconocido';
    const getRoleName = (id: string) => roles.find(r => r.id === id)?.name || 'Desconocido';
    const getStudentName = (id: string) => allStudents.find(s => s.id === id)?.name || 'Estudiante';

    const isGradingDisabled1 = !(isAdmin || gradeInfo.reviewerSlot === 1);
    const isGradingDisabled2 = !(isAdmin || gradeInfo.reviewerSlot === 2);

    return (
        <form onSubmit={handleSubmit} className="space-y-6">
            <div className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-[0.1em] mb-1.5 ml-1">Título del Proyecto</label>
                    <input type="text" name="title" value={formData.title || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-[0.1em] mb-1.5 ml-1">Fecha de Radicación</label>
                        <input type="date" name="presentationDate" value={formData.presentationDate || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails}/>
                    </div>
                    <div>
                        <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-[0.1em] mb-1.5 ml-1">Estado de Avance</label>
                        <select name="statusId" value={formData.statusId || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails && !gradeInfo.canGrade}>
                            {statuses.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            {/* SECCIÓN DE CALIFICACIONES - DIRECTOR Y CO-DIRECTOR */}
            <div className="bg-uninunez-onix/5 p-6 rounded-2xl border border-uninunez-onix/10 space-y-4">
                <div className="flex justify-between items-center border-b border-uninunez-onix/10 pb-4">
                    <h4 className="text-[11px] font-black text-uninunez-onix uppercase tracking-[0.2em]">Evaluación de Jurados (Directores)</h4>
                    <div className="flex items-center gap-3">
                        <span className="text-[10px] font-bold text-uninunez-ash uppercase">Nota Final:</span>
                        <div className="bg-uninunez-orange text-white px-4 py-1.5 rounded-lg text-sm font-black shadow-md min-w-[60px] text-center">
                            {calculateFinalGrade()}
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Panel Director */}
                    <div className={`p-4 rounded-xl border-2 transition-all ${!isGradingDisabled1 ? 'bg-white border-uninunez-teal shadow-md' : 'bg-gray-50 border-transparent opacity-60'}`}>
                        <div className="flex items-center justify-between mb-4">
                            <p className="text-[10px] font-black text-uninunez-teal uppercase tracking-widest">Director (Evaluador 1)</p>
                            {!isGradingDisabled1 && <span className="bg-uninunez-teal text-white text-[8px] px-2 py-0.5 rounded uppercase font-bold">Tú Calificas</span>}
                        </div>
                        <div className="space-y-3">
                            <div>
                                <label className="block text-[9px] font-bold text-gray-500 uppercase mb-1">Nota Escrita</label>
                                <input type="number" step="0.1" min="1" max="5" name="writtenGradeReviewer1" value={formData.writtenGradeReviewer1 ?? ''} onChange={handleChange} disabled={isGradingDisabled1} className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-teal font-bold text-uninunez-onix" placeholder="1.0 - 5.0" />
                            </div>
                            <div>
                                <label className="block text-[9px] font-bold text-gray-500 uppercase mb-1">Nota Sustentación</label>
                                <input type="number" step="0.1" min="1" max="5" name="presentationGradeReviewer1" value={formData.presentationGradeReviewer1 ?? ''} onChange={handleChange} disabled={isGradingDisabled1} className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-teal font-bold text-uninunez-onix" placeholder="1.0 - 5.0" />
                            </div>
                        </div>
                    </div>

                    {/* Panel Co-Director */}
                    <div className={`p-4 rounded-xl border-2 transition-all ${!isGradingDisabled2 ? 'bg-white border-uninunez-teal shadow-md' : 'bg-gray-50 border-transparent opacity-60'}`}>
                        <div className="flex items-center justify-between mb-4">
                            <p className="text-[10px] font-black text-uninunez-teal uppercase tracking-widest">Co-Director (Evaluador 2)</p>
                            {!isGradingDisabled2 && <span className="bg-uninunez-teal text-white text-[8px] px-2 py-0.5 rounded uppercase font-bold">Tú Calificas</span>}
                        </div>
                        <div className="space-y-3">
                            <div>
                                <label className="block text-[9px] font-bold text-gray-500 uppercase mb-1">Nota Escrita</label>
                                <input type="number" step="0.1" min="1" max="5" name="writtenGradeReviewer2" value={formData.writtenGradeReviewer2 ?? ''} onChange={handleChange} disabled={isGradingDisabled2} className="w-full border border-gray-200 rounded-lg px-3 py-2 text-sm focus:ring-uninunez-teal font-bold text-uninunez-onix" placeholder="1.0 - 5.0" />
                            </div>
