                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Panel Director */}
                    <div className={`p-4 rounded-xl border-2 transition-all ${!isGradingDisabled1 ? 'bg-white border-uninunez-teal shadow-md' : 'bg-gray-50 border-transparent opacity-60'}`}>
                        <div className="flex items-center justify-between mb-4">
                            <p className="text-[10px] font-black text-uninunez-teal uppercase tracking-widest">Director (Evaluador 1)</p>
                            {!isGradingDisabled1 && <span className="bg-uninunez-teal text-white text-[8px] px-2 py-0.5 rounded uppercase font-bold animate-pulse">Tu Turno</span>}
