});

const mapUserFromDB = (u: any): User => ({
    ...u,
    teacherId: u.teacher_id || u.teacherId || null,
    studentId: u.student_id || u.studentId || null
});

export const db = {
    initializeDB: async () => {
        const current = localStorage.getItem(LOCAL_STORAGE_KEY);
        if (!current) setLocalDB(initialDB);

        // Si hay Supabase, intentamos sincronizar la configuración básica al inicio
        if (supabase) {
            try {
                const { data: st } = await supabase.from('statuses').select('*');
                const { data: fm } = await supabase.from('formats').select('*');
                const { data: rl } = await supabase.from('teacher_roles').select('*');
                const { data: pr } = await supabase.from('programs').select('*');

                const db_local = getLocalDB();
                if (st?.length) db_local.statuses = st;
                if (fm?.length) db_local.formats = fm;
                if (rl?.length) db_local.teacherRoles = rl;
                if (pr?.length) db_local.programs = pr;
                setLocalDB(db_local);
            } catch (e) {
                console.warn("Error sincronizando maestros iniciales:", e);
            }
        }
    },

    checkConnection: async () => {
        if (!supabase) return true;
        try {
            const { error } = await supabase.from('users').select('id').limit(1);
            return !error;
        } catch {
            return false;
        }
    },

    // --- Lectura con Sincronización Automática (Cloud -> Local) ---
    getUsers: async () => {
        if (supabase) {
            const { data, error } = await supabase.from('users').select('*');
            if (!error && data) {
                const users = data.map(mapUserFromDB);
                const db_l = getLocalDB(); db_l.users = users; setLocalDB(db_l);
                return users;
            }
        }
        return getLocalDB().users;
    },

    getUserByUsername: async (username: string) => {
        const users = await db.getUsers();
        return users.find((u: User) => u.username.toLowerCase() === username.toLowerCase().trim()) || null;
    },

    getProjects: async () => {
        if (supabase) {
            const { data, error } = await supabase.from('projects').select('*').order('created_at', { ascending: false });
            if (!error && data) {
                const projects = data.map(mapProjectFromDB);
                const db_l = getLocalDB(); db_l.projects = projects; setLocalDB(db_l);
                return projects;
            }
        }
        return getLocalDB().projects;
    },

    getProjectById: async (id: string) => {
        if (supabase) {
            const { data } = await supabase.from('projects').select('*').eq('id', id).single();
            if (data) return mapProjectFromDB(data);
        }
        return (getLocalDB().projects).find((p: any) => p.id === id) || null;
    },

    getStudents: async () => {
        if (supabase) {
            const { data, error } = await supabase.from('students').select('*');
            if (!error && data) {
                const students = data.map((s: any) => ({ ...s, projectId: s.project_id, programId: s.program_id }));
                const db_l = getLocalDB(); db_l.students = students; setLocalDB(db_l);
                return students;
            }
        }
        return getLocalDB().students;
    },

    getTeachers: async () => {
        if (supabase) {
            const { data, error } = await supabase.from('teachers').select('*');
            if (!error && data) {
                const teachers = data;
                const db_l = getLocalDB(); db_l.teachers = teachers; setLocalDB(db_l);
                return teachers;
            }
        }
        return getLocalDB().teachers;
    },

    getProjectTeachers: async () => {
        if (supabase) {
            const { data, error } = await supabase.from('project_teachers').select('*');
            if (!error && data) {
                const pts = data.map((pt: any) => ({ id: pt.id, projectId: pt.project_id, teacherId: pt.teacher_id, roleId: pt.role_id }));
                const db_l = getLocalDB(); db_l.projectTeachers = pts; setLocalDB(db_l);
                return pts;
            }
        }
        return getLocalDB().projectTeachers;
    },

    // --- Escritura (Await Supabase for data integrity) ---
    addProject: async (project: Omit<Project, 'id'>) => {
        const id = generateId();
        const newProject = { ...project, id } as Project;

        if (supabase) {
            const { error } = await supabase.from('projects').insert([mapProjectToDB(newProject)]);
            if (error) throw error;
        }

        const db_l = getLocalDB();
        db_l.projects.unshift(newProject);
        setLocalDB(db_l);
        return newProject;
    },

    updateProject: async (project: Project) => {
        if (supabase) {
            const { error } = await supabase.from('projects').update(mapProjectToDB(project)).eq('id', project.id);
            if (error) throw error;
        }

        const db_l = getLocalDB();
        const idx = db_l.projects.findIndex((p: any) => p.id === project.id);
        if (idx !== -1) {
            db_l.projects[idx] = project;
            setLocalDB(db_l);
        }
        return project;
    },

    deleteProject: async (id: string) => {
        if (supabase) await supabase.from('projects').delete().eq('id', id);
        const db_l = getLocalDB();
        db_l.projects = db_l.projects.filter((p: any) => p.id !== id);
        setLocalDB(db_l);
    },

    addStudent: async (student: Omit<Student, 'id'>) => {
        const id = generateId();
        const newStudent = { ...student, id } as Student;
        const userId = generateId();

        if (supabase) {
            await supabase.from('students').insert([{ id, name: student.name, email: student.email, cedula: student.cedula, project_id: student.projectId, program_id: student.programId }]);
            await supabase.from('users').insert([{ id: userId, username: student.name, password: student.cedula, role: 'student', student_id: id }]);
        }

        const db_l = getLocalDB();
        db_l.students.push(newStudent);
        db_l.users.push({ id: userId, username: student.name, password: student.cedula, role: 'student', studentId: id, teacherId: null });
        setLocalDB(db_l);
        return newStudent;
    },

    updateStudent: async (student: Student) => {
        if (supabase) {
            await supabase.from('students').update({ name: student.name, email: student.email, cedula: student.cedula, project_id: student.projectId, program_id: student.programId }).eq('id', student.id);
            await supabase.from('users').update({ username: student.name, password: student.cedula }).eq('student_id', student.id);
        }
        const db_l = getLocalDB();
        const idx = db_l.students.findIndex((s: any) => s.id === student.id);
        if (idx !== -1) {
            db_l.students[idx] = student;
            const uIdx = db_l.users.findIndex((u: any) => u.studentId === student.id);
            if (uIdx !== -1) {
                db_l.users[uIdx].username = student.name;
                db_l.users[uIdx].password = student.cedula;
            }
            setLocalDB(db_l);
        }
        return student;
    },

    addProjectTeacher: async (pt: Omit<ProjectTeacher, 'id'>) => {
        const id = generateId();
        if (supabase) await supabase.from('project_teachers').insert([{ id, project_id: pt.projectId, teacher_id: pt.teacherId, role_id: pt.roleId }]);
        const db_l = getLocalDB();
        db_l.projectTeachers.push({ ...pt, id });
        setLocalDB(db_l);
        return { ...pt, id };
    },

    deleteProjectTeachersByProject: async (projectId: string) => {
        if (supabase) await supabase.from('project_teachers').delete().eq('project_id', projectId);
        const db_l = getLocalDB();
        db_l.projectTeachers = db_l.projectTeachers.filter((pt: any) => pt.projectId !== projectId);
        setLocalDB(db_l);
    },

    // --- Maestros (Sincronización Local) ---
    getStatuses: async () => { if (supabase) { const {data}=await supabase.from('statuses').select('*'); if(data) return data; } return getLocalDB().statuses; },
    getFormats: async () => { if (supabase) { const {data}=await supabase.from('formats').select('*'); if(data) return data; } return getLocalDB().formats; },
    getTeacherRoles: async () => { if (supabase) { const {data}=await supabase.from('teacher_roles').select('*'); if(data) return data; } return getLocalDB().teacherRoles; },
    getPrograms: async () => { if (supabase) { const {data}=await supabase.from('programs').select('*'); if(data) return data; } return getLocalDB().programs; },

    addStatus: async (p: Omit<Status, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('statuses').insert([{id, ...p}]); const db=getLocalDB(); db.statuses.push({id, ...p}); setLocalDB(db); return {id, ...p}; },
    addFormat: async (p: Omit<Format, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('formats').insert([{id, ...p}]); const db=getLocalDB(); db.formats.push({id, ...p}); setLocalDB(db); return {id, ...p}; },
    addProgram: async (p: Omit<Program, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('programs').insert([{id, ...p}]); const db=getLocalDB(); db.programs.push({id, ...p}); setLocalDB(db); return {id, ...p}; },
    addTeacherRole: async (p: Omit<TeacherRole, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('teacher_roles').insert([{id, ...p}]); const db=getLocalDB(); db.teacherRoles.push({id, ...p}); setLocalDB(db); return {id, ...p}; },

    deleteStudent: async (id: string) => { if (supabase) { await supabase.from('users').delete().eq('student_id', id); await supabase.from('students').delete().eq('id', id); } const db=getLocalDB(); db.students=db.students.filter((s:any)=>s.id!==id); db.users=db.users.filter((u:any)=>u.studentId!==id); setLocalDB(db); },
    deleteTeacher: async (id: string) => { if (supabase) { await supabase.from('users').delete().eq('teacher_id', id); await supabase.from('teachers').delete().eq('id', id); } const db=getLocalDB(); db.teachers=db.teachers.filter((t:any)=>t.id!==id); db.users=db.users.filter((u:any)=>u.teacherId!==id); setLocalDB(db); },
    deleteUser: async (id: string) => { if (supabase) await supabase.from('users').delete().eq('id', id); const db=getLocalDB(); db.users=db.users.filter((u:any)=>u.id!==id); setLocalDB(db); },
    getStudentById: async (id: string) => { const sts = await db.getStudents(); return sts.find((s:any)=>s.id===id)||null; }
};

import React, { useState, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { Project, Student, Teacher, TeacherRole, Status, Format, ProjectTeacher } from '../types';
import { Modal } from '../components/Modal';
import { ConfirmationDialog } from '../components/ConfirmationDialog';
import { PlusIcon, EditIcon, TrashIcon } from '../components/Icons';
import { useAuth } from '../contexts/AuthContext';

const ProjectForm: React.FC<{
    project: Partial<Project> | null;
    onSave: (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => Promise<void>;
    onClose: () => void;
    statuses: Status[];
    formats: Format[];
    teachers: Teacher[];
    allStudents: Student[];
    roles: TeacherRole[];
    initialAssignments: ProjectTeacher[];
    initialStudentIds: string[];
    canEditDetails: boolean;
    gradeInfo: { canGrade: boolean, reviewerRole: string | null };
}> = ({ project, onSave, onClose, statuses, formats, teachers, allStudents, roles, initialAssignments, initialStudentIds, canEditDetails, gradeInfo }) => {
    const { isAdmin } = useAuth();
    const [formData, setFormData] = useState<Partial<Project>>({});
    const [assignments, setAssignments] = useState<Array<{teacherId: string, roleId: string, tempId: number}>>([]);
    const [assignedStudentIds, setAssignedStudentIds] = useState<string[]>([]);
    const [newAssignment, setNewAssignment] = useState({ teacherId: '', roleId: '' });
    const [selectedStudentId, setSelectedStudentId] = useState('');
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        const initialData: Partial<Project> = {
            title: '', presentationDate: '', filesUrl: '',
            statusId: statuses[0]?.id || '', formatId: formats[0]?.id || '',
            isApprovedByDirector: false, writtenGradeReviewer1: null,
            presentationGradeReviewer1: null, writtenGradeReviewer2: null,
            presentationGradeReviewer2: null, ...project
        };
        setFormData(initialData);
        setAssignments(initialAssignments.map(a => ({ teacherId: a.teacherId, roleId: a.roleId, tempId: Math.random() })));
        setAssignedStudentIds(initialStudentIds);
        setNewAssignment({ teacherId: '', roleId: '' });
        setSelectedStudentId('');
    }, [project, initialAssignments, initialStudentIds, statuses]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        let finalValue: any = value;
        if (type === 'number' && value !== '') finalValue = parseFloat(value);
        if (type === 'number' && value === '') finalValue = null;
        setFormData(prev => ({ ...prev, [name]: finalValue }));
    };

    const handleAddAssignment = () => {
        if (newAssignment.teacherId && newAssignment.roleId) {
            if (assignments.some(a => a.teacherId === newAssignment.teacherId)) {
                alert('Este docente ya ha sido asignado.'); return;
            }
            setAssignments(prev => [...prev, {...newAssignment, tempId: Math.random()}]);
            setNewAssignment({ teacherId: '', roleId: '' });
        }
    };

    const handleAddStudent = () => {
        if (selectedStudentId && !assignedStudentIds.includes(selectedStudentId)) {
            setAssignedStudentIds(prev => [...prev, selectedStudentId]);
            setSelectedStudentId('');
        }
    };

    const removeStudent = (id: string) => {
        setAssignedStudentIds(prev => prev.filter(sid => sid !== id));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (isSaving) return;

        if (!formData.title?.trim() || !formData.presentationDate) {
            alert("El Título y la Fecha son campos obligatorios.");
            return;
        }

        setIsSaving(true);
        try {
            await onSave(formData, assignments, assignedStudentIds);
            onClose();
        } catch (error) {
            console.error("Error al guardar el proyecto:", error);
            alert("No se pudo guardar el proyecto. Verifique la conexión a la base de datos.");
        } finally {
            setIsSaving(false);
        }
    };

    const getTeacherName = (id: string) => teachers.find(t => t.id === id)?.name || 'Desconocido';
    const getRoleName = (id: string) => roles.find(r => r.id === id)?.name || 'Desconocido';
    const getStudentName = (id: string) => allStudents.find(s => s.id === id)?.name || 'Estudiante';

    // Notas de evaluadores
    const canGradeReviewer1 = isAdmin || (gradeInfo.canGrade && gradeInfo.reviewerRole?.toLowerCase().includes('1'));
    const canGradeReviewer2 = isAdmin || (gradeInfo.canGrade && gradeInfo.reviewerRole?.toLowerCase().includes('2'));

    return (
        <form onSubmit={handleSubmit} className="space-y-6 max-h-[70vh] overflow-y-auto pr-2">
            <div className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-1 ml-1">Título Institucional</label>
                    <input type="text" name="title" value={formData.title || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-1 ml-1">Fecha Radicación</label>
                        <input type="date" name="presentationDate" value={formData.presentationDate || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails}/>
                    </div>
                    <div>
                        <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-1 ml-1">Estado del Proyecto</label>
                        <select name="statusId" value={formData.statusId || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails && !gradeInfo.canGrade}>
                            {statuses.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 space-y-4">
                <h4 className="text-[10px] font-black text-uninunez-onix uppercase tracking-widest border-b pb-2">Calificaciones Académicas</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className={`p-3 rounded-xl border ${canGradeReviewer1 ? 'bg-white border-uninunez-teal/30' : 'bg-gray-100'}`}>
                        <p className="text-[9px] font-bold text-uninunez-teal uppercase mb-2">Evaluador 1</p>
                        <div className="grid grid-cols-2 gap-2">
                            <input type="number" step="0.1" name="writtenGradeReviewer1" placeholder="Escrito" value={formData.writtenGradeReviewer1 ?? ''} onChange={handleChange} disabled={!canGradeReviewer1} className="text-xs border rounded p-2" />
                            <input type="number" step="0.1" name="presentationGradeReviewer1" placeholder="Sust." value={formData.presentationGradeReviewer1 ?? ''} onChange={handleChange} disabled={!canGradeReviewer1} className="text-xs border rounded p-2" />
                        </div>
                    </div>
                    <div className={`p-3 rounded-xl border ${canGradeReviewer2 ? 'bg-white border-uninunez-teal/30' : 'bg-gray-100'}`}>
                        <p className="text-[9px] font-bold text-uninunez-teal uppercase mb-2">Evaluador 2</p>
                        <div className="grid grid-cols-2 gap-2">
                            <input type="number" step="0.1" name="writtenGradeReviewer2" placeholder="Escrito" value={formData.writtenGradeReviewer2 ?? ''} onChange={handleChange} disabled={!canGradeReviewer2} className="text-xs border rounded p-2" />
                            <input type="number" step="0.1" name="presentationGradeReviewer2" placeholder="Sust." value={formData.presentationGradeReviewer2 ?? ''} onChange={handleChange} disabled={!canGradeReviewer2} className="text-xs border rounded p-2" />
                        </div>
                    </div>
                </div>
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-4">Integrantes (Estudiantes)</h4>
                <div className="flex flex-wrap gap-2 mb-3">
                    {assignedStudentIds.map(sid => (
                        <div key={sid} className="flex items-center bg-white px-3 py-1.5 rounded-full border border-gray-200 shadow-sm">
                            <span className="text-[10px] font-bold text-gray-700 mr-2">{getStudentName(sid)}</span>
                            {canEditDetails && (
                                <button type="button" onClick={() => removeStudent(sid)} className="text-red-400 hover:text-red-600">
                                    <TrashIcon className="h-3.5 w-3.5"/>
                                </button>
                            )}
                        </div>
                    ))}
                </div>
                {canEditDetails && (
                    <div className="flex gap-2">
                        <select value={selectedStudentId} onChange={(e) => setSelectedStudentId(e.target.value)} className="flex-grow border border-gray-200 rounded-xl px-3 py-2 text-sm">
                            <option value="">Seleccionar Estudiante...</option>
                            {allStudents.filter(s => (!s.projectId || assignedStudentIds.includes(s.id)) && !assignedStudentIds.includes(s.id)).map(s => (
                                <option key={s.id} value={s.id}>{s.name}</option>
                            ))}
                        </select>
                        <button type="button" onClick={handleAddStudent} className="bg-uninunez-orange text-white px-4 rounded-xl text-[10px] font-black uppercase">Añadir</button>
                    </div>
                )}
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-4">Asignaciones (Docentes)</h4>
                <div className="space-y-2 mb-4">
                    {assignments.map(a => (
                        <div key={a.tempId} className="flex justify-between items-center bg-white px-4 py-2 rounded-xl border border-gray-100 shadow-sm">
                            <span className="text-[11px] font-bold text-gray-700">{getTeacherName(a.teacherId)} — <span className="text-uninunez-teal uppercase font-black">{getRoleName(a.roleId)}</span></span>
                            {canEditDetails && (
                                <button type="button" onClick={() => setAssignments(prev => prev.filter(x => x.tempId !== a.tempId))} className="text-red-400 hover:text-red-600">
                                    <TrashIcon className="h-4 w-4"/>
                                </button>
                            )}
                        </div>
                    ))}
                </div>
                {canEditDetails && (
                    <div className="grid grid-cols-1 sm:grid-cols-7 gap-2">
                        <select value={newAssignment.teacherId} onChange={(e) => setNewAssignment(p => ({...p, teacherId: e.target.value}))} className="sm:col-span-3 border border-gray-200 rounded-xl px-3 py-2 text-sm">
                            <option value="">Docente...</option>
                            {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                        </select>
                        <select value={newAssignment.roleId} onChange={(e) => setNewAssignment(p => ({...p, roleId: e.target.value}))} className="sm:col-span-3 border border-gray-200 rounded-xl px-3 py-2 text-sm">
                            <option value="">Rol...</option>
                            {roles.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                        </select>
                        <button type="button" onClick={handleAddAssignment} className="sm:col-span-1 bg-uninunez-orange text-white rounded-xl text-[10px] font-black uppercase">Añadir</button>
                    </div>
                )}
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t sticky bottom-0 bg-white">
                <button type="button" onClick={onClose} disabled={isSaving} className="px-6 py-3 border-2 border-gray-100 rounded-xl text-[10px] font-black uppercase text-gray-400 hover:bg-gray-50 transition-all">Cancelar</button>
                <button type="submit" disabled={isSaving} className={`px-10 py-3 rounded-xl text-[10px] font-black uppercase shadow-xl transition-all ${isSaving ? 'bg-gray-400' : 'bg-uninunez-orange hover:bg-uninunez-orangeLight text-white'}`}>
                    {isSaving ? 'Guardando...' : 'Guardar Proyecto'}
                </button>
            </div>
        </form>
    );
};

export const ProjectsPage: React.FC = () => {
    const { isAdmin, canEditProject, canGradeProject } = useAuth();
    const [projects, setProjects] = useState<Project[]>([]);
    const [students, setStudents] = useState<Student[]>([]);
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [roles, setRoles] = useState<TeacherRole[]>([]);
    const [statuses, setStatuses] = useState<Status[]>([]);
    const [formats, setFormats] = useState<Format[]>([]);
    const [projectTeachers, setProjectTeachers] = useState<ProjectTeacher[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);

    const [userPerms, setUserPerms] = useState<Record<string, {canEdit: boolean, grade: {canGrade: boolean, reviewerRole: string | null}}>>({});

    const loadData = useCallback(async () => {
        setIsLoading(true);
        try {
            const [p, s, t, r, st, f, pt] = await Promise.all([
                db.getProjects(), db.getStudents(), db.getTeachers(),
                db.getTeacherRoles(), db.getStatuses(), db.getFormats(),
                db.getProjectTeachers()
            ]);

            const perms: any = {};
            for(const project of p) {
                perms[project.id] = {
                    canEdit: await canEditProject(project.id),
                    grade: await canGradeProject(project.id)
                };
            }

            setProjects([...p]);
            setStudents(s);
            setTeachers(t);
            setRoles(r);
            setStatuses(st);
            setFormats(f);
            setProjectTeachers(pt);
            setUserPerms(perms);
        } catch (error) {
            console.error("Error cargando el banco de proyectos:", error);
        } finally {
            setIsLoading(false);
        }
    }, [canEditProject, canGradeProject]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => {
        try {
            let savedProject: Project;
            const isEditing = !!editingProject;

            if (isEditing) {
                savedProject = await db.updateProject({ ...editingProject, ...projectData } as Project);
            } else {
                savedProject = await db.addProject(projectData as Omit<Project, 'id'>);
            }

            // Actualizar vínculos si tiene permisos
            if (!isEditing || isAdmin || userPerms[savedProject.id]?.canEdit) {
                await db.deleteProjectTeachersByProject(savedProject.id);
                for (const a of assignments) {
                    await db.addProjectTeacher({ projectId: savedProject.id, teacherId: a.teacherId, roleId: a.roleId });
                }

                // Sincronización de estudiantes de forma secuencial
                const studentsData = await db.getStudents();
                const currentStudentsOfProject = studentsData.filter(s => s.projectId === savedProject.id);

                // 1. Quitar estudiantes que ya no están vinculados
                for (const s of currentStudentsOfProject) {
                    if (!studentIds.includes(s.id)) {
                        await db.updateStudent({ ...s, projectId: null });
                    }
                }
                // 2. Vincular nuevos seleccionados
                for (const sid of studentIds) {
                    const student = studentsData.find(s => s.id === sid);
                    if (student && student.projectId !== savedProject.id) {
                        await db.updateStudent({ ...student, projectId: savedProject.id });
                    }
                }
            }

            await loadData();
            setIsModalOpen(false);
        } catch (err) {
            console.error("Error crítico guardando proyecto:", err);
            throw err;
        }
    };

    const handleDelete = async () => {
        if (deletingProject) {
            try {
                await db.deleteProject(deletingProject.id);
                await loadData();
                setDeletingProject(null);
            } catch (err) {
                alert("No se pudo eliminar el proyecto.");
            }
        }
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-black text-uninunez-onix font-display uppercase tracking-tight">Banco Institucional</h1>
                    <p className="text-uninunez-ash text-sm font-medium">Gestión integral de trabajos de grado y asignaciones docentes.</p>
                </div>
                {isAdmin && (
                    <button 
                        onClick={() => { setEditingProject(null); setIsModalOpen(true); }} 
                        className="bg-uninunez-orange text-white px-6 py-3 rounded-xl flex items-center text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-uninunez-orangeLight transition-all active:scale-95"
                    >
                        <PlusIcon className="h-5 w-5 mr-2"/> Nuevo Proyecto
                    </button>
                )}
            </div>

            <div className="bg-white shadow-sm border border-gray-100 rounded-3xl overflow-hidden min-h-[400px]">
                {isLoading ? (
                    <div className="flex flex-col items-center justify-center py-20 space-y-4">
                        <div className="w-12 h-12 border-4 border-uninunez-orange border-t-transparent rounded-full animate-spin"></div>
                        <p className="text-xs font-black text-uninunez-ash uppercase tracking-widest">Sincronizando Banco de Proyectos...</p>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-gray-50/50 border-b border-gray-100">
                                <tr>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Título del Proyecto</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Estado Actual</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-right">Acciones</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-50">
                                {projects.map(p => (
                                    <tr key={p.id} className="hover:bg-gray-50/50 transition-colors group">
                                        <td className="px-8 py-6">
                                            <div className="text-sm font-bold text-uninunez-onix group-hover:text-uninunez-orange transition-colors">{p.title}</div>
                                            <div className="text-[10px] text-gray-400 mt-1 uppercase font-bold tracking-tight">Presentado el: {p.presentationDate}</div>
                                        </td>
                                        <td className="px-8 py-6">
                                            <span className="px-3 py-1.5 text-[10px] font-black uppercase tracking-wider rounded-lg bg-uninunez-teal/10 text-uninunez-teal">
                                                {statuses.find(s => s.id === p.statusId)?.name || 'POR ASIGNAR'}
                                            </span>
                                        </td>
                                        <td className="px-8 py-6 text-right">
                                            <div className="flex justify-end gap-2">
                                                {(isAdmin || userPerms[p.id]?.canEdit || userPerms[p.id]?.grade.canGrade) && (
                                                    <button onClick={() => { setEditingProject(p); setIsModalOpen(true); }} className="p-2.5 bg-uninunez-teal/5 text-uninunez-teal hover:bg-uninunez-teal hover:text-white rounded-xl transition-all">
                                                        <EditIcon className="h-5 w-5"/>
                                                    </button>
                                                )}
                                                {(isAdmin || userPerms[p.id]?.canEdit) && (
                                                    <button onClick={() => setDeletingProject(p)} className="p-2.5 bg-red-50 text-red-500 hover:bg-red-500 hover:text-white rounded-xl transition-all">
                                                        <TrashIcon className="h-5 w-5"/>
                                                    </button>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                                {projects.length === 0 && (
                                    <tr>
                                        <td colSpan={3} className="text-center py-20 text-gray-400 italic text-sm">No se han registrado proyectos en la plataforma todavía.</td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingProject ? 'Expediente de Proyecto' : 'Registro de Nuevo Trabajo'}>
                {isModalOpen && (
                    <ProjectForm 
                        project={editingProject} 
                        onSave={handleSave} 
                        onClose={() => setIsModalOpen(false)} 
                        statuses={statuses} 
                        formats={formats} 
                        teachers={teachers} 
                        allStudents={students}
                        roles={roles} 
                        initialAssignments={editingProject ? projectTeachers.filter(pt => pt.projectId === editingProject.id) : []} 
                        initialStudentIds={editingProject ? students.filter(s => s.projectId === editingProject.id).map(s => s.id) : []}
                        canEditDetails={editingProject ? (isAdmin || userPerms[editingProject.id]?.canEdit) : true} 
                        gradeInfo={editingProject ? userPerms[editingProject.id]?.grade : {canGrade: false, reviewerRole: null}} 
                    />
                )}
            </Modal>
            <ConfirmationDialog isOpen={!!deletingProject} onClose={() => setDeletingProject(null)} onConfirm={handleDelete} title="Confirmar Eliminación" message="¿Estás seguro de que deseas eliminar este proyecto del banco institucional? Esta acción eliminará permanentemente todos los vínculos y notas asociadas." />
        </div>
    );
};

// @ts-ignore - Importación directa desde CDN
import { createClient } from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';
import { Project, Student, Teacher, ProjectTeacher, Format, TeacherRole, Status, Program, User } from '../types';

const supabaseUrl = (import.meta as any).env?.VITE_SUPABASE_URL || '';
const supabaseAnonKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || '';

export const isSupabaseConfigured = !!(supabaseUrl && supabaseAnonKey && supabaseUrl.startsWith('http'));

// @ts-ignore
export const supabase = isSupabaseConfigured 
    ? createClient(supabaseUrl, supabaseAnonKey) 
    : null;

const generateId = (): string => Date.now().toString(36) + Math.random().toString(36).substring(2);

const LOCAL_STORAGE_KEY = 'uninunez_db_final_v1';

const initialDB = {
    users: [{ id: 'admin-id', username: 'admin', password: 'admin123', role: 'admin', teacherId: null, studentId: null }],
    projects: [],
    programs: [{ id: '1', name: 'Ingeniería de Sistemas' }, { id: '2', name: 'Derecho' }, { id: '3', name: 'Medicina' }],
    students: [],
    teachers: [],
    projectTeachers: [],
    formats: [{ id: '1', name: 'Anteproyecto' }, { id: '2', name: 'Proyecto Final' }],
    teacherRoles: [{ id: '1', name: 'Director' }, { id: '2', name: 'Co-Director' }, { id: '3', name: 'Evaluador 1' }, { id: '4', name: 'Evaluador 2' }],
    statuses: [{ id: '1', name: 'En Proceso' }, { id: '2', name: 'Aprobado' }, { id: '3', name: 'Sustentado' }, { id: '4', name: 'Rechazado' }]
};

const getLocalDB = (): any => {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (!data) return initialDB;
    try {
        return { ...initialDB, ...JSON.parse(data) };
    } catch {
        return initialDB;
    }
};

const setLocalDB = (db: any) => {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(db));
};

// --- Mapeos Estrictos para Supabase ---
const mapProjectToDB = (p: Partial<Project>) => ({
    id: p.id,
    title: p.title,
    presentation_date: p.presentationDate || null,
    files_url: p.filesUrl || '',
    status_id: p.statusId || null,
    format_id: p.formatId || null,
    is_approved_by_director: !!p.isApprovedByDirector,
    written_grade_reviewer1: typeof p.writtenGradeReviewer1 === 'number' ? p.writtenGradeReviewer1 : null,
    presentation_grade_reviewer1: typeof p.presentationGradeReviewer1 === 'number' ? p.presentationGradeReviewer1 : null,
    written_grade_reviewer2: typeof p.writtenGradeReviewer2 === 'number' ? p.writtenGradeReviewer2 : null,
    presentation_grade_reviewer2: typeof p.presentationGradeReviewer2 === 'number' ? p.presentationGradeReviewer2 : null
});

const mapProjectFromDB = (p: any): Project => ({
    id: p.id,
    title: p.title,
    presentationDate: p.presentation_date || p.presentationDate || '',
    filesUrl: p.files_url || p.filesUrl || '',
    statusId: p.status_id || p.statusId || '',
    formatId: p.format_id || p.formatId || '',
    isApprovedByDirector: p.is_approved_by_director ?? p.isApprovedByDirector ?? false,
    writtenGradeReviewer1: p.written_grade_reviewer1 ?? p.writtenGradeReviewer1 ?? null,
    presentationGradeReviewer1: p.presentation_grade_reviewer1 ?? p.presentationGradeReviewer1 ?? null,
    writtenGradeReviewer2: p.written_grade_reviewer2 ?? p.writtenGradeReviewer2 ?? null,
    presentationGradeReviewer2: p.presentation_grade_reviewer2 ?? p.presentationGradeReviewer2 ?? null
});

const mapUserFromDB = (u: any): User => ({
    ...u,
    teacherId: u.teacher_id || u.teacherId || null,
    studentId: u.student_id || u.studentId || null
});

export const db = {
    initializeDB: async () => {
        const current = localStorage.getItem(LOCAL_STORAGE_KEY);
        if (!current) setLocalDB(initialDB);

        // Si hay Supabase, intentamos sincronizar la configuración básica al inicio
        if (supabase) {
            try {
                const { data: st } = await supabase.from('statuses').select('*');
                const { data: fm } = await supabase.from('formats').select('*');
                const { data: rl } = await supabase.from('teacher_roles').select('*');
                const { data: pr } = await supabase.from('programs').select('*');

                const db_local = getLocalDB();
                if (st?.length) db_local.statuses = st;
                if (fm?.length) db_local.formats = fm;
                if (rl?.length) db_local.teacherRoles = rl;
                if (pr?.length) db_local.programs = pr;
                setLocalDB(db_local);
            } catch (e) {
                console.warn("Error sincronizando maestros iniciales:", e);
            }
        }
    },

    checkConnection: async () => {
        if (!supabase) return true;
        try {
            const { error } = await supabase.from('users').select('id').limit(1);
            return !error;
        } catch {
            return false;
        }
    },

    // --- Lectura con Sincronización Automática (Cloud -> Local) ---
    getUsers: async () => {
        if (supabase) {
            const { data, error } = await supabase.from('users').select('*');
            if (!error && data) {
                const users = data.map(mapUserFromDB);
                const db_l = getLocalDB(); db_l.users = users; setLocalDB(db_l);
                return users;
            }
        }
        return getLocalDB().users;
    },

    getUserByUsername: async (username: string) => {
        const users = await db.getUsers();
        return users.find((u: User) => u.username.toLowerCase() === username.toLowerCase().trim()) || null;
    },

    getProjects: async () => {
        if (supabase) {
            const { data, error } = await supabase.from('projects').select('*').order('created_at', { ascending: false });
            if (!error && data) {
                const projects = data.map(mapProjectFromDB);
                const db_l = getLocalDB(); db_l.projects = projects; setLocalDB(db_l);
                return projects;
            }
        }
        return getLocalDB().projects;
    },

    getProjectById: async (id: string) => {
        if (supabase) {
            const { data } = await supabase.from('projects').select('*').eq('id', id).single();
            if (data) return mapProjectFromDB(data);
        }
        return (getLocalDB().projects).find((p: any) => p.id === id) || null;
    },

    getStudents: async () => {
        if (supabase) {
            const { data, error } = await supabase.from('students').select('*');
            if (!error && data) {
                const students = data.map((s: any) => ({ ...s, projectId: s.project_id, programId: s.program_id }));
                const db_l = getLocalDB(); db_l.students = students; setLocalDB(db_l);
                return students;
            }
        }
        return getLocalDB().students;
    },

    getTeachers: async () => {
        if (supabase) {
            const { data, error } = await supabase.from('teachers').select('*');
            if (!error && data) {
                const teachers = data;
                const db_l = getLocalDB(); db_l.teachers = teachers; setLocalDB(db_l);
                return teachers;
            }
        }
        return getLocalDB().teachers;
    },

    getProjectTeachers: async () => {
        if (supabase) {
            const { data, error } = await supabase.from('project_teachers').select('*');
            if (!error && data) {
                const pts = data.map((pt: any) => ({ id: pt.id, projectId: pt.project_id, teacherId: pt.teacher_id, roleId: pt.role_id }));
                const db_l = getLocalDB(); db_l.projectTeachers = pts; setLocalDB(db_l);
                return pts;
            }
        }
        return getLocalDB().projectTeachers;
    },

    // --- Escritura (Await Supabase for data integrity) ---
    addProject: async (project: Omit<Project, 'id'>) => {
        const id = generateId();
        const newProject = { ...project, id } as Project;

        if (supabase) {
            const { error } = await supabase.from('projects').insert([mapProjectToDB(newProject)]);
            if (error) throw error;
        }

        const db_l = getLocalDB();
        db_l.projects.unshift(newProject);
        setLocalDB(db_l);
        return newProject;
    },

    updateProject: async (project: Project) => {
        if (supabase) {
            const { error } = await supabase.from('projects').update(mapProjectToDB(project)).eq('id', project.id);
            if (error) throw error;
        }

        const db_l = getLocalDB();
        const idx = db_l.projects.findIndex((p: any) => p.id === project.id);
        if (idx !== -1) {
            db_l.projects[idx] = project;
            setLocalDB(db_l);
        }
        return project;
    },

    deleteProject: async (id: string) => {
        if (supabase) await supabase.from('projects').delete().eq('id', id);
        const db_l = getLocalDB();
        db_l.projects = db_l.projects.filter((p: any) => p.id !== id);
        setLocalDB(db_l);
    },

    addStudent: async (student: Omit<Student, 'id'>) => {
        const id = generateId();
        const newStudent = { ...student, id } as Student;
        const userId = generateId();

        if (supabase) {
            await supabase.from('students').insert([{ id, name: student.name, email: student.email, cedula: student.cedula, project_id: student.projectId, program_id: student.programId }]);
            await supabase.from('users').insert([{ id: userId, username: student.name, password: student.cedula, role: 'student', student_id: id }]);
        }

        const db_l = getLocalDB();
        db_l.students.push(newStudent);
        db_l.users.push({ id: userId, username: student.name, password: student.cedula, role: 'student', studentId: id, teacherId: null });
        setLocalDB(db_l);
        return newStudent;
    },

    updateStudent: async (student: Student) => {
        if (supabase) {
            await supabase.from('students').update({ name: student.name, email: student.email, cedula: student.cedula, project_id: student.projectId, program_id: student.programId }).eq('id', student.id);
            await supabase.from('users').update({ username: student.name, password: student.cedula }).eq('student_id', student.id);
        }
        const db_l = getLocalDB();
        const idx = db_l.students.findIndex((s: any) => s.id === student.id);
        if (idx !== -1) {
            db_l.students[idx] = student;
            const uIdx = db_l.users.findIndex((u: any) => u.studentId === student.id);
            if (uIdx !== -1) {
                db_l.users[uIdx].username = student.name;
                db_l.users[uIdx].password = student.cedula;
            }
            setLocalDB(db_l);
        }
        return student;
    },

    // Fix: Added missing addTeacher method to handle teacher and associated user creation
    addTeacher: async (teacher: Omit<Teacher, 'id'>) => {
        const id = generateId();
        const newTeacher = { ...teacher, id } as Teacher;
        const userId = generateId();

        if (supabase) {
            await supabase.from('teachers').insert([{ id, name: teacher.name, email: teacher.email, cedula: teacher.cedula }]);
            await supabase.from('users').insert([{ id: userId, username: teacher.name, password: teacher.cedula, role: 'teacher', teacher_id: id }]);
        }

        const db_l = getLocalDB();
        db_l.teachers.push(newTeacher);
        db_l.users.push({ id: userId, username: teacher.name, password: teacher.cedula, role: 'teacher', teacherId: id, studentId: null });
        setLocalDB(db_l);
        return newTeacher;
    },

    // Fix: Added missing updateTeacher method to sync teacher and user data
    updateTeacher: async (teacher: Teacher) => {
        if (supabase) {
            await supabase.from('teachers').update({ name: teacher.name, email: teacher.email, cedula: teacher.cedula }).eq('id', teacher.id);
            await supabase.from('users').update({ username: teacher.name, password: teacher.cedula }).eq('teacher_id', teacher.id);
        }
        const db_l = getLocalDB();
        const idx = db_l.teachers.findIndex((t: any) => t.id === teacher.id);
        if (idx !== -1) {
            db_l.teachers[idx] = teacher;
            const uIdx = db_l.users.findIndex((u: any) => u.teacherId === teacher.id);
            if (uIdx !== -1) {
                db_l.users[uIdx].username = teacher.name;
                db_l.users[uIdx].password = teacher.cedula;
            }
            setLocalDB(db_l);
        }
        return teacher;
    },

    addProjectTeacher: async (pt: Omit<ProjectTeacher, 'id'>) => {
        const id = generateId();
        if (supabase) await supabase.from('project_teachers').insert([{ id, project_id: pt.projectId, teacher_id: pt.teacherId, role_id: pt.roleId }]);
        const db_l = getLocalDB();
        db_l.projectTeachers.push({ ...pt, id });
        setLocalDB(db_l);
        return { ...pt, id };
    },

    deleteProjectTeachersByProject: async (projectId: string) => {
        if (supabase) await supabase.from('project_teachers').delete().eq('project_id', projectId);
        const db_l = getLocalDB();
        db_l.projectTeachers = db_l.projectTeachers.filter((pt: any) => pt.projectId !== projectId);
        setLocalDB(db_l);
    },

    // --- Maestros (Sincronización Local) ---
    getStatuses: async () => { if (supabase) { const {data}=await supabase.from('statuses').select('*'); if(data) return data; } return getLocalDB().statuses; },
    getFormats: async () => { if (supabase) { const {data}=await supabase.from('formats').select('*'); if(data) return data; } return getLocalDB().formats; },
    getTeacherRoles: async () => { if (supabase) { const {data}=await supabase.from('teacher_roles').select('*'); if(data) return data; } return getLocalDB().teacherRoles; },
    getPrograms: async () => { if (supabase) { const {data}=await supabase.from('programs').select('*'); if(data) return data; } return getLocalDB().programs; },

    addStatus: async (p: Omit<Status, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('statuses').insert([{id, ...p}]); const db=getLocalDB(); db.statuses.push({id, ...p}); setLocalDB(db); return {id, ...p}; },
    addFormat: async (p: Omit<Format, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('formats').insert([{id, ...p}]); const db=getLocalDB(); db.formats.push({id, ...p}); setLocalDB(db); return {id, ...p}; },
    addProgram: async (p: Omit<Program, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('programs').insert([{id, ...p}]); const db=getLocalDB(); db.programs.push({id, ...p}); setLocalDB(db); return {id, ...p}; },
    addTeacherRole: async (p: Omit<TeacherRole, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('teacher_roles').insert([{id, ...p}]); const db=getLocalDB(); db.teacherRoles.push({id, ...p}); setLocalDB(db); return {id, ...p}; },

    // Fix: Added missing update methods for master entities (Status, Format, TeacherRole, Program)
    updateStatus: async (p: Status) => { if(supabase) await supabase.from('statuses').update({name: p.name}).eq('id', p.id); const db=getLocalDB(); const idx=db.statuses.findIndex((s:any)=>s.id===p.id); if(idx!==-1){db.statuses[idx]=p; setLocalDB(db);} return p; },
    updateFormat: async (p: Format) => { if(supabase) await supabase.from('formats').update({name: p.name}).eq('id', p.id); const db=getLocalDB(); const idx=db.formats.findIndex((s:any)=>s.id===p.id); if(idx!==-1){db.formats[idx]=p; setLocalDB(db);} return p; },
    updateTeacherRole: async (p: TeacherRole) => { if(supabase) await supabase.from('teacher_roles').update({name: p.name}).eq('id', p.id); const db=getLocalDB(); const idx=db.teacherRoles.findIndex((s:any)=>s.id===p.id); if(idx!==-1){db.teacherRoles[idx]=p; setLocalDB(db);} return p; },
    updateProgram: async (p: Program) => { if(supabase) await supabase.from('programs').update({name: p.name}).eq('id', p.id); const db=getLocalDB(); const idx=db.programs.findIndex((s:any)=>s.id===p.id); if(idx!==-1){db.programs[idx]=p; setLocalDB(db);} return p; },

    // Fix: Added missing delete methods for master entities (Status, Format, TeacherRole, Program)
    deleteStatus: async (id: string) => { if(supabase) await supabase.from('statuses').delete().eq('id', id); const db=getLocalDB(); db.statuses=db.statuses.filter((s:any)=>s.id!==id); setLocalDB(db); },
    deleteFormat: async (id: string) => { if(supabase) await supabase.from('formats').delete().eq('id', id); const db=getLocalDB(); db.formats=db.formats.filter((s:any)=>s.id!==id); setLocalDB(db); },
    deleteTeacherRole: async (id: string) => { if(supabase) await supabase.from('teacher_roles').delete().eq('id', id); const db=getLocalDB(); db.teacherRoles=db.teacherRoles.filter((s:any)=>s.id!==id); setLocalDB(db); },
    deleteProgram: async (id: string) => { if(supabase) await supabase.from('programs').delete().eq('id', id); const db=getLocalDB(); db.programs=db.programs.filter((s:any)=>s.id!==id); setLocalDB(db); },

    deleteStudent: async (id: string) => { if (supabase) { await supabase.from('users').delete().eq('student_id', id); await supabase.from('students').delete().eq('id', id); } const db=getLocalDB(); db.students=db.students.filter((s:any)=>s.id!==id); db.users=db.users.filter((u:any)=>u.studentId!==id); setLocalDB(db); },
    deleteTeacher: async (id: string) => { if (supabase) { await supabase.from('users').delete().eq('teacher_id', id); await supabase.from('teachers').delete().eq('id', id); } const db=getLocalDB(); db.teachers=db.teachers.filter((t:any)=>t.id!==id); db.users=db.users.filter((u:any)=>u.teacherId!==id); setLocalDB(db); },
    deleteUser: async (id: string) => { if (supabase) await supabase.from('users').delete().eq('id', id); const db=getLocalDB(); db.users=db.users.filter((u:any)=>u.id!==id); setLocalDB(db); },
    getStudentById: async (id: string) => { const sts = await db.getStudents(); return sts.find((s:any)=>s.id===id)||null; }
};

