// @ts-ignore - Importación directa desde CDN
import { createClient } from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';
import { Project, Student, Teacher, ProjectTeacher, Format, TeacherRole, Status, Program, User } from '../types';

const supabaseUrl = (import.meta as any).env?.VITE_SUPABASE_URL || '';
const supabaseAnonKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || '';

export const isSupabaseConfigured = !!(supabaseUrl && supabaseAnonKey && supabaseUrl.startsWith('http'));

// @ts-ignore
export const supabase = isSupabaseConfigured 
    ? createClient(supabaseUrl, supabaseAnonKey) 
    : null;

const generateId = (): string => Date.now().toString(36) + Math.random().toString(36).substring(2);

const LOCAL_STORAGE_KEY = 'uninunez_db_v4_final';

const initialDB = {
    users: [{ id: 'admin-id', username: 'admin', password: 'admin123', role: 'admin', teacherId: null, studentId: null }],
    projects: [],
    programs: [{ id: '1', name: 'Ingeniería de Sistemas' }, { id: '2', name: 'Derecho' }, { id: '3', name: 'Medicina' }],
    students: [],
    teachers: [],
    projectTeachers: [],
    formats: [{ id: '1', name: 'Anteproyecto' }, { id: '2', name: 'Proyecto Final' }],
    teacherRoles: [{ id: '1', name: 'Director' }, { id: '2', name: 'Co-Director' }, { id: '3', name: 'Evaluador 1' }, { id: '4', name: 'Evaluador 2' }],
    statuses: [{ id: '1', name: 'En Proceso' }, { id: '2', name: 'Aprobado' }, { id: '3', name: 'Sustentado' }, { id: '4', name: 'Rechazado' }]
};

const getLocalDB = (): any => {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (!data) return initialDB;
    try {
        const parsed = JSON.parse(data);
        return { ...initialDB, ...parsed };
    } catch {
        return initialDB;
    }
};

const setLocalDB = (db: any) => {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(db));
};

const mapProjectToDB = (p: Partial<Project>) => ({
    id: p.id,
    title: p.title,
    presentation_date: p.presentationDate || null,
    files_url: p.filesUrl || '',
    status_id: p.statusId || null,
    format_id: p.formatId || null,
    is_approved_by_director: !!p.isApprovedByDirector,
    written_grade_reviewer1: p.writtenGradeReviewer1,
    presentation_grade_reviewer1: p.presentationGradeReviewer1,
    written_grade_reviewer2: p.writtenGradeReviewer2,
    presentation_grade_reviewer2: p.presentationGradeReviewer2,
    final_grade: p.finalGrade
});

const mapProjectFromDB = (p: any): Project => ({
    id: p.id,
    title: p.title,
    presentationDate: p.presentation_date || p.presentationDate || '',
    filesUrl: p.files_url || p.filesUrl || '',
    statusId: p.status_id || p.statusId || '',
    formatId: p.format_id || p.formatId || '',
    isApprovedByDirector: p.is_approved_by_director ?? p.isApprovedByDirector ?? false,
    writtenGradeReviewer1: p.written_grade_reviewer1 ?? null,
    presentationGradeReviewer1: p.presentation_grade_reviewer1 ?? null,
    writtenGradeReviewer2: p.written_grade_reviewer2 ?? null,
    presentationGradeReviewer2: p.presentation_grade_reviewer2 ?? null,
    finalGrade: p.final_grade ?? null
});

export const db = {
    initializeDB: async () => {
        const current = localStorage.getItem(LOCAL_STORAGE_KEY);
        if (!current) setLocalDB(initialDB);

        // Sincronizar catálogos si Supabase está vacío
        if (supabase) {
            try {
                const db_l = getLocalDB();
                const checkTable = async (name: string, data: any[]) => {
                    const { count } = await supabase.from(name).select('*', { count: 'exact', head: true });
                    if (count === 0) await supabase.from(name).insert(data);
                };
                await checkTable('statuses', db_l.statuses);
                await checkTable('formats', db_l.formats);
                await checkTable('programs', db_l.programs);
                await checkTable('teacher_roles', db_l.teacherRoles);
            } catch (e) { console.error("Error en sync inicial:", e); }
        }
    },

    checkConnection: async () => {
        if (!supabase) return true;
        try {
            const { error } = await supabase.from('users').select('id').limit(1);
            return !error;
        } catch {
            return false;
        }
    },

    getProjects: async () => {
        const db_l = getLocalDB();
        const localProjects = db_l.projects || [];
        if (supabase) {
            try {
                const { data, error } = await supabase.from('projects').select('*').order('presentation_date', { ascending: false });
                if (!error && data) {
                    const cloudProjects = data.map(mapProjectFromDB);
                    // Mergear local y nube (Nube manda)
                    const merged = [...cloudProjects];
                    localProjects.forEach((lp: Project) => {
                        if (!merged.find(cp => cp.id === lp.id)) merged.push(lp);
                    });
                    db_l.projects = merged;
                    setLocalDB(db_l);
                    return merged;
                }
            } catch (e) { console.error("Error getProjects:", e); }
        }
        return localProjects;
    },

    getUsers: async () => {
        const db_l = getLocalDB();
        if (supabase) {
            try {
                const { data } = await supabase.from('users').select('*');
                if (data) {
                    const users = data.map((u: any) => ({ ...u, teacherId: u.teacher_id, studentId: u.student_id }));
                    db_l.users = users; setLocalDB(db_l);
                    return users;
                }
            } catch (e) {}
        }
        return db_l.users;
    },

    getUserByUsername: async (username: string) => {
        const users = await db.getUsers();
        return users.find((u: User) => u.username.toLowerCase() === username.toLowerCase().trim()) || null;
    },

    getStudents: async () => {
        const db_l = getLocalDB();
        const localStudents = db_l.students || [];
        if (supabase) {
            try {
                const { data, error } = await supabase.from('students').select('*');
                if (!error && data) {
                    const cloudStudents = data.map((s: any) => ({ 
                        id: s.id, 
                        name: s.name, 
                        email: s.email, 
                        cedula: s.cedula, 
                        projectId: s.project_id || null, 
                        programId: s.program_id || null 
                    }));
                    db_l.students = cloudStudents;
                    setLocalDB(db_l);
                    return cloudStudents;
                }
            } catch (e) { console.error("Error getStudents:", e); }
        }
        return localStudents;
    },

    getTeachers: async () => {
        const db_l = getLocalDB();
        if (supabase) {
            try {
                const { data } = await supabase.from('teachers').select('*');
                if (data) {
                    db_l.teachers = data; setLocalDB(db_l);
                    return data;
                }
            } catch (e) {}
        }
        return db_l.teachers;
    },

    getProjectTeachers: async () => {
        const db_l = getLocalDB();
        if (supabase) {
            try {
                const { data } = await supabase.from('project_teachers').select('*');
                if (data) {
                    const pts = data.map((pt: any) => ({ 
                        id: pt.id, 
                        projectId: pt.project_id, 
                        teacherId: pt.teacher_id, 
                        roleId: pt.role_id 
                    }));
                    db_l.projectTeachers = pts; setLocalDB(db_l);
                    return pts;
                }
            } catch (e) {}
        }
        return db_l.projectTeachers;
    },

    addProject: async (project: Omit<Project, 'id'>) => {
        const id = generateId();
        const newProject = { ...project, id } as Project;
        const db_l = getLocalDB();
        db_l.projects.unshift(newProject);
        setLocalDB(db_l);
        if (supabase) {
            const { error } = await supabase.from('projects').insert([mapProjectToDB(newProject)]);
            if (error) {
                console.error("ERROR SUPABASE INSERT PROJECT:", error.message, error.details);
                throw new Error("Supabase rechazó el proyecto: " + error.message);
            }
        }
        return newProject;
    },

    updateProject: async (project: Project) => {
        const db_l = getLocalDB();
        const idx = db_l.projects.findIndex((p: any) => p.id === project.id);
        if (idx !== -1) { db_l.projects[idx] = project; setLocalDB(db_l); }
        if (supabase) {
            const { error } = await supabase.from('projects').update(mapProjectToDB(project)).eq('id', project.id);
            if (error) {
                console.error("ERROR SUPABASE UPDATE PROJECT:", error.message);
                throw new Error("Supabase rechazó la actualización: " + error.message);
            }
        }
        return project;
    },

    deleteProject: async (id: string) => {
        if (supabase) await supabase.from('projects').delete().eq('id', id);
        const db_l = getLocalDB();
        db_l.projects = db_l.projects.filter((p: any) => p.id !== id);
        setLocalDB(db_l);
    },

    addStudent: async (student: Omit<Student, 'id'>) => {
        const id = generateId();
        const userId = generateId();
        if (supabase) {
            await supabase.from('students').insert([{ id, name: student.name, email: student.email, cedula: student.cedula, project_id: student.projectId, program_id: student.programId }]);
            await supabase.from('users').insert([{ id: userId, username: student.name, password: student.cedula, role: 'student', student_id: id }]);
        }
        const db_l = getLocalDB();
        db_l.students.push({ ...student, id });
        db_l.users.push({ id: userId, username: student.name, password: student.cedula, role: 'student', studentId: id, teacherId: null });
        setLocalDB(db_l);
        return { ...student, id } as Student;
    },

    updateStudent: async (student: Student) => {
        if (supabase) {
            const { error } = await supabase.from('students').update({ 
                name: student.name, 
                email: student.email, 
                cedula: student.cedula, 
                project_id: student.projectId, 
                program_id: student.programId 
            }).eq('id', student.id);
            if (error) console.error("Error sync student:", error.message);
        }
        const db_l = getLocalDB();
        const idx = db_l.students.findIndex((s: any) => s.id === student.id);
        if (idx !== -1) {
            db_l.students[idx] = student;
            const uIdx = db_l.users.findIndex((u: any) => u.studentId === student.id);
            if (uIdx !== -1) { db_l.users[uIdx].username = student.name; db_l.users[uIdx].password = student.cedula; }
            setLocalDB(db_l);
        }
        return student;
    },

    addTeacher: async (teacher: Omit<Teacher, 'id'>) => {
        const id = generateId();
        const userId = generateId();
        if (supabase) {
            await supabase.from('teachers').insert([{ id, ...teacher }]);
            await supabase.from('users').insert([{ id: userId, username: teacher.name, password: teacher.cedula, role: 'teacher', teacher_id: id }]);
        }
        const db_l = getLocalDB();
        db_l.teachers.push({ id, ...teacher });
        db_l.users.push({ id: userId, username: teacher.name, password: teacher.cedula, role: 'teacher', teacherId: id, studentId: null });
        setLocalDB(db_l);
        return { id, ...teacher };
    },

    updateTeacher: async (teacher: Teacher) => {
        if (supabase) {
            await supabase.from('teachers').update(teacher).eq('id', teacher.id);
            await supabase.from('users').update({ username: teacher.name, password: teacher.cedula }).eq('teacher_id', teacher.id);
        }
        const db_l = getLocalDB();
        const idx = db_l.teachers.findIndex((t: any) => t.id === teacher.id);
        if (idx !== -1) {
            db_l.teachers[idx] = teacher;
            const uIdx = db_l.users.findIndex((u: any) => u.teacherId === teacher.id);
            if (uIdx !== -1) { db_l.users[uIdx].username = teacher.name; db_l.users[uIdx].password = teacher.cedula; }
            setLocalDB(db_l);
        }
        return teacher;
    },

    getStatuses: async () => getLocalDB().statuses,
    getFormats: async () => getLocalDB().formats,
    getTeacherRoles: async () => getLocalDB().teacherRoles,
    getPrograms: async () => getLocalDB().programs,

    addStatus: async (p: Omit<Status, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('statuses').insert([{id, ...p}]); const db=getLocalDB(); db.statuses.push({id, ...p}); setLocalDB(db); return {id, ...p}; },
    addFormat: async (p: Omit<Format, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('formats').insert([{id, ...p}]); const db=getLocalDB(); db.formats.push({id, ...p}); setLocalDB(db); return {id, ...p}; },
    addProgram: async (p: Omit<Program, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('programs').insert([{id, ...p}]); const db=getLocalDB(); db.programs.push({id, ...p}); setLocalDB(db); return {id, ...p}; },
    addTeacherRole: async (p: Omit<TeacherRole, 'id'>) => { const id=generateId(); if(supabase) await supabase.from('teacher_roles').insert([{id, ...p}]); const db=getLocalDB(); db.teacherRoles.push({id, ...p}); setLocalDB(db); return {id, ...p}; },

    updateStatus: async (p: Status) => { if(supabase) await supabase.from('statuses').update({name: p.name}).eq('id', p.id); const db=getLocalDB(); const idx=db.statuses.findIndex((s:any)=>s.id===p.id); if(idx!==-1) db.statuses[idx]=p; setLocalDB(db); return p; },
    updateFormat: async (p: Format) => { if(supabase) await supabase.from('formats').update({name: p.name}).eq('id', p.id); const db=getLocalDB(); const idx=db.formats.findIndex((s:any)=>s.id===p.id); if(idx!==-1) db.formats[idx]=p; setLocalDB(db); return p; },
    updateTeacherRole: async (p: TeacherRole) => { if(supabase) await supabase.from('teacher_roles').update({name: p.name}).eq('id', p.id); const db=getLocalDB(); const idx=db.teacherRoles.findIndex((s:any)=>s.id===p.id); if(idx!==-1) db.teacherRoles[idx]=p; setLocalDB(db); return p; },
    updateProgram: async (p: Program) => { if(supabase) await supabase.from('programs').update({name: p.name}).eq('id', p.id); const db=getLocalDB(); const idx=db.programs.findIndex((s:any)=>s.id===p.id); if(idx!==-1) db.programs[idx]=p; setLocalDB(db); return p; },

    deleteStatus: async (id: string) => { if(supabase) await supabase.from('statuses').delete().eq('id', id); const db=getLocalDB(); db.statuses=db.statuses.filter((s:any)=>s.id!==id); setLocalDB(db); },
    deleteFormat: async (id: string) => { if(supabase) await supabase.from('formats').delete().eq('id', id); const db=getLocalDB(); db.formats=db.formats.filter((s:any)=>s.id!==id); setLocalDB(db); },
    deleteTeacherRole: async (id: string) => { if(supabase) await supabase.from('teacher_roles').delete().eq('id', id); const db=getLocalDB(); db.teacherRoles=db.teacherRoles.filter((s:any)=>s.id!==id); setLocalDB(db); },
    deleteProgram: async (id: string) => { if(supabase) await supabase.from('programs').delete().eq('id', id); const db=getLocalDB(); db.programs=db.programs.filter((s:any)=>s.id!==id); setLocalDB(db); },

    addProjectTeacher: async (pt: Omit<ProjectTeacher, 'id'>) => {
        const id = generateId();
        if (supabase) await supabase.from('project_teachers').insert([{ id, project_id: pt.projectId, teacher_id: pt.teacherId, role_id: pt.roleId }]);
        const db_l = getLocalDB();
        db_l.projectTeachers.push({ ...pt, id });
        setLocalDB(db_l);
        return { ...pt, id };
    },
    deleteProjectTeachersByProject: async (projectId: string) => {
        if (supabase) await supabase.from('project_teachers').delete().eq('project_id', projectId);
        const db_l = getLocalDB();
        db_l.projectTeachers = db_l.projectTeachers.filter((pt: any) => pt.projectId !== projectId);
        setLocalDB(db_l);
    },
    deleteStudent: async (id: string) => { if (supabase) { await supabase.from('users').delete().eq('student_id', id); await supabase.from('students').delete().eq('id', id); } const db=getLocalDB(); db.students=db.students.filter((s:any)=>s.id!==id); db.users=db.users.filter((u:any)=>u.studentId!==id); setLocalDB(db); },
    deleteTeacher: async (id: string) => { if (supabase) { await supabase.from('users').delete().eq('teacher_id', id); await supabase.from('teachers').delete().eq('id', id); } const db=getLocalDB(); db.teachers=db.teachers.filter((t:any)=>t.id!==id); db.users=db.users.filter((u:any)=>u.teacherId!==id); setLocalDB(db); },
    deleteUser: async (id: string) => { if (supabase) await supabase.from('users').delete().eq('id', id); const db=getLocalDB(); db.users=db.users.filter((u:any)=>u.id!==id); setLocalDB(db); },
    getProjectById: async (id: string) => (await db.getProjects()).find(p => p.id === id) || null,
    getStudentById: async (id: string) => (await db.getStudents()).find(s => s.id === id) || null,
};

import React, { useState, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { Project, Student, Teacher, TeacherRole, Status, Format, ProjectTeacher } from '../types';
import { Modal } from '../components/Modal';
import { ConfirmationDialog } from '../components/ConfirmationDialog';
import { PlusIcon, EditIcon, TrashIcon } from '../components/Icons';
import { useAuth } from '../contexts/AuthContext';

const ProjectForm: React.FC<{
    project: Partial<Project> | null;
    onSave: (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => Promise<void>;
    onClose: () => void;
    statuses: Status[];
    formats: Format[];
    teachers: Teacher[];
    allStudents: Student[];
    roles: TeacherRole[];
    initialAssignments: ProjectTeacher[];
    initialStudentIds: string[];
    canEditDetails: boolean;
    gradeInfo: { canGrade: boolean, reviewerRole: string | null };
}> = ({ project, onSave, onClose, statuses, formats, teachers, allStudents, roles, initialAssignments, initialStudentIds, canEditDetails, gradeInfo }) => {
    const { isAdmin } = useAuth();
    const [formData, setFormData] = useState<Partial<Project>>({});
    const [assignments, setAssignments] = useState<Array<{teacherId: string, roleId: string, tempId: number}>>([]);
    const [assignedStudentIds, setAssignedStudentIds] = useState<string[]>([]);
    const [newAssignment, setNewAssignment] = useState({ teacherId: '', roleId: '' });
    const [selectedStudentId, setSelectedStudentId] = useState('');
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        const initialData: Partial<Project> = {
            title: '', presentationDate: '', filesUrl: '',
            statusId: statuses[0]?.id || '', formatId: formats[0]?.id || '',
            isApprovedByDirector: false, writtenGradeReviewer1: null,
            presentationGradeReviewer1: null, writtenGradeReviewer2: null,
            presentationGradeReviewer2: null, finalGrade: null, ...project
        };
        setFormData(initialData);
        setAssignments(initialAssignments.map(a => ({ teacherId: a.teacherId, roleId: a.roleId, tempId: Math.random() })));
        setAssignedStudentIds(initialStudentIds);
        setNewAssignment({ teacherId: '', roleId: '' });
        setSelectedStudentId('');
    }, [project, initialAssignments, initialStudentIds, statuses]);

    const calculateFinalAverage = (data: Partial<Project>) => {
        const g1w = data.writtenGradeReviewer1;
        const g1p = data.presentationGradeReviewer1;
        const g2w = data.writtenGradeReviewer2;
        const g2p = data.presentationGradeReviewer2;

        let avg1 = 0; let count1 = 0;
        if (g1w !== null) { avg1 += g1w; count1++; }
        if (g1p !== null) { avg1 += g1p; count1++; }
        const finalAvg1 = count1 > 0 ? avg1 / count1 : null;

        let avg2 = 0; let count2 = 0;
        if (g2w !== null) { avg2 += g2w; count2++; }
        if (g2p !== null) { avg2 += g2p; count2++; }
        const finalAvg2 = count2 > 0 ? avg2 / count2 : null;

        if (finalAvg1 !== null && finalAvg2 !== null) {
            return Number(((finalAvg1 + finalAvg2) / 2).toFixed(2));
        } else if (finalAvg1 !== null) {
            return Number(finalAvg1.toFixed(2));
        } else if (finalAvg2 !== null) {
            return Number(finalAvg2.toFixed(2));
        }
        return null;
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        let finalValue: any = value;
        if (type === 'number') {
            if (value === '') finalValue = null;
            else {
                const num = parseFloat(value);
                if (num < 1.0 || num > 5.0) return;
                finalValue = num;
            }
        }
        setFormData(prev => {
            const nextData = { ...prev, [name]: finalValue };
            if (name.includes('Grade')) nextData.finalGrade = calculateFinalAverage(nextData);
            return nextData;
        });
    };

    const handleAddAssignment = () => {
        if (newAssignment.teacherId && newAssignment.roleId) {
            if (assignments.some(a => a.teacherId === newAssignment.teacherId)) { alert('Docente ya asignado.'); return; }
            setAssignments(prev => [...prev, {...newAssignment, tempId: Math.random()}]);
            setNewAssignment({ teacherId: '', roleId: '' });
        }
    };

    const handleAddStudent = () => {
        if (selectedStudentId && !assignedStudentIds.includes(selectedStudentId)) {
            setAssignedStudentIds(prev => [...prev, selectedStudentId]);
            setSelectedStudentId('');
        }
    };

    const removeStudent = (id: string) => setAssignedStudentIds(prev => prev.filter(sid => sid !== id));

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (isSaving) return;
        if (!formData.title?.trim() || !formData.presentationDate) { alert("Título y Fecha obligatorios."); return; }
        setIsSaving(true);
        try { 
            await onSave(formData, assignments, assignedStudentIds); 
            onClose(); 
        }
        catch (error: any) { console.error(error); alert("Error crítico al guardar: " + error.message); }
        finally { setIsSaving(false); }
    };

    const getTeacherName = (id: string) => teachers.find(t => t.id === id)?.name || 'Desconocido';
    const getRoleName = (id: string) => roles.find(r => r.id === id)?.name || 'Desconocido';
    const getStudentName = (id: string) => {
        const found = allStudents.find(s => s.id === id);
        return found ? found.name : 'Estudiante no encontrado';
    };

    const canGradeReviewer1 = isAdmin || (gradeInfo.canGrade && gradeInfo.reviewerRole?.toLowerCase().includes('1'));
    const canGradeReviewer2 = isAdmin || (gradeInfo.canGrade && gradeInfo.reviewerRole?.toLowerCase().includes('2'));

    return (
        <form onSubmit={handleSubmit} className="space-y-6 max-h-[75vh] overflow-y-auto pr-2 scrollbar-thin">
            <div className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-1 ml-1">Título Institucional</label>
                    <input type="text" name="title" value={formData.title || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50 font-bold" disabled={!canEditDetails} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-1 ml-1">Fecha de Radicación</label>
                        <input type="date" name="presentationDate" value={formData.presentationDate || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails}/>
                    </div>
                    <div>
                        <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-1 ml-1">Estado del Proyecto</label>
                        <select name="statusId" value={formData.statusId || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails && !gradeInfo.canGrade}>
                            {statuses.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            <div className="bg-uninunez-onix/5 p-5 rounded-2xl border border-uninunez-onix/10 space-y-4">
                <div className="flex justify-between items-center border-b border-uninunez-onix/10 pb-3">
                    <h4 className="text-[10px] font-black text-uninunez-onix uppercase tracking-widest">Calificaciones Académicas</h4>
                    <div className="flex items-center gap-2">
                        <span className="text-[9px] font-bold text-uninunez-ash uppercase">Promedio:</span>
                        <div className="bg-uninunez-orange text-white px-3 py-1 rounded-lg text-xs font-black shadow-md min-w-[50px] text-center">{formData.finalGrade?.toFixed(2) || '0.00'}</div>
                    </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className={`p-4 rounded-xl border-2 transition-all ${canGradeReviewer1 ? 'bg-white border-uninunez-teal/30 shadow-sm' : 'bg-gray-100 border-transparent opacity-60'}`}>
                        <p className="text-[10px] font-black text-uninunez-teal uppercase mb-3 flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-uninunez-teal"></span> Evaluador 1</p>
                        <div className="grid grid-cols-2 gap-3">
                            <input type="number" step="0.1" name="writtenGradeReviewer1" placeholder="Escrito" value={formData.writtenGradeReviewer1 ?? ''} onChange={handleChange} disabled={!canGradeReviewer1} className="w-full text-xs border rounded-lg p-2 font-bold" />
                            <input type="number" step="0.1" name="presentationGradeReviewer1" placeholder="Sust." value={formData.presentationGradeReviewer1 ?? ''} onChange={handleChange} disabled={!canGradeReviewer1} className="w-full text-xs border rounded-lg p-2 font-bold" />
                        </div>
                    </div>
                    <div className={`p-4 rounded-xl border-2 transition-all ${canGradeReviewer2 ? 'bg-white border-uninunez-teal/30 shadow-sm' : 'bg-gray-100 border-transparent opacity-60'}`}>
                        <p className="text-[10px] font-black text-uninunez-teal uppercase mb-3 flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-uninunez-teal"></span> Evaluador 2</p>
                        <div className="grid grid-cols-2 gap-3">
                            <input type="number" step="0.1" name="writtenGradeReviewer2" placeholder="Escrito" value={formData.writtenGradeReviewer2 ?? ''} onChange={handleChange} disabled={!canGradeReviewer2} className="w-full text-xs border rounded-lg p-2 font-bold" />
                            <input type="number" step="0.1" name="presentationGradeReviewer2" placeholder="Sust." value={formData.presentationGradeReviewer2 ?? ''} onChange={handleChange} disabled={!canGradeReviewer2} className="w-full text-xs border rounded-lg p-2 font-bold" />
                        </div>
                    </div>
                </div>
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-4 ml-1">Integrantes (Estudiantes)</h4>
                <div className="flex flex-wrap gap-2 mb-3">
                    {assignedStudentIds.length > 0 ? assignedStudentIds.map(sid => (
                        <div key={sid} className="flex items-center bg-white px-3 py-2 rounded-xl border border-gray-200 shadow-sm">
                            <span className="text-[10px] font-bold text-gray-700 mr-2">{getStudentName(sid)}</span>
                            {canEditDetails && <button type="button" onClick={() => removeStudent(sid)} className="text-red-400 hover:text-red-600"><TrashIcon className="h-3.5 w-3.5"/></button>}
                        </div>
                    )) : <p className="text-[10px] text-gray-400 italic py-2">No hay estudiantes vinculados todavía.</p>}
                </div>
                {canEditDetails && (
                    <div className="flex gap-2">
                        <select value={selectedStudentId} onChange={(e) => setSelectedStudentId(e.target.value)} className="flex-grow border border-gray-200 rounded-xl px-3 py-2 text-sm bg-gray-50">
                            <option value="">Vincular estudiante...</option>
                            {allStudents.filter(s => (!s.projectId || assignedStudentIds.includes(s.id)) && !assignedStudentIds.includes(s.id)).map(s => (
                                <option key={s.id} value={s.id}>{s.name} ({s.cedula})</option>
                            ))}
                        </select>
                        <button type="button" onClick={handleAddStudent} className="bg-uninunez-orange text-white px-5 rounded-xl text-[10px] font-black uppercase hover:bg-uninunez-orangeLight">Añadir</button>
                    </div>
                )}
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-4 ml-1">Asignaciones (Docentes)</h4>
                <div className="space-y-2 mb-4">
                    {assignments.map(a => (
                        <div key={a.tempId} className="flex justify-between items-center bg-white px-4 py-2.5 rounded-xl border border-gray-100 shadow-sm">
                            <span className="text-[11px] font-bold text-gray-700">{getTeacherName(a.teacherId)} — <span className="text-uninunez-teal uppercase font-black tracking-widest">{getRoleName(a.roleId)}</span></span>
                            {canEditDetails && <button type="button" onClick={() => setAssignments(prev => prev.filter(x => x.tempId !== a.tempId))} className="text-red-400 p-1"><TrashIcon className="h-4 w-4"/></button>}
                        </div>
                    ))}
                </div>
                {canEditDetails && (
                    <div className="grid grid-cols-1 sm:grid-cols-7 gap-2">
                        <select value={newAssignment.teacherId} onChange={(e) => setNewAssignment(p => ({...p, teacherId: e.target.value}))} className="sm:col-span-3 border border-gray-200 rounded-xl px-3 py-2 text-sm bg-gray-50">
                            <option value="">Seleccionar Docente...</option>
                            {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                        </select>
                        <select value={newAssignment.roleId} onChange={(e) => setNewAssignment(p => ({...p, roleId: e.target.value}))} className="sm:col-span-3 border border-gray-200 rounded-xl px-3 py-2 text-sm bg-gray-50">
                            <option value="">Rol...</option>
                            {roles.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                        </select>
                        <button type="button" onClick={handleAddAssignment} className="sm:col-span-1 bg-uninunez-orange text-white rounded-xl text-[10px] font-black uppercase">OK</button>
                    </div>
                )}
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t sticky bottom-0 bg-white/95 pb-2">
                <button type="button" onClick={onClose} disabled={isSaving} className="px-6 py-3 border-2 border-gray-100 rounded-xl text-[10px] font-black uppercase text-gray-400">Cancelar</button>
                <button type="submit" disabled={isSaving} className={`px-10 py-3 rounded-xl text-[10px] font-black uppercase shadow-xl transition-all ${isSaving ? 'bg-gray-400' : 'bg-uninunez-orange hover:bg-uninunez-orangeLight text-white'}`}>
                    {isSaving ? 'Guardando...' : project ? 'Actualizar Proyecto' : 'Guardar Proyecto'}
                </button>
            </div>
        </form>
    );
};

export const ProjectsPage: React.FC = () => {
    const { isAdmin, canEditProject, canGradeProject } = useAuth();
    const [projects, setProjects] = useState<Project[]>([]);
    const [students, setStudents] = useState<Student[]>([]);
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [roles, setRoles] = useState<TeacherRole[]>([]);
    const [statuses, setStatuses] = useState<Status[]>([]);
    const [formats, setFormats] = useState<Format[]>([]);
    const [projectTeachers, setProjectTeachers] = useState<ProjectTeacher[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);
    const [userPerms, setUserPerms] = useState<Record<string, any>>({});

    const loadData = useCallback(async () => {
        setIsLoading(true);
        try {
            const [p, s, t, r, st, f, pt] = await Promise.all([
                db.getProjects(), 
                db.getStudents(), 
                db.getTeachers(),
                db.getTeacherRoles(), 
                db.getStatuses(), 
                db.getFormats(),
                db.getProjectTeachers()
            ]);

            const perms: any = {};
            for(const project of p) {
                perms[project.id] = { 
                    canEdit: await canEditProject(project.id), 
                    grade: await canGradeProject(project.id) 
                };
            }

            setProjects([...p]); 
            setStudents([...s]); 
            setTeachers([...t]); 
            setRoles([...r]); 
            setStatuses([...st]); 
            setFormats([...f]); 
            setProjectTeachers([...pt]); 
            setUserPerms(perms);
        } catch (error) { 
            console.error("Error al cargar datos:", error); 
        } finally { 
            setIsLoading(false); 
        }
    }, [canEditProject, canGradeProject]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => {
        try {
            let savedProject: Project;

            // 1. Guardar/Actualizar Proyecto principal primero
            if (editingProject) {
                savedProject = await db.updateProject({ ...editingProject, ...projectData } as Project);
            } else {
                savedProject = await db.addProject(projectData as Omit<Project, 'id'>);
            }

            // Si el proyecto se guardó con éxito (en local o nube), actualizamos relaciones
            if (!editingProject || isAdmin || userPerms[savedProject.id]?.canEdit) {
                // 2. Docentes - Eliminar antiguos y re-añadir
                await db.deleteProjectTeachersByProject(savedProject.id);
                for (const a of assignments) {
                    await db.addProjectTeacher({ projectId: savedProject.id, teacherId: a.teacherId, roleId: a.roleId });
                }

                // 3. Estudiantes - Sincronización robusta
                const sts = await db.getStudents();

                // Desvincular todos los estudiantes que estaban en este proyecto pero ya no están en studentIds
                const currentLinked = sts.filter(s => s.projectId === savedProject.id);
                for (const s of currentLinked) {
                    if (!studentIds.includes(s.id)) {
                        await db.updateStudent({ ...s, projectId: null });
                    }
                }

                // Vincular los nuevos integrantes
                for (const sid of studentIds) {
                    const s = sts.find(st => st.id === sid);
                    if (s) {
                        await db.updateStudent({ ...s, projectId: savedProject.id });
                    }
                }
            }

            // Recarga completa para asegurar visibilidad
            await loadData(); 
            setIsModalOpen(false);
            setEditingProject(null);
        } catch (err: any) { 
            console.error("Fallo crítico en handleSave:", err); 
            alert("No se pudo completar el guardado en Supabase: " + err.message + ". Asegúrate de que las tablas de catálogos no estén vacías.");
        }
    };

    const handleDelete = async () => { 
        if (deletingProject) { 
            await db.deleteProject(deletingProject.id); 
            await loadData(); 
            setDeletingProject(null); 
        } 
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-black text-uninunez-onix font-display uppercase tracking-tight">Banco de Proyectos</h1>
                    <p className="text-uninunez-ash text-sm font-medium">Gestión integral de expedientes académicos.</p>
                </div>
                {isAdmin && (
                    <button 
                        onClick={() => { setEditingProject(null); setIsModalOpen(true); }} 
                        className="bg-uninunez-orange text-white px-6 py-3 rounded-xl flex items-center text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-uninunez-orangeLight transition-all active:scale-95"
                    >
                        <PlusIcon className="h-5 w-5 mr-2"/> Nuevo Proyecto
                    </button>
                )}
            </div>

            <div className="bg-white shadow-sm border border-gray-100 rounded-3xl overflow-hidden min-h-[400px]">
                {isLoading ? (
                    <div className="flex flex-col items-center justify-center py-20 space-y-4">
                        <div className="w-12 h-12 border-4 border-uninunez-orange border-t-transparent rounded-full animate-spin"></div>
                        <p className="text-xs font-black text-uninunez-ash uppercase tracking-widest">Sincronizando expedientes...</p>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-gray-50/50 border-b border-gray-100">
                                <tr>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Proyecto</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Autores (Estudiantes)</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Estado</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">Nota Final</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-right">Acciones</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-50">
                                {projects.map(p => {
                                    const linkedStudents = students.filter(s => s.projectId === p.id);
                                    return (
                                        <tr key={p.id} className="hover:bg-gray-50/50 transition-colors group">
                                            <td className="px-8 py-6">
                                                <div className="text-sm font-bold text-uninunez-onix group-hover:text-uninunez-orange transition-colors">{p.title}</div>
                                                <div className="text-[10px] text-gray-400 mt-1 uppercase font-bold tracking-tight">Radicación: {p.presentationDate}</div>
                                            </td>
                                            <td className="px-8 py-6">
                                                <div className="flex flex-wrap gap-1">
                                                    {linkedStudents.length > 0 ? linkedStudents.map(s => (
                                                        <span key={s.id} className="inline-block px-2 py-0.5 bg-jade-50 text-[10px] font-bold text-jade-700 rounded uppercase border border-jade-100 shadow-sm">{s.name}</span>
                                                    )) : <span className="text-[10px] text-gray-300 italic">Sin estudiantes vinculados</span>}
                                                </div>
                                            </td>
                                            <td className="px-8 py-6">
                                                <span className="px-3 py-1.5 text-[10px] font-black uppercase tracking-wider rounded-lg bg-uninunez-teal/10 text-uninunez-teal">{statuses.find(s => s.id === p.statusId)?.name || 'PENDIENTE'}</span>
                                            </td>
                                            <td className="px-8 py-6 text-center">
                                                <span className={`px-3 py-1 text-sm font-black rounded-lg ${p.finalGrade ? (p.finalGrade >= 3.0 ? 'bg-jade-100 text-jade-700' : 'bg-red-100 text-red-600') : 'bg-gray-100 text-gray-400'}`}>{p.finalGrade?.toFixed(2) || '---'}</span>
                                            </td>
                                            <td className="px-8 py-6 text-right">
                                                <div className="flex justify-end gap-2">
                                                    {(isAdmin || userPerms[p.id]?.canEdit || userPerms[p.id]?.grade?.canGrade) && (
                                                        <button onClick={() => { setEditingProject(p); setIsModalOpen(true); }} className="p-2.5 bg-uninunez-teal/5 text-uninunez-teal hover:bg-uninunez-teal hover:text-white rounded-xl shadow-sm transition-all"><EditIcon className="h-5 w-5"/></button>
                                                    )}
                                                    {(isAdmin || userPerms[p.id]?.canEdit) && <button onClick={() => setDeletingProject(p)} className="p-2.5 bg-red-50 text-red-500 hover:bg-red-500 hover:text-white rounded-xl shadow-sm transition-all"><TrashIcon className="h-5 w-5"/></button>}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                                {!isLoading && projects.length === 0 && (
                                    <tr>
                                        <td colSpan={5} className="text-center py-20">
                                            <p className="text-uninunez-ash italic text-sm">No se han encontrado proyectos registrados.</p>
                                            {isAdmin && <p className="text-xs text-gray-400 mt-2">Haz clic en "Nuevo Proyecto" para comenzar.</p>}
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingProject ? 'Expediente de Proyecto' : 'Nuevo Registro Académico'}>
                {isModalOpen && (
                    <ProjectForm 
                        project={editingProject} 
                        onSave={handleSave} 
                        onClose={() => setIsModalOpen(false)} 
                        statuses={statuses} 
                        formats={formats} 
                        teachers={teachers} 
                        allStudents={students} 
                        roles={roles} 
                        initialAssignments={editingProject ? projectTeachers.filter(pt => pt.projectId === editingProject.id) : []} 
                        initialStudentIds={editingProject ? students.filter(s => s.projectId === editingProject.id).map(s => s.id) : []}
                        canEditDetails={editingProject ? (isAdmin || userPerms[editingProject.id]?.canEdit) : true} 
                        gradeInfo={editingProject ? userPerms[editingProject.id]?.grade : {canGrade: false, reviewerRole: null}} 
                    />
                )}
            </Modal>
            <ConfirmationDialog isOpen={!!deletingProject} onClose={() => setDeletingProject(null)} onConfirm={handleDelete} title="Confirmar Eliminación" message="¿Desea eliminar permanentemente este expediente del banco institucional? Esta acción borrará todas las notas asociadas." />
        </div>
    );
};

// @ts-ignore - Importación directa desde CDN
import { createClient } from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';
import { Project, Student, Teacher, ProjectTeacher, Format, TeacherRole, Status, Program, User } from '../types';

const supabaseUrl = (import.meta as any).env?.VITE_SUPABASE_URL || '';
const supabaseAnonKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || '';

export const isSupabaseConfigured = !!(supabaseUrl && supabaseAnonKey && supabaseUrl.startsWith('http'));

// @ts-ignore
export const supabase = isSupabaseConfigured 
    ? createClient(supabaseUrl, supabaseAnonKey) 
    : null;

const generateId = (): string => Date.now().toString(36) + Math.random().toString(36).substring(2);

// Datos iniciales para siembra (solo se usan si Supabase está vacío)
const initialSeeds = {
    programs: [{ id: '1', name: 'Ingeniería de Sistemas' }, { id: '2', name: 'Derecho' }, { id: '3', name: 'Medicina' }],
    formats: [{ id: '1', name: 'Anteproyecto' }, { id: '2', name: 'Proyecto Final' }],
    teacherRoles: [{ id: '1', name: 'Director' }, { id: '2', name: 'Co-Director' }, { id: '3', name: 'Evaluador 1' }, { id: '4', name: 'Evaluador 2' }],
    statuses: [{ id: '1', name: 'En Proceso' }, { id: '2', name: 'Aprobado' }, { id: '3', name: 'Sustentado' }, { id: '4', name: 'Rechazado' }]
};

const mapProjectToDB = (p: Partial<Project>) => ({
    id: p.id,
    title: p.title,
    presentation_date: p.presentationDate || null,
    files_url: p.filesUrl || '',
    status_id: p.statusId || null,
    format_id: p.formatId || null,
    is_approved_by_director: !!p.isApprovedByDirector,
    written_grade_reviewer1: p.writtenGradeReviewer1,
    presentation_grade_reviewer1: p.presentationGradeReviewer1,
    written_grade_reviewer2: p.writtenGradeReviewer2,
    presentation_grade_reviewer2: p.presentationGradeReviewer2,
    final_grade: p.finalGrade
});

const mapProjectFromDB = (p: any): Project => ({
    id: p.id,
    title: p.title,
    presentationDate: p.presentation_date || '',
    filesUrl: p.files_url || '',
    statusId: p.status_id || '',
    formatId: p.format_id || '',
    isApprovedByDirector: !!p.is_approved_by_director,
    writtenGradeReviewer1: p.written_grade_reviewer1 ?? null,
    presentationGradeReviewer1: p.presentation_grade_reviewer1 ?? null,
    writtenGradeReviewer2: p.written_grade_reviewer2 ?? null,
    presentationGradeReviewer2: p.presentation_grade_reviewer2 ?? null,
    finalGrade: p.final_grade ?? null
});

export const db = {
    initializeDB: async () => {
        if (!supabase) return;
        try {
            const checkAndSeed = async (table: string, data: any[]) => {
                const { count } = await supabase.from(table).select('*', { count: 'exact', head: true });
                if (count === 0) await supabase.from(table).insert(data);
            };
            await checkAndSeed('statuses', initialSeeds.statuses);
            await checkAndSeed('formats', initialSeeds.formats);
            await checkAndSeed('programs', initialSeeds.programs);
            await checkAndSeed('teacher_roles', initialSeeds.teacherRoles);
        } catch (e) {
            console.error("Error en inicialización de Supabase:", e);
        }
    },

    checkConnection: async () => {
        if (!supabase) return false;
        try {
            const { error } = await supabase.from('statuses').select('id').limit(1);
            return !error;
        } catch {
            return false;
        }
    },

    getProjects: async (): Promise<Project[]> => {
        if (!supabase) return [];
        const { data, error } = await supabase.from('projects').select('*').order('presentation_date', { ascending: false });
        if (error) { console.error("Error getProjects:", error); return []; }
        return (data || []).map(mapProjectFromDB);
    },

    getUsers: async (): Promise<User[]> => {
        if (!supabase) return [];
        const { data, error } = await supabase.from('users').select('*');
        if (error) return [];
        return (data || []).map((u: any) => ({
            ...u,
            teacherId: u.teacher_id,
            studentId: u.student_id
        }));
    },

    getUserByUsername: async (username: string) => {
        if (!supabase) return null;
        const { data, error } = await supabase.from('users').select('*').eq('username', username).single();
        if (error || !data) return null;
        return {
            ...data,
            teacherId: data.teacher_id,
            studentId: data.student_id
        } as User;
    },

    getStudents: async (): Promise<Student[]> => {
        if (!supabase) return [];
        const { data, error } = await supabase.from('students').select('*');
        if (error) return [];
        return (data || []).map((s: any) => ({
            id: s.id,
            name: s.name,
            email: s.email,
            cedula: s.cedula,
            projectId: s.project_id,
            programId: s.program_id
        }));
    },

    getTeachers: async (): Promise<Teacher[]> => {
        if (!supabase) return [];
        const { data, error } = await supabase.from('teachers').select('*');
        if (error) return [];
        return data || [];
    },

    getProjectTeachers: async (): Promise<ProjectTeacher[]> => {
        if (!supabase) return [];
        const { data, error } = await supabase.from('project_teachers').select('*');
        if (error) return [];
        return (data || []).map((pt: any) => ({
            id: pt.id,
            projectId: pt.project_id,
            teacherId: pt.teacher_id,
            roleId: pt.role_id
        }));
    },

    addProject: async (project: Omit<Project, 'id'>) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const id = generateId();
        const { error } = await supabase.from('projects').insert([mapProjectToDB({ ...project, id })]);
        if (error) throw error;
        return { ...project, id } as Project;
    },

    updateProject: async (project: Project) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const { error } = await supabase.from('projects').update(mapProjectToDB(project)).eq('id', project.id);
        if (error) throw error;
        return project;
    },

    deleteProject: async (id: string) => {
        if (!supabase) return;
        await supabase.from('project_teachers').delete().eq('project_id', id);
        await supabase.from('students').update({ project_id: null }).eq('project_id', id);
        await supabase.from('projects').delete().eq('id', id);
    },

    addStudent: async (student: Omit<Student, 'id'>) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const id = generateId();
        const userId = generateId();
        await supabase.from('students').insert([{ 
            id, name: student.name, email: student.email, cedula: student.cedula, 
            project_id: student.projectId, program_id: student.programId 
        }]);
        await supabase.from('users').insert([{ 
            id: userId, username: student.name, password: student.cedula, role: 'student', student_id: id 
        }]);
        return { ...student, id } as Student;
    },

    updateStudent: async (student: Student) => {
        if (!supabase) return student;
        const { error } = await supabase.from('students').update({ 
            name: student.name, email: student.email, cedula: student.cedula, 
            project_id: student.projectId, program_id: student.programId 
        }).eq('id', student.id);
        if (error) console.error("Error updateStudent:", error);
        return student;
    },

    addTeacher: async (teacher: Omit<Teacher, 'id'>) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const id = generateId();
        const userId = generateId();
        await supabase.from('teachers').insert([{ id, ...teacher }]);
        await supabase.from('users').insert([{ 
            id: userId, username: teacher.name, password: teacher.cedula, role: 'teacher', teacher_id: id 
        }]);
        return { id, ...teacher } as Teacher;
    },

    updateTeacher: async (teacher: Teacher) => {
        if (!supabase) return teacher;
        await supabase.from('teachers').update(teacher).eq('id', teacher.id);
        await supabase.from('users').update({ username: teacher.name, password: teacher.cedula }).eq('teacher_id', teacher.id);
        return teacher;
    },

    getStatuses: async () => {
        if (!supabase) return initialSeeds.statuses;
        const { data } = await supabase.from('statuses').select('*');
        return data || [];
    },

    getFormats: async () => {
        if (!supabase) return initialSeeds.formats;
        const { data } = await supabase.from('formats').select('*');
        return data || [];
    },

    getTeacherRoles: async () => {
        if (!supabase) return initialSeeds.teacherRoles;
        const { data } = await supabase.from('teacher_roles').select('*');
        return data || [];
    },

    getPrograms: async () => {
        if (!supabase) return initialSeeds.programs;
        const { data } = await supabase.from('programs').select('*');
        return data || [];
    },

    addProjectTeacher: async (pt: Omit<ProjectTeacher, 'id'>) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const id = generateId();
        await supabase.from('project_teachers').insert([{ 
            id, project_id: pt.projectId, teacher_id: pt.teacherId, role_id: pt.roleId 
        }]);
        return { ...pt, id };
    },

    deleteProjectTeachersByProject: async (projectId: string) => {
        if (!supabase) return;
        await supabase.from('project_teachers').delete().eq('project_id', projectId);
    },

    deleteStudent: async (id: string) => {
        if (!supabase) return;
        await supabase.from('users').delete().eq('student_id', id);
        await supabase.from('students').delete().eq('id', id);
    },

    deleteTeacher: async (id: string) => {
        if (!supabase) return;
        await supabase.from('users').delete().eq('teacher_id', id);
        await supabase.from('teachers').delete().eq('id', id);
    },

    deleteUser: async (id: string) => {
        if (!supabase) return;
        await supabase.from('users').delete().eq('id', id);
    },

    getProjectById: async (id: string) => {
        if (!supabase) return null;
        const { data } = await supabase.from('projects').select('*').eq('id', id).single();
        return data ? mapProjectFromDB(data) : null;
    },

    getStudentById: async (id: string) => {
        if (!supabase) return null;
        const { data } = await supabase.from('students').select('*').eq('id', id).single();
        if (!data) return null;
        return {
            id: data.id,
            name: data.name,
            email: data.email,
            cedula: data.cedula,
            projectId: data.project_id,
            programId: data.program_id
        };
    },

    // Funciones administrativas de catálogos (solo Supabase)
    addStatus: async (p: any) => { const id=generateId(); await supabase?.from('statuses').insert([{id, ...p}]); return {id, ...p}; },
    addFormat: async (p: any) => { const id=generateId(); await supabase?.from('formats').insert([{id, ...p}]); return {id, ...p}; },
    addProgram: async (p: any) => { const id=generateId(); await supabase?.from('programs').insert([{id, ...p}]); return {id, ...p}; },
    addTeacherRole: async (p: any) => { const id=generateId(); await supabase?.from('teacher_roles').insert([{id, ...p}]); return {id, ...p}; },
    updateStatus: async (p: any) => { await supabase?.from('statuses').update({name: p.name}).eq('id', p.id); return p; },
    updateFormat: async (p: any) => { await supabase?.from('formats').update({name: p.name}).eq('id', p.id); return p; },
    updateProgram: async (p: any) => { await supabase?.from('programs').update({name: p.name}).eq('id', p.id); return p; },
    updateTeacherRole: async (p: any) => { await supabase?.from('teacher_roles').update({name: p.name}).eq('id', p.id); return p; },
    deleteStatus: async (id: string) => { await supabase?.from('statuses').delete().eq('id', id); },
    deleteFormat: async (id: string) => { await supabase?.from('formats').delete().eq('id', id); },
    deleteProgram: async (id: string) => { await supabase?.from('programs').delete().eq('id', id); },
    deleteTeacherRole: async (id: string) => { await supabase?.from('teacher_roles').delete().eq('id', id); }
};

import React, { useState, useEffect, useCallback } from 'react';
import { db } from '../services/database';
import { Project, Student, Teacher, TeacherRole, Status, Format, ProjectTeacher } from '../types';
import { Modal } from '../components/Modal';
import { ConfirmationDialog } from '../components/ConfirmationDialog';
import { PlusIcon, EditIcon, TrashIcon } from '../components/Icons';
import { useAuth } from '../contexts/AuthContext';

const ProjectForm: React.FC<{
    project: Partial<Project> | null;
    onSave: (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => Promise<void>;
    onClose: () => void;
    statuses: Status[];
    formats: Format[];
    teachers: Teacher[];
    allStudents: Student[];
    roles: TeacherRole[];
    initialAssignments: ProjectTeacher[];
    initialStudentIds: string[];
    canEditDetails: boolean;
    gradeInfo: { canGrade: boolean, reviewerRole: string | null };
}> = ({ project, onSave, onClose, statuses, formats, teachers, allStudents, roles, initialAssignments, initialStudentIds, canEditDetails, gradeInfo }) => {
    const { isAdmin } = useAuth();
    const [formData, setFormData] = useState<Partial<Project>>({});
    const [assignments, setAssignments] = useState<Array<{teacherId: string, roleId: string, tempId: number}>>([]);
    const [assignedStudentIds, setAssignedStudentIds] = useState<string[]>([]);
    const [newAssignment, setNewAssignment] = useState({ teacherId: '', roleId: '' });
    const [selectedStudentId, setSelectedStudentId] = useState('');
    const [isSaving, setIsSaving] = useState(false);

    useEffect(() => {
        const initialData: Partial<Project> = {
            title: '', presentationDate: '', filesUrl: '',
            statusId: statuses[0]?.id || '', formatId: formats[0]?.id || '',
            isApprovedByDirector: false, writtenGradeReviewer1: null,
            presentationGradeReviewer1: null, writtenGradeReviewer2: null,
            presentationGradeReviewer2: null, finalGrade: null, ...project
        };
        setFormData(initialData);
        setAssignments(initialAssignments.map(a => ({ teacherId: a.teacherId, roleId: a.roleId, tempId: Math.random() })));
        setAssignedStudentIds(initialStudentIds);
        setNewAssignment({ teacherId: '', roleId: '' });
        setSelectedStudentId('');
    }, [project, initialAssignments, initialStudentIds, statuses]);

    const calculateFinalAverage = (data: Partial<Project>) => {
        const g1w = data.writtenGradeReviewer1;
        const g1p = data.presentationGradeReviewer1;
        const g2w = data.writtenGradeReviewer2;
        const g2p = data.presentationGradeReviewer2;

        let avg1 = 0; let count1 = 0;
        if (g1w !== null) { avg1 += g1w; count1++; }
        if (g1p !== null) { avg1 += g1p; count1++; }
        const finalAvg1 = count1 > 0 ? avg1 / count1 : null;

        let avg2 = 0; let count2 = 0;
        if (g2w !== null) { avg2 += g2w; count2++; }
        if (g2p !== null) { avg2 += g2p; count2++; }
        const finalAvg2 = count2 > 0 ? avg2 / count2 : null;

        if (finalAvg1 !== null && finalAvg2 !== null) {
            return Number(((finalAvg1 + finalAvg2) / 2).toFixed(2));
        } else if (finalAvg1 !== null) {
            return Number(finalAvg1.toFixed(2));
        } else if (finalAvg2 !== null) {
            return Number(finalAvg2.toFixed(2));
        }
        return null;
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value, type } = e.target;
        let finalValue: any = value;
        if (type === 'number') {
            if (value === '') finalValue = null;
            else {
                const num = parseFloat(value);
                if (num < 1.0 || num > 5.0) return;
                finalValue = num;
            }
        }
        setFormData(prev => {
            const nextData = { ...prev, [name]: finalValue };
            if (name.includes('Grade')) nextData.finalGrade = calculateFinalAverage(nextData);
            return nextData;
        });
    };

    const handleAddAssignment = () => {
        if (newAssignment.teacherId && newAssignment.roleId) {
            if (assignments.some(a => a.teacherId === newAssignment.teacherId)) { alert('Docente ya asignado.'); return; }
            setAssignments(prev => [...prev, {...newAssignment, tempId: Math.random()}]);
            setNewAssignment({ teacherId: '', roleId: '' });
        }
    };

    const handleAddStudent = () => {
        if (selectedStudentId && !assignedStudentIds.includes(selectedStudentId)) {
            setAssignedStudentIds(prev => [...prev, selectedStudentId]);
            setSelectedStudentId('');
        }
    };

    const removeStudent = (id: string) => setAssignedStudentIds(prev => prev.filter(sid => sid !== id));

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (isSaving) return;
        if (!formData.title?.trim() || !formData.presentationDate) { alert("Título y Fecha obligatorios."); return; }
        setIsSaving(true);
        try { 
            await onSave(formData, assignments, assignedStudentIds); 
            onClose(); 
        }
        catch (error: any) { console.error(error); alert("Fallo al guardar: " + error.message); }
        finally { setIsSaving(false); }
    };

    const getTeacherName = (id: string) => teachers.find(t => t.id === id)?.name || 'Desconocido';
    const getRoleName = (id: string) => roles.find(r => r.id === id)?.name || 'Desconocido';
    const getStudentName = (id: string) => {
        const found = allStudents.find(s => s.id === id);
        return found ? found.name : 'Estudiante no encontrado';
    };

    const canGradeReviewer1 = isAdmin || (gradeInfo.canGrade && gradeInfo.reviewerRole?.toLowerCase().includes('1'));
    const canGradeReviewer2 = isAdmin || (gradeInfo.canGrade && gradeInfo.reviewerRole?.toLowerCase().includes('2'));

    return (
        <form onSubmit={handleSubmit} className="space-y-6 max-h-[75vh] overflow-y-auto pr-2 scrollbar-thin">
            <div className="space-y-4">
                <div>
                    <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-1 ml-1">Título Institucional</label>
                    <input type="text" name="title" value={formData.title || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50 font-bold" disabled={!canEditDetails} />
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-1 ml-1">Fecha de Radicación</label>
                        <input type="date" name="presentationDate" value={formData.presentationDate || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails}/>
                    </div>
                    <div>
                        <label className="block text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-1 ml-1">Estado del Proyecto</label>
                        <select name="statusId" value={formData.statusId || ''} onChange={handleChange} required className="block w-full px-4 py-2.5 border border-gray-300 rounded-xl shadow-sm focus:ring-uninunez-orange focus:border-uninunez-orange text-sm disabled:bg-gray-50" disabled={!canEditDetails && !gradeInfo.canGrade}>
                            {statuses.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                        </select>
                    </div>
                </div>
            </div>

            <div className="bg-uninunez-onix/5 p-5 rounded-2xl border border-uninunez-onix/10 space-y-4">
                <div className="flex justify-between items-center border-b border-uninunez-onix/10 pb-3">
                    <h4 className="text-[10px] font-black text-uninunez-onix uppercase tracking-widest">Calificaciones Académicas</h4>
                    <div className="flex items-center gap-2">
                        <span className="text-[9px] font-bold text-uninunez-ash uppercase">Promedio:</span>
                        <div className="bg-uninunez-orange text-white px-3 py-1 rounded-lg text-xs font-black shadow-md min-w-[50px] text-center">{formData.finalGrade?.toFixed(2) || '0.00'}</div>
                    </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className={`p-4 rounded-xl border-2 transition-all ${canGradeReviewer1 ? 'bg-white border-uninunez-teal/30 shadow-sm' : 'bg-gray-100 border-transparent opacity-60'}`}>
                        <p className="text-[10px] font-black text-uninunez-teal uppercase mb-3 flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-uninunez-teal"></span> Evaluador 1</p>
                        <div className="grid grid-cols-2 gap-3">
                            <input type="number" step="0.1" name="writtenGradeReviewer1" placeholder="Escrito" value={formData.writtenGradeReviewer1 ?? ''} onChange={handleChange} disabled={!canGradeReviewer1} className="w-full text-xs border rounded-lg p-2 font-bold" />
                            <input type="number" step="0.1" name="presentationGradeReviewer1" placeholder="Sust." value={formData.presentationGradeReviewer1 ?? ''} onChange={handleChange} disabled={!canGradeReviewer1} className="w-full text-xs border rounded-lg p-2 font-bold" />
                        </div>
                    </div>
                    <div className={`p-4 rounded-xl border-2 transition-all ${canGradeReviewer2 ? 'bg-white border-uninunez-teal/30 shadow-sm' : 'bg-gray-100 border-transparent opacity-60'}`}>
                        <p className="text-[10px] font-black text-uninunez-teal uppercase mb-3 flex items-center gap-2"><span className="w-2 h-2 rounded-full bg-uninunez-teal"></span> Evaluador 2</p>
                        <div className="grid grid-cols-2 gap-3">
                            <input type="number" step="0.1" name="writtenGradeReviewer2" placeholder="Escrito" value={formData.writtenGradeReviewer2 ?? ''} onChange={handleChange} disabled={!canGradeReviewer2} className="w-full text-xs border rounded-lg p-2 font-bold" />
                            <input type="number" step="0.1" name="presentationGradeReviewer2" placeholder="Sust." value={formData.presentationGradeReviewer2 ?? ''} onChange={handleChange} disabled={!canGradeReviewer2} className="w-full text-xs border rounded-lg p-2 font-bold" />
                        </div>
                    </div>
                </div>
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-4 ml-1">Integrantes (Estudiantes)</h4>
                <div className="flex flex-wrap gap-2 mb-3">
                    {assignedStudentIds.length > 0 ? assignedStudentIds.map(sid => (
                        <div key={sid} className="flex items-center bg-white px-3 py-2 rounded-xl border border-gray-200 shadow-sm">
                            <span className="text-[10px] font-bold text-gray-700 mr-2">{getStudentName(sid)}</span>
                            {canEditDetails && <button type="button" onClick={() => removeStudent(sid)} className="text-red-400 hover:text-red-600"><TrashIcon className="h-3.5 w-3.5"/></button>}
                        </div>
                    )) : <p className="text-[10px] text-gray-400 italic py-2">No hay estudiantes vinculados todavía.</p>}
                </div>
                {canEditDetails && (
                    <div className="flex gap-2">
                        <select value={selectedStudentId} onChange={(e) => setSelectedStudentId(e.target.value)} className="flex-grow border border-gray-200 rounded-xl px-3 py-2 text-sm bg-gray-50">
                            <option value="">Vincular estudiante...</option>
                            {allStudents.filter(s => (!s.projectId || assignedStudentIds.includes(s.id)) && !assignedStudentIds.includes(s.id)).map(s => (
                                <option key={s.id} value={s.id}>{s.name} ({s.cedula})</option>
                            ))}
                        </select>
                        <button type="button" onClick={handleAddStudent} className="bg-uninunez-orange text-white px-5 rounded-xl text-[10px] font-black uppercase hover:bg-uninunez-orangeLight">Añadir</button>
                    </div>
                )}
            </div>

            <div className="pt-4 border-t border-gray-100">
                <h4 className="text-[10px] font-black text-uninunez-ash uppercase tracking-widest mb-4 ml-1">Asignaciones (Docentes)</h4>
                <div className="space-y-2 mb-4">
                    {assignments.map(a => (
                        <div key={a.tempId} className="flex justify-between items-center bg-white px-4 py-2.5 rounded-xl border border-gray-100 shadow-sm">
                            <span className="text-[11px] font-bold text-gray-700">{getTeacherName(a.teacherId)} — <span className="text-uninunez-teal uppercase font-black tracking-widest">{getRoleName(a.roleId)}</span></span>
                            {canEditDetails && <button type="button" onClick={() => setAssignments(prev => prev.filter(x => x.tempId !== a.tempId))} className="text-red-400 p-1"><TrashIcon className="h-4 w-4"/></button>}
                        </div>
                    ))}
                </div>
                {canEditDetails && (
                    <div className="grid grid-cols-1 sm:grid-cols-7 gap-2">
                        <select value={newAssignment.teacherId} onChange={(e) => setNewAssignment(p => ({...p, teacherId: e.target.value}))} className="sm:col-span-3 border border-gray-200 rounded-xl px-3 py-2 text-sm bg-gray-50">
                            <option value="">Seleccionar Docente...</option>
                            {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                        </select>
                        <select value={newAssignment.roleId} onChange={(e) => setNewAssignment(p => ({...p, roleId: e.target.value}))} className="sm:col-span-3 border border-gray-200 rounded-xl px-3 py-2 text-sm bg-gray-50">
                            <option value="">Rol...</option>
                            {roles.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                        </select>
                        <button type="button" onClick={handleAddAssignment} className="sm:col-span-1 bg-uninunez-orange text-white rounded-xl text-[10px] font-black uppercase">OK</button>
                    </div>
                )}
            </div>

            <div className="flex justify-end gap-3 pt-6 border-t sticky bottom-0 bg-white/95 pb-2">
                <button type="button" onClick={onClose} disabled={isSaving} className="px-6 py-3 border-2 border-gray-100 rounded-xl text-[10px] font-black uppercase text-gray-400">Cancelar</button>
                <button type="submit" disabled={isSaving} className={`px-10 py-3 rounded-xl text-[10px] font-black uppercase shadow-xl transition-all ${isSaving ? 'bg-gray-400' : 'bg-uninunez-orange hover:bg-uninunez-orangeLight text-white'}`}>
                    {isSaving ? 'Guardando...' : project ? 'Actualizar Proyecto' : 'Guardar Proyecto'}
                </button>
            </div>
        </form>
    );
};

export const ProjectsPage: React.FC = () => {
    const { isAdmin, canEditProject, canGradeProject } = useAuth();
    const [projects, setProjects] = useState<Project[]>([]);
    const [students, setStudents] = useState<Student[]>([]);
    const [teachers, setTeachers] = useState<Teacher[]>([]);
    const [roles, setRoles] = useState<TeacherRole[]>([]);
    const [statuses, setStatuses] = useState<Status[]>([]);
    const [formats, setFormats] = useState<Format[]>([]);
    const [projectTeachers, setProjectTeachers] = useState<ProjectTeacher[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingProject, setEditingProject] = useState<Project | null>(null);
    const [deletingProject, setDeletingProject] = useState<Project | null>(null);
    const [userPerms, setUserPerms] = useState<Record<string, any>>({});

    const loadData = useCallback(async () => {
        setIsLoading(true);
        try {
            const [p, s, t, r, st, f, pt] = await Promise.all([
                db.getProjects(), 
                db.getStudents(), 
                db.getTeachers(),
                db.getTeacherRoles(), 
                db.getStatuses(), 
                db.getFormats(),
                db.getProjectTeachers()
            ]);

            const perms: any = {};
            for(const project of p) {
                perms[project.id] = { 
                    canEdit: await canEditProject(project.id), 
                    grade: await canGradeProject(project.id) 
                };
            }

            setProjects([...p]); 
            setStudents([...s]); 
            setTeachers([...t]); 
            setRoles([...r]); 
            setStatuses([...st]); 
            setFormats([...f]); 
            setProjectTeachers([...pt]); 
            setUserPerms(perms);
        } catch (error) { 
            console.error("Error al cargar datos:", error); 
        } finally { 
            setIsLoading(false); 
        }
    }, [canEditProject, canGradeProject]);

    useEffect(() => { loadData(); }, [loadData]);

    const handleSave = async (projectData: Partial<Project>, assignments: Array<{teacherId: string, roleId: string}>, studentIds: string[]) => {
        try {
            let savedProject: Project;

            // 1. Guardar/Actualizar Proyecto principal en Supabase
            if (editingProject) {
                savedProject = await db.updateProject({ ...editingProject, ...projectData } as Project);
            } else {
                savedProject = await db.addProject(projectData as Omit<Project, 'id'>);
            }

            // Si el proyecto se guardó con éxito, actualizamos relaciones secundarias
            if (!editingProject || isAdmin || userPerms[savedProject.id]?.canEdit) {
                // 2. Docentes - Eliminar antiguos y re-añadir en la tabla puente
                await db.deleteProjectTeachersByProject(savedProject.id);
                for (const a of assignments) {
                    await db.addProjectTeacher({ projectId: savedProject.id, teacherId: a.teacherId, roleId: a.roleId });
                }

                // 3. Estudiantes - Sincronizar columna project_id en la tabla students
                const sts = await db.getStudents();

                // Desvincular antiguos: a los que estaban vinculados pero ya no están en la lista actual
                const currentlyLinked = sts.filter(s => s.projectId === savedProject.id);
                for (const s of currentlyLinked) {
                    if (!studentIds.includes(s.id)) {
                        await db.updateStudent({ ...s, projectId: null });
                    }
                }

                // Vincular actuales: establecer el project_id a los seleccionados
                for (const sid of studentIds) {
                    const s = sts.find(st => st.id === sid);
                    if (s) {
                        await db.updateStudent({ ...s, projectId: savedProject.id });
                    }
                }
            }

            // Recarga completa de Supabase para confirmar visibilidad de nombres y datos
            await loadData(); 
            setIsModalOpen(false);
            setEditingProject(null);
        } catch (err: any) { 
            console.error("Fallo crítico en handleSave:", err); 
            alert("No se pudo completar el guardado en Supabase: " + err.message);
        }
    };

    const handleDelete = async () => { 
        if (deletingProject) { 
            await db.deleteProject(deletingProject.id); 
            await loadData(); 
            setDeletingProject(null); 
        } 
    };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-black text-uninunez-onix font-display uppercase tracking-tight">Banco de Proyectos</h1>
                    <p className="text-uninunez-ash text-sm font-medium">Gestión integral de expedientes académicos vinculados a Supabase.</p>
                </div>
                {isAdmin && (
                    <button 
                        onClick={() => { setEditingProject(null); setIsModalOpen(true); }} 
                        className="bg-uninunez-orange text-white px-6 py-3 rounded-xl flex items-center text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-uninunez-orangeLight transition-all active:scale-95"
                    >
                        <PlusIcon className="h-5 w-5 mr-2"/> Nuevo Proyecto
                    </button>
                )}
            </div>

            <div className="bg-white shadow-sm border border-gray-100 rounded-3xl overflow-hidden min-h-[400px]">
                {isLoading ? (
                    <div className="flex flex-col items-center justify-center py-20 space-y-4">
                        <div className="w-12 h-12 border-4 border-uninunez-orange border-t-transparent rounded-full animate-spin"></div>
                        <p className="text-xs font-black text-uninunez-ash uppercase tracking-widest">Consultando Supabase...</p>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-gray-50/50 border-b border-gray-100">
                                <tr>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Proyecto</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Autores (Estudiantes)</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest">Estado</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-center">Nota Final</th>
                                    <th className="px-8 py-5 text-[10px] font-black text-gray-400 uppercase tracking-widest text-right">Acciones</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-50">
                                {projects.map(p => {
                                    // Filtramos los estudiantes cuyo projectId coincida con el de este proyecto
                                    const linkedStudents = students.filter(s => s.projectId === p.id);
                                    return (
                                        <tr key={p.id} className="hover:bg-gray-50/50 transition-colors group">
                                            <td className="px-8 py-6">
                                                <div className="text-sm font-bold text-uninunez-onix group-hover:text-uninunez-orange transition-colors">{p.title}</div>
                                                <div className="text-[10px] text-gray-400 mt-1 uppercase font-bold tracking-tight">Radicación: {p.presentationDate}</div>
                                            </td>
                                            <td className="px-8 py-6">
                                                <div className="flex flex-wrap gap-1">
                                                    {linkedStudents.length > 0 ? linkedStudents.map(s => (
                                                        <span key={s.id} className="inline-block px-2 py-0.5 bg-jade-50 text-[10px] font-bold text-jade-700 rounded uppercase border border-jade-100 shadow-sm">{s.name}</span>
                                                    )) : <span className="text-[10px] text-gray-300 italic">Sin estudiantes vinculados</span>}
                                                </div>
                                            </td>
                                            <td className="px-8 py-6">
                                                <span className="px-3 py-1.5 text-[10px] font-black uppercase tracking-wider rounded-lg bg-uninunez-teal/10 text-uninunez-teal">{statuses.find(s => s.id === p.statusId)?.name || 'PENDIENTE'}</span>
                                            </td>
                                            <td className="px-8 py-6 text-center">
                                                <span className={`px-3 py-1 text-sm font-black rounded-lg ${p.finalGrade ? (p.finalGrade >= 3.0 ? 'bg-jade-100 text-jade-700' : 'bg-red-100 text-red-600') : 'bg-gray-100 text-gray-400'}`}>{p.finalGrade?.toFixed(2) || '---'}</span>
                                            </td>
                                            <td className="px-8 py-6 text-right">
                                                <div className="flex justify-end gap-2">
                                                    {(isAdmin || userPerms[p.id]?.canEdit || userPerms[p.id]?.grade?.canGrade) && (
                                                        <button onClick={() => { setEditingProject(p); setIsModalOpen(true); }} className="p-2.5 bg-uninunez-teal/5 text-uninunez-teal hover:bg-uninunez-teal hover:text-white rounded-xl shadow-sm transition-all"><EditIcon className="h-5 w-5"/></button>
                                                    )}
                                                    {(isAdmin || userPerms[p.id]?.canEdit) && <button onClick={() => setDeletingProject(p)} className="p-2.5 bg-red-50 text-red-500 hover:bg-red-500 hover:text-white rounded-xl shadow-sm transition-all"><TrashIcon className="h-5 w-5"/></button>}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })}
                                {!isLoading && projects.length === 0 && (
                                    <tr>
                                        <td colSpan={5} className="text-center py-20">
                                            <p className="text-uninunez-ash italic text-sm">No hay registros en Supabase.</p>
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} title={editingProject ? 'Expediente de Proyecto' : 'Nuevo Registro Académico'}>
                {isModalOpen && (
                    <ProjectForm 
                        project={editingProject} 
                        onSave={handleSave} 
                        onClose={() => setIsModalOpen(false)} 
                        statuses={statuses} 
                        formats={formats} 
                        teachers={teachers} 
                        allStudents={students} 
                        roles={roles} 
                        initialAssignments={editingProject ? projectTeachers.filter(pt => pt.projectId === editingProject.id) : []} 
                        initialStudentIds={editingProject ? students.filter(s => s.projectId === editingProject.id).map(s => s.id) : []}
                        canEditDetails={editingProject ? (isAdmin || userPerms[editingProject.id]?.canEdit) : true} 
                        gradeInfo={editingProject ? userPerms[editingProject.id]?.grade : {canGrade: false, reviewerRole: null}} 
                    />
                )}
            </Modal>
            <ConfirmationDialog isOpen={!!deletingProject} onClose={() => setDeletingProject(null)} onConfirm={handleDelete} title="Confirmar Eliminación" message="¿Desea eliminar permanentemente este expediente? Esta acción borrará todas las notas y vínculos en Supabase." />
        </div>
    );
};

// @ts-ignore - Importación directa desde CDN
import { createClient } from 'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm';
import { Project, Student, Teacher, ProjectTeacher, Format, TeacherRole, Status, Program, User } from '../types';

const supabaseUrl = (import.meta as any).env?.VITE_SUPABASE_URL || '';
const supabaseAnonKey = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || '';

export const isSupabaseConfigured = !!(supabaseUrl && supabaseAnonKey && supabaseUrl.startsWith('http'));

// @ts-ignore
export const supabase = isSupabaseConfigured 
    ? createClient(supabaseUrl, supabaseAnonKey) 
    : null;

const generateId = (): string => Date.now().toString(36) + Math.random().toString(36).substring(2);

// Datos iniciales para siembra (solo se usan si Supabase está vacío)
const initialSeeds = {
    programs: [{ id: '1', name: 'Ingeniería de Sistemas' }, { id: '2', name: 'Derecho' }, { id: '3', name: 'Medicina' }],
