import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { db } from '../services/database';
import { Status, Format, TeacherRole, Program, Faculty } from '../types';
import { EditIcon, TrashIcon, PlusIcon } from '../components/Icons';
import { ConfirmationDialog } from '../components/ConfirmationDialog';
import { useAuth } from '../contexts/AuthContext';

type EntityType = 'status' | 'format' | 'role' | 'program' | 'faculty';
type Entity = Status | Format | TeacherRole | Program | Faculty;

interface SettingsListProps<T extends Entity> {
    title: string;
    items: T[];
    placeholder: string;
    faculties?: Faculty[];
    onAdd: (name: string, extraId?: string) => void;
    onUpdate: (item: T) => void;
    onDelete: (item: T) => void;
    onReorder: (items: T[]) => void;
    isLoading?: boolean;
    type: EntityType;
}

const SettingsList = <T extends {id: string; name: string, facultyId?: string, sortOrder?: number}>({ 
    title, items, placeholder, faculties, onAdd, onUpdate, onDelete, onReorder, isLoading, type 
}: SettingsListProps<T>) => {
    const { isAdmin } = useAuth();
    const [newItemName, setNewItemName] = useState('');
    const [selectedFacultyId, setSelectedFacultyId] = useState('');
    const [editingItem, setEditingItem] = useState<T | null>(null);
    const [isManualOrder, setIsManualOrder] = useState(false);

    // Determinar si los items ya tienen un orden personalizado para activar el modo manual por defecto
    useEffect(() => {
        const hasCustomOrder = items.some(item => item.sortOrder && item.sortOrder < 99);
        if (hasCustomOrder) setIsManualOrder(true);
    }, [items.length === 0]);

    // Lógica de ordenación según el modo seleccionado
    const sortedItems = useMemo(() => {
        const list = [...items];
        if (isManualOrder) {
            return list.sort((a, b) => (a.sortOrder || 99) - (b.sortOrder || 99) || a.name.localeCompare(b.name));
        }
        return list.sort((a, b) => a.name.localeCompare(b.name));
    }, [items, isManualOrder]);

    const handleAdd = () => {
        if (newItemName.trim()) {
            if (type === 'program' && !selectedFacultyId) {
                alert("Debes seleccionar una facultad para el programa.");
                return;
            }
            onAdd(newItemName.trim(), selectedFacultyId);
            setNewItemName('');
            setSelectedFacultyId('');
        }
    };

    const handleUpdate = () => {
        if (editingItem && editingItem.name.trim()){
            onUpdate(editingItem);
            setEditingItem(null);
        }
    }

    const moveItem = (index: number, direction: 'up' | 'down') => {
        const newItems = [...sortedItems];
        const targetIndex = direction === 'up' ? index - 1 : index + 1;

        if (targetIndex < 0 || targetIndex >= newItems.length) return;

        // Intercambiar elementos
        const temp = newItems[index];
        newItems[index] = newItems[targetIndex];
        newItems[targetIndex] = temp;

        // Reasignar sortOrder basado en la nueva posición (1-based index)
        const updatedItems = newItems.map((item, idx) => ({
            ...item,
            sortOrder: idx + 1
        }));

        onReorder(updatedItems);
    };

    return (
        <div className="bg-white rounded-3xl shadow-sm border border-gray-100 flex flex-col h-full overflow-hidden transition-all hover:shadow-md">
            {/* Header con Selector de Orden */}
            <div className="p-5 bg-gray-50/50 border-b border-gray-100">
                <div className="flex justify-between items-start mb-3">
                    <h2 className="text-[10px] font-black text-uninunez-onix uppercase tracking-[0.2em] font-display">{title}</h2>
                    {isAdmin && (
                        <div className="flex bg-white rounded-lg p-0.5 border border-gray-200 shadow-sm">
                            <button 
                                onClick={() => setIsManualOrder(false)}
                                className={`px-2 py-1 text-[8px] font-black rounded-md transition-all ${!isManualOrder ? 'bg-uninunez-teal text-white shadow-sm' : 'text-gray-400 hover:text-uninunez-teal'}`}
                            >
                                A-Z
                            </button>
                            <button 
                                onClick={() => setIsManualOrder(true)}
                                className={`px-2 py-1 text-[8px] font-black rounded-md transition-all ${isManualOrder ? 'bg-uninunez-orange text-white shadow-sm' : 'text-gray-400 hover:text-uninunez-orange'}`}
                            >
                                MANUAL
                            </button>
                        </div>
                    )}
                </div>
                <p className="text-[8px] text-uninunez-ash font-bold uppercase tracking-widest flex items-center gap-1">
                    <svg className="w-2.5 h-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d={isManualOrder ? "M4 6h16M4 12h16M4 18h16" : "M3 4h13M3 8h9m-9 4h6m4 0l4-4m0 0l4 4m-4-4v12"} />
                    </svg>
                    Orden {isManualOrder ? 'Personalizado' : 'Alfabético'}
                </p>
            </div>

            <div className="p-5 flex-grow">
                {isAdmin && (
                    <div className="space-y-2 mb-6">
                        <input
                            type="text"
                            value={newItemName}
                            onChange={(e) => setNewItemName(e.target.value)}
                            placeholder={placeholder}
                            className="w-full bg-gray-50 border border-gray-200 rounded-xl py-2.5 px-4 text-xs font-bold focus:ring-1 focus:ring-uninunez-orange outline-none transition-all"
                        />
                        {type === 'program' && faculties && (
                            <select 
                                value={selectedFacultyId}
                                onChange={(e) => setSelectedFacultyId(e.target.value)}
                                className="w-full bg-gray-50 border border-gray-200 rounded-xl py-2.5 px-4 text-xs font-bold focus:ring-1 focus:ring-uninunez-teal outline-none"
                            >
                                <option value="">Seleccionar Facultad...</option>
                                {faculties.map(f => <option key={f.id} value={f.id}>{f.name}</option>)}
                            </select>
                        )}
                        <button 
                            onClick={handleAdd} 
                            disabled={!newItemName.trim()}
                            className="w-full bg-uninunez-orange text-white py-2.5 rounded-xl shadow-lg hover:bg-uninunez-orangeLight disabled:bg-gray-200 disabled:shadow-none transition-all flex justify-center items-center font-black text-[10px] uppercase tracking-widest"
                        >
                            <PlusIcon className="h-4 w-4 mr-2"/> AGREGAR
                        </button>
                    </div>
                )}

                {isLoading ? (
                    <div className="py-10 flex justify-center">
                        <div className="w-6 h-6 border-2 border-uninunez-orange border-t-transparent rounded-full animate-spin"></div>
                    </div>
                ) : (
                    <ul className="space-y-2">
                        {sortedItems.length === 0 ? (
                            <li className="py-8 text-center text-[10px] text-gray-400 font-bold uppercase tracking-widest italic">Sin registros</li>
                        ) : (
                            sortedItems.map((item, index) => (
                                <li key={item.id} className="group flex justify-between items-center bg-gray-50/40 hover:bg-white hover:shadow-sm border border-transparent hover:border-gray-100 p-3 rounded-xl transition-all">
                                    <div className="flex items-center gap-3">
                                        {isAdmin && isManualOrder && (
                                            <div className="flex flex-col border-r pr-2 border-gray-200">
                                                <button 
                                                    onClick={() => moveItem(index, 'up')} 
                                                    disabled={index === 0}
                                                    className="p-1 text-gray-400 hover:text-uninunez-orange disabled:opacity-20 transition-colors"
                                                    title="Subir"
                                                >
                                                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 15l7-7 7 7" /></svg>
                                                </button>
                                                <button 
                                                    onClick={() => moveItem(index, 'down')} 
                                                    disabled={index === sortedItems.length - 1}
                                                    className="p-1 text-gray-400 hover:text-uninunez-orange disabled:opacity-20 transition-colors"
                                                    title="Bajar"
                                                >
                                                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M19 9l-7 7-7-7" /></svg>
                                                </button>
                                            </div>
                                        )}
                                        <div className="flex flex-col">
                                            {editingItem?.id === item.id && isAdmin ? (
                                                <input 
                                                    type="text"
                                                    value={editingItem.name}
                                                    onChange={(e) => setEditingItem({...editingItem, name: e.target.value})}
                                                    onBlur={handleUpdate}
                                                    onKeyDown={(e) => e.key === 'Enter' && handleUpdate()}
                                                    autoFocus
                                                    className="text-xs font-black text-uninunez-teal bg-transparent border-b-2 border-uninunez-teal focus:outline-none"
                                                />
                                            ) : (
                                                <>
                                                    <span className="text-xs font-bold text-uninunez-ash group-hover:text-uninunez-onix transition-colors leading-tight">{item.name}</span>
                                                    {type === 'program' && item.facultyId && (
                                                        <span className="text-[8px] font-black text-uninunez-teal uppercase mt-0.5">
                                                            {faculties?.find(f => f.id === item.facultyId)?.name || 'Sin Facultad'}
                                                        </span>
                                                    )}
                                                </>
                                            )}
                                        </div>
                                    </div>

                                    {isAdmin && (
                                        <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity ml-2">
                                            <button onClick={() => setEditingItem(item)} className="p-1.5 text-uninunez-teal hover:bg-uninunez-teal/10 rounded-lg"><EditIcon className="h-3.5 w-3.5" /></button>
                                            <button onClick={() => onDelete(item)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg"><TrashIcon className="h-3.5 w-3.5" /></button>
                                        </div>
                                    )}
                                </li>
                            ))
                        )}
                    </ul>
                )}
            </div>
        </div>
    );
};

export const SettingsPage: React.FC = () => {
    const { isAdmin } = useAuth();
    const [faculties, setFaculties] = useState<Faculty[]>([]);
    const [statuses, setStatuses] = useState<Status[]>([]);
    const [formats, setFormats] = useState<Format[]>([]);
    const [roles, setRoles] = useState<TeacherRole[]>([]);
    const [programs, setPrograms] = useState<Program[]>([]);

    const [isLoading, setIsLoading] = useState(true);
    const [deletingItem, setDeletingItem] = useState<{item: Entity, type: EntityType} | null>(null);

    const loadData = useCallback(async () => {
        setIsLoading(true);
        try {
            const [f, s, fo, r, p] = await Promise.all([
                db.getFaculties(),
                db.getStatuses(), 
                db.getFormats(), 
                db.getTeacherRoles(), 
                db.getPrograms()
            ]);
            setFaculties(f);
            setStatuses(s);
            setFormats(fo);
            setRoles(r);
            setPrograms(p);
        } catch (error) {
            console.error("Error cargando catálogos:", error);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => { loadData(); }, [loadData]);

    const handleAdd = async (type: EntityType, name: string, facultyId?: string) => {
        if (!isAdmin) return;
        try {
            if(type === 'faculty') await db.addFaculty({ name });
            else if(type === 'status') await db.addStatus({ name });
            else if(type === 'format') await db.addFormat({ name });
            else if(type === 'role') await db.addTeacherRole({ name });
            else if(type === 'program') await db.addProgram({ name, facultyId: facultyId || '' });
            await loadData();
        } catch (error) {
            alert("Error al crear el registro.");
        }
    };

    const handleUpdate = async (type: EntityType, item: Entity) => {
        if (!isAdmin) return;
        try {
            if(type === 'faculty') await db.updateFaculty(item as Faculty);
            else if(type === 'status') await db.updateStatus(item as Status);
            else if(type === 'format') await db.updateFormat(item as Format);
            else if(type === 'role') await db.updateTeacherRole(item as TeacherRole);
            else if(type === 'program') await db.updateProgram(item as Program);
            await loadData();
        } catch (error) {
            alert("Error al actualizar el registro.");
        }
    };

    const handleReorder = async (type: EntityType, items: Entity[]) => {
        if (!isAdmin) return;

        // Actualización optimista de la UI inmediata
        if(type === 'faculty') setFaculties(items as Faculty[]);
        else if(type === 'status') setStatuses(items as Status[]);
        else if(type === 'format') setFormats(items as Format[]);
        else if(type === 'role') setRoles(items as TeacherRole[]);
        else if(type === 'program') setPrograms(items as Program[]);

        try {
            // Persistir masivamente los nuevos índices de orden
            await Promise.all(items.map(item => {
                if(type === 'faculty') return db.updateFaculty(item as Faculty);
                if(type === 'status') return db.updateStatus(item as Status);
                if(type === 'format') return db.updateFormat(item as Format);
                if(type === 'role') return db.updateTeacherRole(item as TeacherRole);
                if(type === 'program') return db.updateProgram(item as Program);
                return Promise.resolve();
            }));
        } catch (error) {
            console.error("Error persistiendo orden personalizado:", error);
            loadData(); // Revertir en caso de error de red
        }
    };

    const checkAndSetDelete = (type: EntityType, item: Entity) => {
        setDeletingItem({ item, type });
    };

    const handleDelete = async () => {
        if (!deletingItem || !isAdmin) return;
        const { item, type } = deletingItem;
        try {
            if(type === 'faculty') await db.deleteFaculty(item.id);
            else if(type === 'status') await db.deleteStatus(item.id);
            else if(type === 'format') await db.deleteFormat(item.id);
            else if(type === 'role') await db.deleteTeacherRole(item.id);
            else if(type === 'program') await db.deleteProgram(item.id);
            await loadData();
        } finally {
            setDeletingItem(null);
        }
    }

    return (
        <div className="space-y-8 animate-fadeIn max-w-7xl mx-auto px-2 md:px-0">
            <div className="bg-white p-8 rounded-3xl shadow-sm border border-gray-100">
                <h1 className="text-3xl font-black text-uninunez-onix font-display uppercase tracking-tight">Catálogos Maestros</h1>
                <p className="text-sm text-uninunez-ash font-medium mt-1">Gestión centralizada de la estructura académica institucional. Elige entre orden alfabético automático o manual.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                <SettingsList
                    type="faculty"
                    title="Facultades"
                    items={faculties}
                    placeholder="Ej: Fac. de Ingeniería..."
                    isLoading={isLoading}
                    onAdd={(n) => handleAdd('faculty', n)}
                    onUpdate={(i) => handleUpdate('faculty', i)}
                    onDelete={(i) => checkAndSetDelete('faculty', i)}
                    onReorder={(items) => handleReorder('faculty', items)}
                />
                <SettingsList
                    type="program"
                    title="Programas Académicos"
                    items={programs}
                    faculties={faculties}
                    placeholder="Ej: Ing. de Sistemas..."
                    isLoading={isLoading}
                    onAdd={(n, fid) => handleAdd('program', n, fid)}
                    onUpdate={(i) => handleUpdate('program', i)}
                    onDelete={(i) => checkAndSetDelete('program', i)}
                    onReorder={(items) => handleReorder('program', items)}
                />
                <SettingsList
                    type="status"
                    title="Estados del Proyecto"
                    items={statuses}
                    placeholder="Ej: Radicado, Aprobado..."
                    isLoading={isLoading}
                    onAdd={(n) => handleAdd('status', n)}
                    onUpdate={(i) => handleUpdate('status', i)}
                    onDelete={(i) => checkAndSetDelete('status', i)}
                    onReorder={(items) => handleReorder('status', items)}
                />
                <SettingsList
                    type="format"
                    title="Formatos de Trabajo"
                    items={formats}
                    placeholder="Ej: Anteproyecto, Proyecto Final..."
                    isLoading={isLoading}
                    onAdd={(n) => handleAdd('format', n)}
                    onUpdate={(i) => handleUpdate('format', i)}
                    onDelete={(i) => checkAndSetDelete('format', i)}
                    onReorder={(items) => handleReorder('format', items)}
                />
                <SettingsList
                    type="role"
                    title="Roles de Docentes"
                    items={roles}
                    placeholder="Ej: Director, Evaluador..."
                    isLoading={isLoading}
                    onAdd={(n) => handleAdd('role', n)}
                    onUpdate={(i) => handleUpdate('role', i)}
                    onDelete={(i) => checkAndSetDelete('role', i)}
                    onReorder={(items) => handleReorder('role', items)}
                />
            </div>

            <ConfirmationDialog
                isOpen={!!deletingItem}
                onClose={() => setDeletingItem(null)}
                onConfirm={handleDelete}
                title="Confirmar Eliminación"
                message={`¿Estás seguro de que quieres eliminar este registro? Esta acción puede afectar la consistencia de los proyectos vinculados.`}
            />
        </div>
    );
};

import { createClient } from '@supabase/supabase-js';
import { Project, Student, Teacher, ProjectTeacher, Format, TeacherRole, Status, Program, User, Faculty } from '../types';

// Intentar obtener de process.env (Vercel/Node) o import.meta.env (Vite)
const getEnv = (key: string): string => {
    return (window as any).process?.env?.[key] || (import.meta as any).env?.[key] || '';
};

const supabaseUrl = getEnv('VITE_SUPABASE_URL');
const supabaseAnonKey = getEnv('VITE_SUPABASE_ANON_KEY');

export const isSupabaseConfigured = !!(supabaseUrl && supabaseAnonKey && supabaseUrl.startsWith('http'));

// @ts-ignore
export const supabase = isSupabaseConfigured 
    ? createClient(supabaseUrl, supabaseAnonKey) 
    : null;

const generateId = (): string => Date.now().toString(36) + Math.random().toString(36).substring(2);

const bootstrapData = {
    faculties: [{ id: 'f1', name: 'Facultad de Ingeniería' }, { id: 'f2', name: 'Facultad de Salud' }],
    programs: [{ id: '1', name: 'Tecnología en Sistemas', faculty_id: 'f1' }, { id: '2', name: 'Ingeniería de Sistemas', faculty_id: 'f1' }],
    formats: [{ id: '1', name: 'Anteproyecto' }, { id: '2', name: 'Proyecto Final' }],
    teacherRoles: [{ id: '1', name: 'Director' }, { id: '2', name: 'Co-Director' }, { id: '3', name: 'Evaluador 1' }, { id: '4', name: 'Evaluador 2' }],
    statuses: [{ id: '1', name: 'En Proceso' }, { id: '2', name: 'Aprobado' }, { id: '3', name: 'Sustentado' }, { id: '4', name: 'Rechazado' }]
};

// Helper para obtener catálogos con fallback si falla sort_order
async function fetchCatalog(table: string) {
    if (!supabase) return [];

    // Intento 1: Con sort_order
    let { data, error } = await supabase.from(table).select('*').order('sort_order', { ascending: true }).order('name', { ascending: true });

    // Si falla (probablemente porque la columna no existe en Supabase todavía)
    if (error) {
        console.warn(`Fallback: Falló ordenamiento por sort_order en ${table}. Reintentando alfabético.`);
        const { data: fallbackData } = await supabase.from(table).select('*').order('name', { ascending: true });
        return fallbackData || [];
    }

    return data || [];
}

export const db = {
    initializeDB: async () => {
        if (!supabase) return;
        try {
            const checkAndSeed = async (table: string, data: any[]) => {
                const { count, error } = await supabase!.from(table).select('*', { count: 'exact', head: true });
                if (!error && count === 0) {
                    await supabase!.from(table).insert(data);
                }
            };
            await checkAndSeed('faculties', bootstrapData.faculties);
            await checkAndSeed('statuses', bootstrapData.statuses);
            await checkAndSeed('formats', bootstrapData.formats);
            await checkAndSeed('programs', bootstrapData.programs);
            await checkAndSeed('teacher_roles', bootstrapData.teacherRoles);
        } catch (e) { 
            console.error("Error al inicializar base de datos remota:", e); 
        }
    },

    checkConnection: async () => {
        if (!supabase) return false;
        try {
            const { error } = await supabase.from('statuses').select('id').limit(1);
            return !error;
        } catch { return false; }
    },

    // --- Facultades ---
    getFaculties: async (): Promise<Faculty[]> => {
        const data = await fetchCatalog('faculties');
        return data.map((f: any) => ({ ...f, sortOrder: f.sort_order }));
    },
    addFaculty: async (f: { name: string, sortOrder?: number }) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const id = generateId();
        const payload: any = { id, name: f.name };
        if (f.sortOrder) payload.sort_order = f.sortOrder;
        await supabase.from('faculties').insert([payload]);
        return { id, ...f };
    },
    updateFaculty: async (f: Faculty) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const payload: any = { name: f.name };
        if (f.sortOrder !== undefined) payload.sort_order = f.sortOrder;
        await supabase.from('faculties').update(payload).eq('id', f.id);
        return f;
    },
    deleteFaculty: async (id: string) => {
        if (supabase) await supabase.from('faculties').delete().eq('id', id);
    },

    // --- Programas ---
    getPrograms: async (): Promise<Program[]> => {
        const data = await fetchCatalog('programs');
        return data.map((p: any) => ({ id: p.id, name: p.name, facultyId: p.faculty_id, sortOrder: p.sort_order }));
    },
    addProgram: async (p: { name: string, facultyId: string, sortOrder?: number }) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const id = generateId();
        const payload: any = { id, name: p.name, faculty_id: p.facultyId };
        if (p.sortOrder) payload.sort_order = p.sortOrder;
        await supabase.from('programs').insert([payload]);
        return { id, ...p };
    },
    updateProgram: async (p: Program) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const payload: any = { name: p.name, faculty_id: p.facultyId };
        if (p.sortOrder !== undefined) payload.sort_order = p.sortOrder;
        await supabase.from('programs').update(payload).eq('id', p.id);
        return p;
    },
    deleteProgram: async (id: string) => {
        if (supabase) await supabase.from('programs').delete().eq('id', id);
    },

    // --- Proyectos ---
    getProjects: async (): Promise<Project[]> => {
        if (!supabase) return [];
        const { data } = await supabase.from('projects').select('*').order('presentation_date', { ascending: false });
        return (data || []).map(p => ({
            id: p.id, title: p.title, presentationDate: p.presentation_date, filesUrl: p.files_url,
            statusId: p.status_id, formatId: p.format_id, programId: p.program_id,
            isApprovedByDirector: p.is_approved_by_director, finalGrade: p.final_grade,
            writtenGradeReviewer1: p.written_grade_reviewer1, presentationGradeReviewer1: p.presentation_grade_reviewer1,
            writtenGradeReviewer2: p.written_grade_reviewer2, presentationGradeReviewer2: p.presentation_grade_reviewer2
        }));
    },
    getProjectById: async (id: string): Promise<Project | null> => {
        if (!supabase) return null;
        const { data } = await supabase.from('projects').select('*').eq('id', id).single();
        if (!data) return null;
        return {
            id: data.id, title: data.title, presentationDate: data.presentation_date, filesUrl: data.files_url,
            statusId: data.status_id, formatId: data.format_id, programId: data.program_id,
            isApprovedByDirector: data.is_approved_by_director, finalGrade: data.final_grade,
            writtenGradeReviewer1: data.written_grade_reviewer1, presentationGradeReviewer1: data.presentation_grade_reviewer1,
            writtenGradeReviewer2: data.written_grade_reviewer2, presentationGradeReviewer2: data.presentation_grade_reviewer2
        };
    },
    addProject: async (p: Omit<Project, 'id'>) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const id = generateId();
        await supabase.from('projects').insert([{ 
            id, title: p.title, presentation_date: p.presentationDate, files_url: p.filesUrl, 
            status_id: p.statusId, format_id: p.formatId, program_id: p.programId 
        }]);
        return { ...p, id } as Project;
    },
    updateProject: async (p: Project) => {
        if (!supabase) throw new Error("Supabase no configurado");
        await supabase.from('projects').update({ 
            title: p.title, presentation_date: p.presentationDate, files_url: p.filesUrl, 
            status_id: p.statusId, format_id: p.formatId, program_id: p.programId, 
            final_grade: p.finalGrade, written_grade_reviewer1: p.writtenGradeReviewer1, 
            presentation_grade_reviewer1: p.presentationGradeReviewer1, 
            written_grade_reviewer2: p.writtenGradeReviewer2, 
            presentation_grade_reviewer2: p.presentationGradeReviewer2 
        }).eq('id', p.id);
        return p;
    },
    deleteProject: async (id: string) => {
        if (!supabase) return;
        await supabase.from('project_teachers').delete().eq('project_id', id);
        await supabase.from('students').update({ project_id: null }).eq('project_id', id);
        await supabase.from('projects').delete().eq('id', id);
    },

    // --- Estudiantes ---
    getStudents: async (): Promise<Student[]> => {
        if (!supabase) return [];
        const { data } = await supabase.from('students').select('*').order('name', { ascending: true });
        return (data || []).map((s: any) => ({ id: s.id, name: s.name, email: s.email, cedula: s.cedula, projectId: s.project_id, programId: s.program_id }));
    },
    getStudentById: async (id: string): Promise<Student | null> => {
        if (!supabase) return null;
        const { data } = await supabase.from('students').select('*').eq('id', id).single();
        if (!data) return null;
        return { id: data.id, name: data.name, email: data.email, cedula: data.cedula, projectId: data.project_id, programId: data.program_id };
    },
    addStudent: async (s: Omit<Student, 'id'>) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const id = generateId();
        const userId = generateId();
        await supabase.from('students').insert([{ id, name: s.name, email: s.email, cedula: s.cedula, program_id: s.programId }]);
        await supabase.from('users').insert([{ id: userId, username: s.name, password: s.cedula, role: 'student', student_id: id }]);
        return { ...s, id } as Student;
    },
    updateStudent: async (s: Student) => {
        if (!supabase) throw new Error("Supabase no configurado");
        await supabase.from('students').update({ name: s.name, email: s.email, cedula: s.cedula, program_id: s.programId, project_id: s.projectId }).eq('id', s.id);
        return s;
    },
    deleteStudent: async (id: string) => {
        if (!supabase) return;
        await supabase.from('users').delete().eq('student_id', id);
        await supabase.from('students').delete().eq('id', id);
    },

    // --- Docentes ---
    getTeachers: async (): Promise<Teacher[]> => {
        if (!supabase) return [];
        const { data } = await supabase.from('teachers').select('*').order('name', { ascending: true });
        return data || [];
    },
    addTeacher: async (t: Omit<Teacher, 'id'>) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const id = generateId();
        const userId = generateId();
        await supabase.from('teachers').insert([{ id, name: t.name, email: t.email, cedula: t.cedula }]);
        await supabase.from('users').insert([{ id: userId, username: t.name, password: t.cedula, role: 'teacher', teacher_id: id }]);
        return { ...t, id } as Teacher;
    },
    updateTeacher: async (t: Teacher) => {
        if (!supabase) throw new Error("Supabase no configurado");
        await supabase.from('teachers').update({ name: t.name, email: t.email, cedula: t.cedula }).eq('id', t.id);
        await supabase.from('users').update({ username: t.name, password: t.cedula }).eq('teacher_id', t.id);
        return t;
    },
    deleteTeacher: async (id: string) => {
        if (!supabase) return;
        await supabase.from('users').delete().eq('teacher_id', id);
        await supabase.from('teachers').delete().eq('id', id);
    },

    // --- Usuarios y Autenticación ---
    getUserByUsername: async (username: string): Promise<User | null> => {
        if (!supabase) return null;
        const { data } = await supabase.from('users').select('*').eq('username', username).single();
        return data ? { ...data, teacherId: data.teacher_id, studentId: data.student_id } : null;
    },
    getUsers: async (): Promise<User[]> => {
        if (!supabase) return [];
        const { data } = await supabase.from('users').select('*');
        return (data || []).map((u: any) => ({ ...u, teacherId: u.teacher_id, studentId: u.student_id }));
    },
    deleteUser: async (id: string) => {
        if (supabase) await supabase.from('users').delete().eq('id', id);
    },

    // --- Relación Proyecto-Docente ---
    getProjectTeachers: async (): Promise<ProjectTeacher[]> => {
        if (!supabase) return [];
        const { data } = await supabase.from('project_teachers').select('*');
        return (data || []).map((pt: any) => ({ id: pt.id, projectId: pt.project_id, teacherId: pt.teacher_id, role_id: pt.role_id }));
    },
    addProjectTeacher: async (pt: Omit<ProjectTeacher, "id">) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const id = generateId();
        await supabase.from('project_teachers').insert([{ id, project_id: pt.projectId, teacher_id: pt.teacherId, role_id: pt.roleId }]);
        return { ...pt, id };
