export const notificationService = {
  /**
   * Genera el contenido del correo usando Gemini para que sea profesional y empático.
   */
  async generateEmailContent(action: 'create' | 'update' | 'grade' | 'delete', data: {
    project: Project,
    recipients: string[],
    statusName?: string,
    roleName?: string
  }) {
    const prompt = `Actúa como el sistema de notificaciones de la Corporación Universitaria Rafael Núñez. 
    Escribe un correo electrónico formal y profesional en HTML para informar sobre la siguiente acción: ${action}.
    Proyecto: "${data.project.title}"
    Estado actual: ${data.statusName || 'N/A'}
    Nota final (si aplica): ${data.project.finalGrade || 'Pendiente'}

    El correo debe incluir un saludo cordial, los detalles del cambio y un mensaje de ánimo o instrucciones siguientes. 
    Usa los colores de la institución: Naranja (#F07E12) y Turquesa (#249A8C).
    Retorna exclusivamente el código HTML del cuerpo del correo.`;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt
      });
      return response.text || "Contenido no disponible.";
    } catch (error) {
      console.error("Error generando contenido con Gemini:", error);
      return `<h3>Actualización de Proyecto</h3><p>Se han realizado cambios en el proyecto: ${data.project.title}</p>`;
    }
  },

  /**
   * Simula el envío de correo. 
   * Nota: En producción Vercel, esto llamaría a una API Route que use 'nodemailer' con los datos SMTP.
   */
  async sendEmail(to: string[], subject: string, html: string) {
    console.log(`%c[SMTP SEND] Destinatarios: ${to.join(', ')}`, 'color: #F07E12; font-weight: bold');
    console.log(`%cAsunto: ${subject}`, 'color: #249A8C');

    // Simulamos latencia de red del servidor SMTP
    await new Promise(resolve => setTimeout(resolve, 1500));

    // Aquí se integraría la llamada a la Vercel Function / API
    return { success: true, timestamp: new Date().toISOString() };
  },

  /**
   * Notifica a todos los interesados en un proyecto
   */
  async notifyProjectChange(
    action: 'create' | 'update' | 'grade' | 'delete',
    project: Project,
    students: Student[],
    teachers: { teacher: Teacher, role: TeacherRole }[],
    statusName?: string
  ) {
    const studentEmails = students.map(s => s.email).filter(Boolean);
    const teacherEmails = teachers.map(t => t.teacher.email).filter(Boolean);
    const allEmails = [...new Set([...studentEmails, ...teacherEmails])];

    if (allEmails.length === 0) return;

    const subject = `NOTIFICACIÓN: ${action === 'create' ? 'Nuevo Proyecto Radicado' : 'Actualización de Proyecto'} - ${project.title}`;
    const html = await this.generateEmailContent(action, { project, recipients: allEmails, statusName });

    await this.sendEmail(allEmails, subject, html);

    // Retornamos para feedback en UI
    return {
        count: allEmails.length,
        recipients: allEmails
    };
  }
};

import { createClient } from '@supabase/supabase-js';
import { Project, Student, Teacher, ProjectTeacher, Format, TeacherRole, Status, Program, User, Faculty } from '../types';
import { notificationService } from './notificationService';

const getEnv = (key: string): string => {
    return (window as any).process?.env?.[key] || (import.meta as any).env?.[key] || '';
};

const supabaseUrl = getEnv('VITE_SUPABASE_URL');
const supabaseAnonKey = getEnv('VITE_SUPABASE_ANON_KEY');

export const isSupabaseConfigured = !!(supabaseUrl && supabaseAnonKey && supabaseUrl.startsWith('http'));

// @ts-ignore
export const supabase = isSupabaseConfigured 
    ? createClient(supabaseUrl, supabaseAnonKey) 
    : null;

const generateId = (): string => Date.now().toString(36) + Math.random().toString(36).substring(2);

async function fetchCatalog(table: string) {
    if (!supabase) return [];
    let { data, error } = await supabase.from(table).select('*').order('sort_order', { ascending: true }).order('name', { ascending: true });
    if (error) {
        const { data: fallbackData } = await supabase.from(table).select('*').order('name', { ascending: true });
        return fallbackData || [];
    }
    return data || [];
}

export const db = {
    initializeDB: async () => {
        if (!supabase) return;
        try {
            const { count } = await supabase!.from('statuses').select('*', { count: 'exact', head: true });
            if (count === 0) {
                // Seed logic here if needed
            }
        } catch (e) { console.error(e); }
    },

    checkConnection: async () => {
        if (!supabase) return false;
        try {
            const { error } = await supabase.from('statuses').select('id').limit(1);
            return !error;
        } catch { return false; }
    },

    // --- Auxiliares para Notificaciones ---
    async getProjectContext(projectId: string) {
        const allStudents = await this.getStudents();
        const projectStudents = allStudents.filter(s => s.projectId === projectId);

        const allPT = await this.getProjectTeachers();
        const ptForProject = allPT.filter(pt => pt.projectId === projectId);

        const allTeachers = await this.getTeachers();
        const allRoles = await this.getTeacherRoles();

        const teachersWithRoles = ptForProject.map(pt => ({
            teacher: allTeachers.find(t => t.id === pt.teacherId)!,
            role: allRoles.find(r => r.id === pt.roleId)!
        })).filter(item => item.teacher && item.role);

        return { students: projectStudents, teachers: teachersWithRoles };
    },

    // --- Proyectos ---
    getProjects: async (): Promise<Project[]> => {
        if (!supabase) return [];
        const { data } = await supabase.from('projects').select('*').order('presentation_date', { ascending: false });
        return (data || []).map(p => ({
            id: p.id, title: p.title, presentationDate: p.presentation_date, filesUrl: p.files_url,
            statusId: p.status_id, formatId: p.format_id, programId: p.program_id,
            isApprovedByDirector: p.is_approved_by_director, finalGrade: p.final_grade,
            writtenGradeReviewer1: p.written_grade_reviewer1, presentationGradeReviewer1: p.presentation_grade_reviewer1,
            writtenGradeReviewer2: p.written_grade_reviewer2, presentationGradeReviewer2: p.presentation_grade_reviewer2
        }));
    },

    addProject: async (p: Omit<Project, 'id'>) => {
        if (!supabase) throw new Error("Supabase no configurado");
        const id = generateId();
        const { data, error } = await supabase.from('projects').insert([{ 
            id, title: p.title, presentation_date: p.presentationDate, files_url: p.filesUrl, 
            status_id: p.statusId, format_id: p.formatId, program_id: p.programId 
        }]).select();

        if (error) throw error;
        return { ...p, id } as Project;
    },

    updateProject: async (p: Project) => {
        if (!supabase) throw new Error("Supabase no configurado");

        // Obtener estado anterior para comparar si hubo cambios críticos
        const { data: oldProject } = await supabase.from('projects').select('status_id, final_grade').eq('id', p.id).single();

        const { error } = await supabase.from('projects').update({ 
            title: p.title, presentation_date: p.presentationDate, files_url: p.filesUrl, 
            status_id: p.statusId, format_id: p.formatId, program_id: p.programId, 
            final_grade: p.finalGrade, written_grade_reviewer1: p.writtenGradeReviewer1, 
            presentation_grade_reviewer1: p.presentationGradeReviewer1, 
            written_grade_reviewer2: p.writtenGradeReviewer2, 
            presentation_grade_reviewer2: p.presentationGradeReviewer2 
        }).eq('id', p.id);

        if (error) throw error;

        // Disparar Notificación si cambió el estado o la nota
        if (oldProject && (oldProject.status_id !== p.statusId || oldProject.final_grade !== p.finalGrade)) {
            const context = await db.getProjectContext(p.id);
            const statuses = await db.getStatuses();
            const statusName = statuses.find(s => s.id === p.statusId)?.name;

            // Acción asíncrona "fire and forget" para no bloquear la UI
            notificationService.notifyProjectChange(
                oldProject.final_grade !== p.finalGrade ? 'grade' : 'update',
                p, context.students, context.teachers, statusName
            );
        }

        return p;
    },

    deleteProject: async (id: string) => {
        if (!supabase) return;
        const context = await db.getProjectContext(id);
        const { data: project } = await supabase.from('projects').select('*').eq('id', id).single();

        await supabase.from('project_teachers').delete().eq('project_id', id);
        await supabase.from('students').update({ project_id: null }).eq('project_id', id);
        await supabase.from('projects').delete().eq('id', id);

        if (project) {
            notificationService.notifyProjectChange('delete', project as any, context.students, context.teachers);
        }
    },

    // --- Resto de métodos de catálogos ---
    getFaculties: async () => (await fetchCatalog('faculties')).map((f: any) => ({ ...f, sortOrder: f.sort_order })),
    getPrograms: async () => (await fetchCatalog('programs')).map((p: any) => ({ id: p.id, name: p.name, facultyId: p.faculty_id, sortOrder: p.sort_order })),
    getStudents: async () => (await (supabase?.from('students').select('*').order('name')) || {data: []}).data?.map((s: any) => ({ id: s.id, name: s.name, email: s.email, cedula: s.cedula, projectId: s.project_id, programId: s.program_id })) || [],
    getTeachers: async () => (await (supabase?.from('teachers').select('*').order('name')) || {data: []}).data || [],
    getProjectTeachers: async () => (await (supabase?.from('project_teachers').select('*')) || {data: []}).data?.map((pt: any) => ({ id: pt.id, projectId: pt.project_id, teacherId: pt.teacher_id, roleId: pt.role_id })) || [],
    getStatuses: async () => (await fetchCatalog('statuses')).map((d: any) => ({ ...d, sortOrder: d.sort_order })),
    getFormats: async () => (await fetchCatalog('formats')).map((d: any) => ({ ...d, sortOrder: d.sort_order })),
    getTeacherRoles: async () => (await fetchCatalog('teacher_roles')).map((d: any) => ({ ...d, sortOrder: d.sort_order })),
    getUserByUsername: async (username: string) => {
        const { data } = await supabase!.from('users').select('*').eq('username', username).single();
        return data ? { ...data, teacherId: data.teacher_id, studentId: data.student_id } : null;
    },
    getUsers: async () => (await supabase!.from('users').select('*')).data?.map((u: any) => ({ ...u, teacherId: u.teacher_id, studentId: u.student_id })) || [],

    addFaculty: async (f: any) => { const id = generateId(); await supabase!.from('faculties').insert([{ id, name: f.name, sort_order: f.sortOrder || 99 }]); return { id, ...f }; },
    addProgram: async (p: any) => { const id = generateId(); await supabase!.from('programs').insert([{ id, name: p.name, faculty_id: p.facultyId, sort_order: p.sortOrder || 99 }]); return { id, ...p }; },
    addStudent: async (s: any) => { const id = generateId(); const userId = generateId(); await supabase!.from('students').insert([{ id, name: s.name, email: s.email, cedula: s.cedula, program_id: s.programId }]); await supabase!.from('users').insert([{ id: userId, username: s.name, password: s.cedula, role: 'student', student_id: id }]); return { ...s, id }; },
    addTeacher: async (t: any) => { const id = generateId(); const userId = generateId(); await supabase!.from('teachers').insert([{ id, name: t.name, email: t.email, cedula: t.cedula }]); await supabase!.from('users').insert([{ id: userId, username: t.name, password: t.cedula, role: 'teacher', teacher_id: id }]); return { ...t, id }; },
